INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0000', 'ALM', 'ALM-0000 : This  process step number is not supported. Please check the process step number.', 'ALM-0000 : 지원되지 않는 STEP입니다. 다시 확인 하십시요.', 'ALM-0000 : Diese Prozess Ablaufnummer wird nicht unterstuetzt. Bitte ueberpruefen sie die Prozess-Ablaufnummer.', 'ADMIN', '20050725162507', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0001', 'ALM', 'ALM-0001 :  A required field is empty. Please enter a valid value.', 'ALM-0001 : 이 항목은 필요한 필드 입니다. 입력 바랍니다.', 'ALM-0001 : Ein erforderliches Eingabefeld ist leer. Bitte geben Sie gueltige Daten ein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0002', 'ALM', 'ALM-0002 : This Alarm ID exists already.', 'ALM-0002 : 이미 존재하는 알람 메시지입니다.', 'ALM-0002 : Diese Alarm ID existiert bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0003', 'ALM', 'ALM-0003 : This Alarm ID does not exist.', 'ALM-0003 : 존재하지 않는 알람 메시지입니다.', 'ALM-0003 : Diese Alarm ID existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0004', 'ALM', 'ALM-0004 : A fatal database error occurred. Please contact an administrator.', 'ALM-0004 : Database 작업중 오류가 발생 하였습니다. 관리자에게 문의 바랍니다.', 'ALM-0004 : Ein schwerer Datenbankfehler ist aufgetreten. Bitte kontaktieren Sie einen Administrator.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0005', 'ALM', 'ALM-0005 : This resource does not exist. Enter an existing resource or let the field empty.', 'ALM-0005 : 존재하지 않는 장비입니다. 존재하는 장비를 입력하거나 공백으로 두십시요.', 'ALM-0005 : Diese Resource existiert nicht. Geben sie eine gueltige Resource ein oder lassen Sie das Eingabefeld leer.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0006', 'ALM', 'ALM-0006 : This item does not exist in GCM Table.', 'ALM-0006 : 이 아이템은 GCM 테이블에 존재하지 않습니다.', 'ALM-0006 : Dieser Eintrag ist nicht in den GCM Tabelle enthalten.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0007', 'ALM', 'ALM-0007 : This data is not numeric. Only numeric data is valid.', 'ALM-0007 : 이 데이터는 숫자가 아닙니다. 숫자를 입력해주세요.', 'ALM-0007 : Diese Eingabe ist nicht numerisch. Nur numerische Daten sind erlaubt.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0008', 'ALM', 'ALM-0008 : This function is not supported by MESplus.', 'ALM-0008 : MESplus에서 지원하지 않는 기능입니다.', 'ALM-0008 : Diese Funktion wird nicht durch MESplus unterstuetzt.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0009', 'ALM', 'ALM-0009 : Invalid alarm level flag. Valid values are "I", "W", or "E".', 'ALM-0009 : 유효하지 않은 알람 수준 플래그 값입니다. "I", "W" 또는 "E"이어야만 합니다.', 'ALM-0009 : Ungueltiger Alarm-Level-Flag. Gueltige Werte sind "I", "W" oder "E".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0010', 'ALM', 'ALM-0010 : Invalid alarm send flag. Valid values are "Y", "N", or " ".', 'ALM-0010 : 유효하지 않은 알람 SEND 플래그 값입니다. "Y", "N" 또는 " "이어야만 합니다.', 'ALM-0010 : Ungueltiger Alarm-Sende-Flag. Gueltige Werte sind "Y", "N" oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0011', 'ALM', 'ALM-0011 : The user does not belong to an alarm group.', 'ALM-0011 : 존재하지 않는 사용자가 알람을 받을 사용자로 설정되었습니다.', 'ALM-0011 : Der Benutzer gehoert keiner Alarmgruppe an.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0012', 'ALM', 'ALM-0012 :  The user group does not belong to an alarm group.', 'ALM-0012 : 존재하지 않는 사용자그룹이 알람을 받을 사용자그룹으로 설정되었습니다.', 'ALM-0012 : Die Benutzergruppe ist keiner Alarmgruppe zugeordnet.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0013', 'ALM', 'ALM-0013 : Invalid alarm action flag. Valid values are "Y", "N", or " ".', 'ALM-0013 : 유효하지 않은 알람 ACTION 플래그 값입니다. "Y", "N" 또는 " "이어야만 합니다.', 'ALM-0013 : Ungueltiger Flag Alarm-Action. Gueltige Werte sind "Y", "N"  oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0014', 'ALM', 'ALM-0014 : Hold Lot is setup for an alarm action, so hold code must be set.', 'ALM-0014 : 알람 ACTION으로 HOLD가 설정되어있습니다. 따라서 HOLD CODE가 반드시 설정 되어야 합니다.', 'ALM-0014 : Hold-Lot ist als Alarm-Action konfiguriert, deshalb muss der Halte-Code gesetzt werden..', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0015', 'ALM', 'ALM-0015 : Hold code does not exist.', 'ALM-0015 : 존재하지 않는 HOLD CODE 입니다.', 'ALM-0015 : Hold-Code existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0016', 'ALM', 'ALM-0016 : Invalid  resource event flag . Valid values are "Y", "N", or " ".', 'ALM-0016 : 유효하지 않은 장비 이벤트 설정 플래그 값입니다. "Y", "N" 또는 " "이어야만 합니다.', 'ALM-0016 : Ungueltiger Resource-Event-Flag. Gueltige Werte sind ""Y", "N" oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0017', 'ALM', 'ALM-0017 : Alarm action triggers a resource event, so resource event must be set.', 'ALM-0017 : 알람 ACTION으로 장비 이벤트를 발생시키도록 설정되어있습니다. 따라서 장비 이벤트가 반드시 설정 되어야 합니다.', 'ALM-0017 : Alarm-Action loest einen Resource-Event aus, deshalb muss der Resource-Event gesetzt sein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0018', 'ALM', 'ALM-0018 : The resource event does not exist.', 'ALM-0018 : 존재하지 않는 장비 이벤트 입니다.', 'ALM-0018 : Das Resource-Event existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0019', 'ALM', 'ALM-0019 : Invalid clear resource event flag value. Clear resource event flag must be "Y", "N", or " ".', 'ALM-0019 : 유효하지 않은 장비 이벤트 CLEAR 플래그 값입니다. "Y", "N" 또는 " "이어야만 합니다.', 'ALM-0019 : Ungueltiger Clear-Resource-Event-Flag. Gueltige Werte sind "Y", "N"  oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0020', 'ALM', 'ALM-0020 : Alarm code and alarm text are empty. At least one of them must be specified.', 'ALM-0020 : 알람 코드와 알람 내용이 모두 비어 있습니다. 둘중 하나는 정의되어 있어야 알람을 일으킬 수 있습니다.', 'ALM-0020 : Alarmcode und Alarmtext sind leer, zumindest eines dieser Felder muss sepzifiziert werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0021', 'ALM', 'ALM-0021 : Invalid alarm type. Alarm type must be one of "L(Lot)", "E(Equip)", "A(AMHS)", or "S(SPC)".', 'ALM-0021 : 유효하지 않은 알람 종류입니다. "L(Lot)", "E(Equip)", "A(AMHS)", 또는 "S(SPC)" 중에 하나이어야 합니다.', 'ALM-0021 : Ungueltiger Alarmtyp. Gueltige sind "L(Lot)", "E(Equip)", "A(AMHS)" oder "S(SPC)".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0022', 'ALM', 'ALM-0022 : The alarm is aleady cleared.', 'ALM-0022 : 이미 CLEAR된 알람 입니다.', 'ALM-0022 : Dieser Alarm wurde bereits geloescht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0023', 'ALM', 'ALM-0023 : The alarm is not raised. Check alarm code, raise date time, lot id, and equip id.', 'ALM-0023 : 발생하지 않은 알람입니다. 알람 코드, 발생시간, LOT ID, 장비 ID를 확인하십시요.', 'ALM-0023 : Der Alarm wurde nicht ausgeloest. Bitte ueberpruefen Sie den Alarmcode,  Ausloesezeitpunkt, Los ID und Equipment ID.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0024', 'ALM', 'ALM-0024 : No Alarm history.', 'ALM-0024 : 해당 알람 이력이 없습니다.', 'ALM-0024 : Keine Alarm-Historie.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0025', 'ALM', 'ALM-0025 : Alarm send to user flag is YES but no username is specified.', 'ALM-0025 : 특정 사용자에게 알람을 보내는 플래그가 YES로 설정되었으나, 사용자명을 설정하지 않았습니다.', 'ALM-0025 : Das Flag Send-Alarm-to-User ist gesetzt, der User-Name ist jedoch nicht spezifiziert.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0026', 'ALM', 'ALM-0026 : Alarm send to user group flag is YES but no user group is specified.', 'ALM-0026 : 특정 사용자 그룹에게 알람을 보내는 플래그가 YES로 설정되었으나, 사용자 그룹을 설정하지 않았습니다.', 'ALM-0026 : Das Flag Send-Alarrm-to-Usere-Group ist gesetzt, jedoch wurde keine User-Group spezifiziert.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0027', 'ALM', 'ALM-0027 : The resource does not exist. Specify existing resource ID only for resource alarms or let the field be empty.', 'ALM-0027 : 존재하지 않는 장비입니다. 장비 알람의 경우에만 존재하는 장비명을 설정해야합니다. 장비 알람이 아닌 경우는 공백으로 두십시요.', 'ALM-0027 : Die Resource existiert nicht. Die Resource muss nur fuer Resource-Alarme spezifiziert werden, ansonsten kann sie leer gelassen werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0028', 'ALM', 'ALM-0028 : This engineer note is not setup.', 'ALM-0028 : 해당 엔지니어 노트가 없습니다.', 'ALM-0028 : Die Benutzer-Notiz ist nicht eingerichtet.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0029', 'ALM', 'ALM-0029 : The engineer note is already exist.', 'ALM-0029 : 이미 존재하는 엔지니어 노트입니다.', 'ALM-0029 : Die Benutzer-Notiz existiert bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0030', 'ALM', 'ALM-0030 : This engineer note is not exist.', 'ALM-0030 : 존재하지 않는 엔지니어 노트입니다.', 'ALM-0030 : Die Benutzer-Notiz existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0031', 'ALM', 'ALM-0031 : Alarm send to user flag is NO, so username is not allowed.', 'ALM-0031 : 특정 사용자에게 알람을 보내는 플래그가 YES로 설정되지 않아, 사용자명을 설정 할 수 없습니다.', 'ALM-0031 : Das Flag Send-Alarm-to-User ist nicht gesetzt, deshalb muss der Benutzername leer sein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0032', 'ALM', 'ALM-0032 : Alarm send to user group flag is NO, so user group is not allowed.', 'ALM-0032 : 특정 사용자 그룹에게 알람을 보내는 플래그가 YES로 설정되지 않아, 사용자 그룹을 설정 할 수 없습니다.', 'ALM-0032 : Das Flag Send-Alarm-to-User-Group ist nicht gesetzt, deshalb muss der User-Group-Name leer sein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0033', 'ALM', 'ALM-0033 : This data format is invalid. Please check data.', 'ALM-0033 : 이 DATA의 형식이 유효하지 않습니다. DATA를 확인하세요.', 'ALM-0033 : Das Datenformat ist ungueltig. Bitte ueberpruefen Sie die Eingabe.', 'ADMIN', '20050726162752', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0034', 'ALM', 'ALM-0034 : The resource alarm is not setup. Please check the setup.', 'ALM-0034 : 이 장비 알람은 정의되어 있지 않습니다.', 'ALM-0034 : Der Resourcen-Alarm ist nicht konfiguriert. Bitte ueberpruefen Sie das Setup.', 'ADMIN', '20071011090417', 'ADMIN', '20081217162237');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0035', 'ALM', 'ALM-0035 : Invalid alarm type value. Alarm Type must be "N", "R", or "A".', 'ALM-0035 : 유효하지 않는 알람 종류 값입니다. 알람 종류는 "N", "R",  "A" 중 하나이어야 합니다.', 'ALM-0035 : Ungueltiger Alarmtyp. Gueltige Werte sind "N", "R" oder "A".', 'ADMIN', '20071213054356', 'ADMIN', '20081217165008');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0037', 'ALM', 'ALM-0037 : This alarm relationship already exists.', 'ALM-0037 : 이미 존재하는 Alarm Relationship 입니다.', 'ALM-0037 : Diese Alarm-Relationship existiert bereits.', 'ADMIN', '20071213055155', 'ADMIN', '20081217165641');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0038', 'ALM', 'ALM-0038 : The alarm relationship does not exist.', 'ALM-0038 : 존재하지 않는 Alarm Relationship입니다.', 'ALM-0038 : Diese Alarm-Relationship existiet nicht.', 'ADMIN', '20071213055530', 'ADMIN', '20081217165702');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0039', 'ALM', 'ALM-0039 : Can not generate file for e-mail.', 'ALM-0039 : 이메일 파일을 생성할 수 없습니다.', 'ALM-0039 : Die E-Mail Nachricht kann nicht erzeugt werden.', 'ADMIN', '20080201003456', 'ADMIN', '20081217170059');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0040', 'ALM', 'ALM-0040 : Can not delete alarm. Check alarm to MFO/Resource relation setup.', 'ALM-0040 : 알람을 삭제할 수 없습니다. Alarm to MFO/Resource Relation Setup을 확인하세요.', 'ALM-0040 : Alarm kann nicht geloescht werden . Bitte ueberpruefen Sie das MFO-Resource-Relation-Setup.', 'ADMIN', '20080225072012', 'ADMIN', '20081217170329');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0041', 'ALM', 'ALM-0041 : Can not create directory to save file attached to alarm.', 'ALM-0041 : 알람에 첨부되는 파일을 저장할 디렉토리를 생성할 수 없습니다.', 'ALM-0041 : Verzeichnis kann nicht erstellt werden, um die am Alarm angehaengte Datei zu speichern.', 'ADMIN', '20110210124601', 'ADMIN', '20120206102625');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0042', 'ALM', 'ALM-0042 : A fatal error occurred during searching for a file attached to alarm.', 'ALM-0042 : 알람에 첨부된 파일을 찾는 도중 에러가 발생했습니다.', 'ALM-0042 : Ein fataler Fehler ist waehrend der Suche einer Datei, angeschlossen am Alarm, aufgetreten.', 'ADMIN', '20110210124933', 'ADMIN', '20120206102640');
