INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0017', 'BOM', 'BOM-0017 : You cannot delete Part id, becuase it is used by an Order.', 'BOM-0017 : ORDER에서 이 PART가 사용되고 있으므로 PART를 삭제 할 수 없읍니다.', 'BOM-0017 : Diese Part-ID kann nicht geloescht werden da es in einem Order verwendet wird.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0018', 'BOM', 'BOM-0018 : No BOM history.', 'BOM-0018 : BOM 이력이 존재하지 않습니다.', 'BOM-0018 : Es existiert keine BOM-Historie.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0019', 'BOM', 'BOM-0019 : Order count is too small.', 'BOM-0019 : ORDER 수량이 너무 작습니다.', 'BOM-0019 : Der Order-Count ist zu klein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0020', 'BOM', 'BOM-0020 : This Exchange Part does not exist.', 'BOM-0020 : 이 대치 Part ID가 존재하지 않읍니다.', 'BOM-0020 : Dieses Exchange-Part existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0021', 'BOM', 'BOM-0021 : It is not possible to complete warehousing for the Order because it is not in Store request status.', 'BOM-0021 : 이 주문을 입고 완료 할수 없습니다. 입고 대기 중이 아닙니다.', 'BOM-0021 : Es ist nicht moeglich das Warehousing zu kompletieren, da es nicht im Store-Request Status ist.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0022', 'BOM', 'BOM-0022 : ''Mat_Or_Ord_Flag'' is allowed to set only when BOM set is created.', 'BOM-0022 :  ''Mat_Or_Ord_Flag'' 필드는 BOM SET을 생성할때만 지정할수 있습니다.', 'BOM-0022 : Das Flag  Mat-Or-Ord darf nur gesetzt werden, wenn eine BOM-Set angelegt ist.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0023', 'BOM', 'BOM-0023 : This BOM set is already deleted.', 'BOM-0023 :  이 BOM SET은 이미 삭제되었습니다.', 'BOM-0023 : Dieses BOM-Set ist bereits geloescht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0024', 'BOM', 'BOM-0024 : This BOM set is not deleted. The BOM set is still available for use.', 'BOM-0024 : 이 BOM SET은 삭제되지 않았습니다. 현재 사용가능합니다.', 'BOM-0024 : Dieses BOM-Set ist nicht geloescht und steht zur weitern Verfuegung.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0025', 'BOM', 'BOM-0025 : This BOM set version does not exist.', 'BOM-0025 : 이 BOM SET VERSION은 존재하지 않습니다.', 'BOM-0025 : Diese BOM-Set-Version existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0026', 'BOM', 'BOM-0026 : This BOM set version already exists.', 'BOM-0026 : 이 BOM SET VERSION은 이미 존재 합니다.', 'BOM-0026 : Diese BOM-Set-Version existiert bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0027', 'BOM', 'BOM-0027 : The end time is less than the start time. Please check the start time.', 'BOM-0027 : 버전의 적용 만료 날짜가 적용 시작 날짜 이전입니다. 만료 날짜를 시작날짜 이후로 수정해 주세요.', 'BOM-0027 : Die End-Time befindet vor der Start-Time. Bitte ueberpruefen Sie die End-Time.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0028', 'BOM', 'BOM-0028 : The Approval_require_flag is set to "Y", so  the Approval_flag must be specified.', 'BOM-0028 : APPROVAL_REQUIRE_FLAG를 "Y" 로 지정했습니다. APPROVAL_FLAG이 반드시 존재해야 합니다.', 'BOM-0028 : Das Flag Approve-Require ist auf "Y" gesetzt, deshalb muss das  Flag Approve spezifiziert werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0029', 'BOM', 'BOM-0029 : Current user can not approve.  Please check user.', 'BOM-0029 : 현 사용자는 권한이 없습니다. 사용 권한을 확인 하세요', 'BOM-0029 : Der User kann kein Approve erteilen. Bitte ueberpruefen sie den User.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0030', 'BOM', 'BOM-0030 : Not the same  BOM_SET_ID for input and lot.', 'BOM-0030 : 입력된 BOM_SET_ID와 LOT의 BOM_SET_ID가 다릅니다.', 'BOM-0030 : Die BOM_SET_ID fuer Los und Eingabe sind nicht identisch.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0031', 'BOM', 'BOM-0031 : Not the same  BOM_SET_VERSION for input and lot.', 'BOM-0031 : 입력된 BOM_SET_VERSION과 LOT의 BOM_SET_VERSION이 다릅니다.', 'BOM-0031 : Die BOM_SET_VERSION fuer Los und Eingabe sind nicht identisch.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0032', 'BOM', 'BOM-0032 : This material does not exist.', 'BOM-0032 : 이 제품은 존재하지 않습니다.', 'BOM-0032 : Dieses Material existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0033', 'BOM', 'BOM-0033 : Cannot delete this BOM set because of released BOM set version.', 'BOM-0033 : 이 BOM SET은 RELEASE 된 BOM SET이 있으므로 삭제할 수 없습니다.', 'BOM-0033 : Diese BOM-Set kann aufgrund einer bereits erschienen BOM-Set-Version nicht geloescht werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0034', 'BOM', 'BOM-0034 : This Material Qty value is input automatically. The Material Assembly Qty should be same as the Material Qty.', 'BOM-0034 : 이 Material은 자동 입력되는 값입니다. 따라서 Material Attach Qty는 Material Qty와 같아야 합니다.', 'BOM-0034 : Diese Material-Qty wurde automatisch eingegeben. Die Material-Assembly-Qty  muss die gleiche Menge haben als die Material-Qty.', 'ADMIN', '20081201010101', ' ', ' ');
