INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0038', 'BOM', 'BOM-0038 : The BOM Set Version of the Lot is different from the latest BOM Set Version.', 'BOM-0038 : LOT의 BOM_SET_VERSION 이 최신 BOM_SET_VERSION과 일치하지 않습니다.', 'BOM-0038 : Die Lot BOM_SET_VERSION ist von der Letzten unterschiedlich.', 'ADMIN', '20081201010101', ' ', ' ');
