INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('CMN-0001', 'CMN', 'CMN-0001 : This  process step number is not supported. Please check the process step number.', 'CMN-0001 : 지원되지 않는 STEP입니다. 다시 확인 하십시요.', 'CMN-0001 : Dieser Schritt wird nicht unterstuetzt. Bitte Ueberpruefen.', 'ADMIN', '20080624115226', ' ', ' ');
