INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('CMN-0006', 'CMN', 'CMN-0006 : No item was selected. Please select item.', 'CMN-0006 : Item이 선택되지 않았습니다. Item을 선택해 주십시요.', 'CMN-0006 : Es wurde kein Element ausgewaehlt. Bitte waehlen Sie ein Element aus.', 'ADMIN', '20081118184551', 'ADMIN', '20081217171420');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('CMN-0007', 'CMN', 'CMN-0007 : Invalid value to check from database table. Maybe member does not exist or value is Null.', 'CMN-0007 : Database Table 에서 값을 확인하기에는 입력값이 부적합합니다. Member가 없거나 값이 Null 입니다.', 'CMN-0007 : Eingegebener Wert in der Datenbank Tabelle ist ungueltig. Entweder gibt es keinen Member oder der Wert liegt bei Null.', 'ADMIN', '20090209142625', 'ADMIN', '20090416163931');
