INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('CMN-0011', 'CMN', 'CMN-0011 : Future Action is successful. But the original service is skipped.', 'CMN-0011 : Future Action이 성공 하였습니다. 그러나 호출된 서비스는 설정에 의해 처리되지 않았습니다.', 'CMN-0011 : Kuenftige Aktion ist erfolgreich. Aber der urspruengliche Service wurde uebersprungen.', 'ADMIN', '20110602132433', 'ADMIN', '20120206102846');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('CMN-0012', 'CMN', 'CMN-0012 : No message code.', 'CMN-0012 : 메시지 코드가 정의되지 않았습니다.', 'CMN-0012 : Keine Message Code vorhanden.', 'ADMIN', '20110606163202', 'ADMIN', '20120206102903');
