INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0012', 'EDC', 'EDC-0012 : Only "A" or " " is allowed. Please check the value.', 'EDC-0012 : 이 Field는 "A" 또는 " " 값만을 허용 합니다.', 'EDC-0012 : Nur "A" oder " " sind gueltig. Bitte ueberpruefen Sie die Eingabe.', 'ADMIN', '20081201010101', ' ', ' ');
