INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0014', 'EDC', 'EDC-0014 : Sample count range is 1 to 100.', 'EDC-0014 : SAMPLE COUNT의 값의 범위는 1 ~ 100 사이 입니다.', 'EDC-0014 : Der Sample-Count-Range liegt zwischen 1 und 100.', 'ADMIN', '20081201010101', ' ', ' ');
