INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0017', 'EDC', 'EDC-0017 : This collection set is already deleted.', 'EDC-0017 : 이 COLLECTION SET은 이미 삭제되었습니다.', 'EDC-0017 : Diese Collection-Set wurde bereits geloescht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0018', 'EDC', 'EDC-0018 : This Collection set version is not released. so you can use this colletion set version.', 'EDC-0018 : 이 COLLECTION SET은 RELEASE 되지 않아서 현재 사용할 수 없습니다.', 'EDC-0018 : Diese Collection-Set ist noch nicht erschienen, deshalb kann die Collection-Set-Version verwendet werden.', 'ADMIN', '20081201010101', ' ', ' ');
