INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0025', 'EDC', 'EDC-0025 : This operator is not allowed. Please use "+-*/".', 'EDC-0025 : 이 연산자는 허용되지 않습니다. "+-*/"만 허용 됩니다.', 'EDC-0025 : Dieser Operator ist nicht erlaubt. Bitte verwenden Sie  "+-*/".', 'ADMIN', '20081201010101', ' ', ' ');
