INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0029', 'EDC', 'EDC-0029 : No data found to modify. Please check it again.', 'EDC-0029 : 수정할 DATA를 찾을 수 없습니다. 확인후 다시 시도 하세요.', 'EDC-0029 : Die zu modifizierenden Daten koennen nicht gefunden werden. Bitte erneut ueberpruefen.', 'ADMIN', '20081201010101', ' ', ' ');
