INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0035', 'EDC', 'EDC-0035 : Collection Set Versions exist. Please delete collection set versions before.', 'EDC-0035 : COLLECTION SET VERSION 정보가 남아있습니다. COLLECTION SET VERSION을 먼저 삭제하세요.', 'EDC-0035 : Diese Collection-Set-Version existiert bereits. Bitte loeschen Sie die Collection-Set-Version.', 'ADMIN', '20081201010101', ' ', ' ');
