INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0040', 'EDC', 'EDC-0040 : The specified apply end time is prior than apply start time. Please check the apply start and end time.', 'EDC-0040 : 버전의 적용 만료 날짜가 적용 시작 날짜 이전입니다. 만료 날짜를 시작날짜 이후로 수정해 주세요.', 'EDC-0040 : Die spezifizierte Apply-End-Time liegt vor der Apply-Start-Time. Bitte ueberpruefen Sie Apply-Start- und End-Time.', 'ADMIN', '20081201010101', ' ', ' ');
