INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0054', 'EDC', 'EDC-0054 : Spec out Value is occured .Do you want to continue?', 'EDC-0054 : SPEC에 어긋나는 값이 발견되었습니다.  계속하시겠습니까?', 'EDC-0054 : Die Wert entspricht nicht der Spezifikation wollen Sie fortfahren?', 'ADMIN', '20081201010101', ' ', ' ');
