INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0059', 'EDC', 'EDC-0059 : The number of input values exceed max. number of value per unit of Character.', 'EDC-0059 : CHARACTER UNIT 당 설정된 값의 개수보다 실제 입력된 값의 개수가 많습니다.', 'EDC-0059 : Die Anzahl der Input-Values ueberschreitet die erlaubte Anzahl.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0060', 'EDC', 'EDC-0060 : The number of value is not same with the number of value for the Character.', 'EDC-0060 : 몇개 값의 데이타 형식이 올바르지 않습니다. 값을 수정해 주세요.', 'EDC-0060 : Die Anzahl der Wete ist nicht identisch mit der Anzahl von Werten fuer den Character..', 'ADMIN', '20081201010101', ' ', ' ');
