INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0063', 'EDC', 'EDC-0063: Unit ID is not valid . Please input valid Unit ID.', 'EDC-0063: UNIT ID 가 올바르지 않습니다. 올바른 UNIT ID를 입력해 주세요.', 'EDC-0063 : Die Unit ID ist nicht gueltig.', 'ADMIN', '20081201010101', ' ', ' ');
