INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0077', 'EDC', 'EDC-0077 : Inputted Character is not matched with Character of inputted sequence in database.', 'EDC-0077 : Database 상의 character와 입력한 sequece의 Character가 일치 하지 않습니다.', 'EDC-0077 : Eingegebene Character stimmen in der Datenbank nicht mit Character der eingegebenen Sequenz ueberein.', 'ADMIN', '20090619221855', 'ADMIN', '20090619222722');
