INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0026', 'RAS', 'RAS-0026 : This alternative resource group is already set for the resource group.', 'RAS-0026 : 이 대치장비그룹은 이미 이 장비그룹에 설정되어 있습니다.', 'RAS-0026 : Diese alternative Resourcengruppe ist bereits verwendet.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0027', 'RAS', 'RAS-0027 : A MFO(Material-Flow-Oper) relation does already for the resource group. Check MFO(Material-Flow-Oper) relation.', 'RAS-0027 : 이 장비그룹에 대한 DFO(Device-Flow-Oper) 관계가 설정되어 있습니다. DFO(Device-Flow-Oper) 관계를 확인하십시요.', 'RAS-0027 : MFO(Material-Flow-Oper) Beziehung existiert bereits fuer die Resourcenguppe.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0028', 'RAS', 'RAS-0028 : Sub resource flag is set to "Y". The main resource id should be specified.', 'RAS-0028 : 서브장비플래그가 "Y"로 설정되어 있습니다. 메인장비를 반드시 설정해야 합니다.', 'RAS-0028 : Das Subresourcenflag ist auf "Y" gesetzt. Bitte spezifizieren Sie die Hauptresourcen ID.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0029', 'RAS', 'RAS-0029 : Invalid Sub resource sequence. Sequence must be greater than 0', 'RAS-0029 : 유효하지 않은 서브장비시퀀스입니다. 시퀀스는 1부터 시작합니다.', 'RAS-0029 : Ungultige Subresourcensequenz. Der Wert muss groesser 0 sein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0030', 'RAS', 'RAS-0030 : At least oneResource exists in the resource group. Move the resource to another resource group first.', 'RAS-0030 : 장비그룹에 속한 장비가 존재합니다. 먼저 장비를 다른 장비그룹으로 옮긴 후 작업하십시요.', 'RAS-0030 : Zumindest eine Resource existiert in der Resourcengruppe. Verschieben Sie die Resourcen zuerst in eine andere Gruppe.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0031', 'RAS', 'RAS-0031 : This event already exists.', 'RAS-0031 : 이 이벤트는 이미 존재 합니다.', 'RAS-0031 : Dieses Event existiert bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0032', 'RAS', 'RAS-0032 : The event does not exist.', 'RAS-0032 : 존재하지 않는 이벤트입니다.', 'RAS-0032 : Dieses Event existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0033', 'RAS', 'RAS-0033 : At least one Resource exists which is using this event. Remove the event setup from the resource first.', 'RAS-0033 : 이 이벤트를 사용하는 장비가 있어서 지울 수가 없습니다. 먼저 장비로부터 이벤트 설정을 제거해 주십시요.', 'RAS-0033 : Es existiert zumindest eine Resource welche dieses Event verwendet. Verschieben Sie dieses Event zuerst.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0034', 'RAS', 'RAS-0034 : Check Status Flag is defined, it must define Check Status.', 'RAS-0034 : Check Status 플래그가 설정되어 있습니다. Check Status를 반드시 설정해야 합니다.', 'RAS-0034 : Das Check Status Flag ist definiert, geben Sie dafuer einen  Wert ein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0035', 'RAS', 'RAS-0035 : Invalid Check Status Flag. It must be "=", "!", ">", "<", "N" or " ".', 'RAS-0035 : 잘못된 Check Status 플래그입니다. "=", "!", ">", "<", "N", " " 중에 하나이어야 합니다.', 'RAS-0035 : Ungueltiges Flag Check-Status. Gueltige Werte sind "=", "!", ">", "<", "N" oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0036', 'RAS', 'RAS-0036 : Invalid Check Up Down Flag. It must be "=", "!", "N" or " ".', 'RAS-0036 : 잘못된 Check Up Down 플래그입니다. "=", "!", "N", " " 중에 하나이어야 합니다.', 'RAS-0036 : Das Flag Check- Up-Down ist ungueltig. Gueltige Werte sind "=", "!", "N" oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0037', 'RAS', 'RAS-0037 : Check Up Down Flag is defined, it must define Check Up Down status.', 'RAS-0037 : Check Up Down 플래그가 설정되어 있습니다. Check Up Down을 반드시 설정해야 합니다.', 'RAS-0037:  Das Flag Check-Up-Down ist definiert, deshalb muss Check-Up- Down definiert werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0038', 'RAS', 'RAS-0038 : Invalid Up Down Flag. It must be "U" or "D".', 'RAS-0038 : 잘못된 Up Down 플래그입니다. "U" 또는 "D"이어야 합니다.', 'RAS-0038 : Ungueltiges Flag Up-Down. Gueltige Werte sind "U" oder "D".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0039', 'RAS', 'RAS-0039 : Invalid Change Up Down Flag. It must be "Y", "N" or " ".', 'RAS-0039 : 잘못된 Change Up Down 플래그입니다. "Y", "N", " " 중에 하나이어야 합니다.', 'RAS-0039 : Flag Change-Up-Down ist ungueltig. Gueltige Werte sind "Y", "N" oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0040', 'RAS', 'RAS-0040 : Change Up Down Flag is set. Change Up Down must be set.', 'RAS-0040 : Change Up Down 플래그가 설정되어 있습니다. Change Up Down을 반드시 설정해야 합니다.', 'RAS-0040 : Fag Up-Down ist gesetzt', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0041', 'RAS', 'RAS-0041 : Invalid Change Status Flag. It  must be "Y", "N", "+", "-", "O" or " ".', 'RAS-0041 : 잘못된 Change Status 플래그입니다. "Y", "N", "+", "-", "O" or " " 중에 하나이어야 합니다.', 'RAS-0041 : Flag Change-Status is ungueltig. Gueltige Werte sind"Y", "N", "+", "-", "O" oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0042', 'RAS', 'RAS-0042 : Change Status Flag is defined, it must define Change Status.', 'RAS-0042 : Change Status 플래그가 설정되어 있습니다. Change Status를 반드시 설정해야 합니다.', 'RAS-0042 : Das Flag Change-Status ist definiert, deshalb muss Change-Status definiert werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0043', 'RAS', 'RAS-0043 : Chagne Status Flag is defined by "Override", it must define Validation table.', 'RAS-0043 : Change Status 플래그가 "Override"로 설정되어 있습니다. Table Status를 반드시 설정해야 합니다.', 'RAS-0043 : Flag Change-Status ist durch "Override" gesetzt. Die Validation-table muss definiert werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0044', 'RAS', 'RAS-0044 : GCM Table does not exist. Create GCM table for Table Status first.', 'RAS-0044 : 존재하지 않는 GCM 테이블입니다. Table Status를 위한 GCM 테이블을 먼저 생성하십시요.', 'RAS-0044 : Es existiert keine GCM Tabelle. Erstellen sie eine GCM Tabelle fur den Status.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0045', 'RAS', 'RAS-0045 : Only numeric value is valid for Check Status value in case of check status flag is ">" or "<".', 'RAS-0045 : Check Status 플래그가 ">" 또는 "<"인 경우는 Check Status 값으로 숫자만 가능합니다.', 'RAS-0045 : Nur numerische Werte sind fur Check Status erlaubt da das Flag Check-Sstatus auf ">" oder "<"gesetzt ist.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0046', 'RAS', 'RAS-0046 : Only numeric value is valid for Change Status value in case of check status flag is "+" or "-".', 'RAS-0046 : Change Status 플래그가 "+" 또는 "-"인 경우는 Change Status 값으로 숫자만 가능합니다.', 'RAS-0046 : Nur numerische Werte fur Change Status sind erlaubt da das Flag Status auf  "+" oder "-" gesetzt ist.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0047', 'RAS', 'RAS-0047 : The event is already set for the resource.', 'RAS-0047 : 이 이벤트는 이미 장비에 설정되어 있습니다.', 'RAS-0047 : Dieses Event ist bereits der Resource zugewiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0048', 'RAS', 'RAS-0048 : The event is not set for the resource.', 'RAS-0048 : 장비에 설정되어 있지 않은 이벤트입니다.', 'RAS-0048 : Dieser Event ist fuer die Resource nicht gesetzt.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0049', 'RAS', 'RAS-0049 : Cannot log an event. The current UP/DOWN status of resource is not same to event setup for the resource. Check event setup.', 'RAS-0049 : 이벤트를 발생 시킬 수 없습니다. 현재 장비의 UP/DOWN 상태가 장비 이벤트 설정과 일치하지 않습니다. 이벤트 설정을 확인하십시요.', 'RAS-0049 : Das Event kann nicht geloggt werden. Der aktuelle  UP/DOWN Status der Resource ist nicht identisch wie im Eventsetup der Resource.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0050', 'RAS', 'RAS-0050 : Cannot log an event. The resource status is not exist on GCM table.', 'RAS-0050 : 이벤트를 발생 시킬 수 없습니다. GCM 테이블에 정의되어 있지 않은 장비상태를 입력하였습니다.', 'RAS-0050 : Das Event kann nicht geloggt werden. Der Resourcenstatus ist in der GCM Tabelle nicht verhanden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0051', 'RAS', 'RAS-0051 : Cannot log an event. The current resource status is not same to event setup for the resource. Check event setup.', 'RAS-0051 : 이벤트를 발생 시킬 수 없습니다. 현재 장비상태가 장비 이벤트 설정과 일치하지 않습니다. 이벤트 설정을 확인하십시요.', 'RAS-0051 : Event kann nicht geloggt werden. Der aktuelle Resourcenstatus ist nicht identisch mit dem Event im Resourcen Setup.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0052', 'RAS', 'RAS-0052 : Cannot log an event. The current resource status is same to event setup for the resource. Check event setup.', 'RAS-0052 : 이벤트를 발생 시킬 수 없습니다. 현재 장비상태가 장비 이벤트 설정과 일치합니다. 이벤트 설정을 확인하십시요.', 'RAS-0052 : Ereignis kann nicht geloggt werden. Der aktuelle Resourcenstatus ist nicht identisch mit dem im Event Setup.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0053', 'RAS', 'RAS-0053 : Cannot log an event. The current resource status value is less than event setup for the resource. Check event setup.', 'RAS-0053 : 이벤트를 발생 시킬 수 없습니다. 현재 장비상태 값이 장비 이벤트 설정보다 작습니다. 이벤트 설정을 확인하십시요.', 'RAS-0053 : Das Event kann nicht geloggt werden. Der aktuelle Resourcenstatuswert ist kleiner als der im Event Setup konfigurierte.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0054', 'RAS', 'RAS-0054 : Cannot log an event. The current resource status value is greater than event setup for the resource. Check event setup.', 'RAS-0054 : 이벤트를 발생 시킬 수 없습니다. 현재 장비상태 값이 장비 이벤트 설정보다 큽니다. 이벤트 설정을 확인하십시요.', 'RAS-0054 : Das Event kann nicht geloggt werden. Der aktuelle Resourcenstatuswert ist groesser als der im Event Setup eingestellte Wert.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0055', 'RAS', 'RAS-0055 : Cannot log an event. User input Back Time is behind of last event time.', 'RAS-0055 : 이벤트를 발생 시킬 수 없습니다. 사용자가 입력한 Back Time이 마지막 이벤트 발생시간보다 이전입니다.', 'RAS-0055 : Das Event kann nicht geloggt werden. Die Eingabezeit ist kleiner als die letzte Eventzeit.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0056', 'RAS', 'RAS-0056 : This carrier already exists.', 'RAS-0056 : 이 카세트는 이미 존재 합니다.', 'RAS-0056 : Dieser Carrier existiert bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0057', 'RAS', 'RAS-0057 : The carrier does not exist.', 'RAS-0057 : 존재하지 않는 카세트입니다.', 'RAS-0057 : Der Carrier existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0058', 'RAS', 'RAS-0058 : The carrier type is not defined.', 'RAS-0058 : 존재하지 않는 카세트타입 입니다.', 'RAS-0058 : Der Carrier-Typ ist nicht definiert.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0059', 'RAS', 'RAS-0059 : The carrier material does not exist.', 'RAS-0059 : 존재하지 않는 카세트 소재 입니다.', 'RAS-0059 : Das Carrier-Material existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0060', 'RAS', 'RAS-0060 : The carrier size does not exist.', 'RAS-0060 : 존재하지 않는 카세트 크기 입니다.', 'RAS-0060 : Die Carrier-Groesse existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0061', 'RAS', 'RAS-0061 : The carrier is in use or reserved.', 'RAS-0061 : 카세트가 사용중이거나 예약되어 있습니다.', 'RAS-0061 : Der Carrier ist reserviert oder in Verwendung.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0062', 'RAS', 'RAS-0062 : The carrier has lot.', 'RAS-0062 : 이 카세트를 사용하는 LOT이 있습니다.', 'RAS-0062 : Dieser Carrier hat Lose.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0063', 'RAS', 'RAS-0063 : The carrier using by resource.', 'RAS-0063 : 이 카세트가 장비에서 사용중입니다.', 'RAS-0063 : Dieser Carrier wird von einer Resource verwendet.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0064', 'RAS', 'RAS-0064 : The carrier is cleaning.', 'RAS-0064 : 이 카세트는 세척중입니다.', 'RAS-0064 : Der Carrier wird gereinigt.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0065', 'RAS', 'RAS-0065 : The carrier is moving.', 'RAS-0065 : 이 카세트는 반송장비에 의해 이동중입니다.', 'RAS-0065 : Dieser  Carrier wird verschoben.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0066', 'RAS', 'RAS-0066 : The carrier is not empty.', 'RAS-0066 : 이 카세트가 비어있지 않습니다.', 'RAS-0066 : Dieser Carrier ist nicht leer.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0067', 'RAS', 'RAS-0067 : This material-flow-oper already has resource group.', 'RAS-0067 : 이 제품-FLOW-공정에 이미 장비그룹을 가지고 있습니다.', 'RAS-0067 : Diese Material-Flow-Oper hat bereits eine Resourcengruppe.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0068', 'RAS', 'RAS-0068 : This material-flow-oper does not have resource group.', 'RAS-0068 : 이 제품-FLOW-공정은 장비그룹을 가지고 있지 않습니다.', 'RAS-0068 : Diese Material-Flow-Oper hat keine Resourcengruppe.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0069', 'RAS', 'RAS-0069 : This resource port already exists.', 'RAS-0069 : 이 장비 포트는 이미 존재합니다.', 'RAS-0069 : Dieser Resourcen-Port ist bereits in Verwendung.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0070', 'RAS', 'RAS-0070 : This resource port does not exist.', 'RAS-0070 : 존재하지 않는 장비 포트입니다.', 'RAS-0070 : Dieser Resourcen-Port existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0071', 'RAS', 'RAS-0071 : This resource has already the same port sequence. Use another port sequence.', 'RAS-0071 : 이 장비에 이미 존재하는 포트 순서입니다. 다른 포트순서를 사용하십시요.', 'RAS-0071 : Diese Resource hat bereits eine Portsequenz, verwenden sie eine andere.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0072', 'RAS', 'RAS-0072 : Invalid Port Type 1. Port Type 1 can be "L":LOAD, "U":UNLOAD, or "B":BOTH.', 'RAS-0072 : 잘못된 포트타입입니다. 포트타입 1은 "L":LOAD, "U":UNLOAD, "B":BOTH 중 하나이어야 합니다.', 'RAS-0072 : Ungueltiger Port Type 1. Gueltige Werte sind "L":LOAD, "U":UNLOAD, oder "B":BOTH.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0073', 'RAS', 'RAS-0073 : Invalid Port Type 2. Port Type 2 must be "Y":BATCH LORD, "N", or " ".', 'RAS-0073 : 잘못된 포트타입입니다. 포트타입 2은 "Y":BATCH LORD, "N", " " 중 하나이어야 합니다.', 'RAS-0073 : Ungueltiger Port Type 2. Gueltige Werte sind "Y":BATCH LORD, "N", oder " ".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0074', 'RAS', 'RAS-0074 : Lot or Carrier exists at the port. Remove the Lot or Carrier and retry.', 'RAS-0074 : 포트에 Lot 또는 카세트가 존재합니다. Lot 또는 카세트를 먼저 제거하고 다시 시도하십시요.', 'RAS-0074 : Los oder Trager haben einen Port. Entfernen Sie das Los oder Carrier und versuchen Sie es erneut.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0075', 'RAS', 'RAS-0075 : Not the last resource history. Only the last history can be deleted.', 'RAS-0075 : 마지막 장비이력이 아닙니다. 마지막 이력만이 지워질 수 있습니다.', 'RAS-0075 : Historiensequenz ist nicht aktuell. Nur die letzte Historiensequenz kann geloescht werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0076', 'RAS', 'RAS-0076 : No resource history.', 'RAS-0076 : 장비이력이 존재하지 않습니다.', 'RAS-0076 : Keine Resourcenhistorie.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0077', 'RAS', 'RAS-0077 : Not valid time value.', 'RAS-0077 : 유효하지 않은 시간 값입니다.', 'RAS-0077 : Keine gueltige Zeit.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0078', 'RAS', 'RAS-0078 : No tool history.', 'RAS-0078 : TOOL 이력이 존재하지 않습니다.', 'RAS-0078 : Keine Tool-Historie.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0079', 'RAS', 'RAS-0079 : This EMC Definition already exists.', 'RAS-0079 : 이 EMC 정의는 이미 존재합니다.', 'RAS-0079 : Diese EMC Definition existiert bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0080', 'RAS', 'RAS-0080 : This EMC Definition does not exist.', 'RAS-0080 : 존재하지 않는 EMC 정의입니다.', 'RAS-0080 : Diese EMC Definition existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0081', 'RAS', 'RAS-0081 : Quantity is less than zero.', 'RAS-0081 : 수량이 0보다 작습니다.', 'RAS-0081 : Die Menge ist kleiner 0.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0082', 'RAS', 'RAS-0082 : Invalid Batch Condition value. Batch Condition value can be composed with "X" or " ".', 'RAS-0082 : 유효하지 않은 Batch 조건 값입니다. Batch 조건 값은 "X" 또는 " "만을 사용하여 구성 할 수 있습니다.', 'RAS-0082 : Ungueltige Batchbedingung. Gueltige Werte werden mit "X" oder " " gebildet.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0083', 'RAS', 'RAS-0083 : Invalid Barcode Reader Type. Barcode Reader Type must be "H" or "F".', 'RAS-0083 : 유효하지 않은 바코드 리더 타입 입니다. 바코드 리더 타입으로 "H" 또는 "F"만이 사용됩니다.', 'RAS-0083 : Ungueltiger Barcodelesertyp. Gueltige Werte sind "H" oder "F".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0084', 'RAS', 'RAS-0084 : Control mode is defined, so Auto mode must be defined with the control mode.', 'RAS-0084 : 컨트롤 모드가 설정되어 있습니다. 자동화 모드도 함께 설정되어야만 합니다.', 'RAS-0084 : Der Kontrollmodus ist definiert, deshalb muss Auto-Mode mit Control-Mode definiert sein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0085', 'RAS', 'RAS-0085 : Auto mode is set to MANUAL(M) mode. Control mode must be set to OFF-LINE(OF) mode.', 'RAS-0085 : 자동화 모드가 MANUAL(M)로 설정되어 있습니다. 컨트롤 모드는 반드시 OFF-LINE(OF) 모드이어야 합니다.', 'RAS-0085 : Auto-Modus ist auf MANUAL(M) gesetzt. Control-Mode muss auf OFF-LINE(OF) gesetzt werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0086', 'RAS', 'RAS-0086 : Auto mode is set to SEMI-AUTO(S) or FULL-AUTO(F) mode. Control mode must be set to ON-LINE LOCAL(OL) or ON-LINE REMOTE(OR) mode.', 'RAS-0086 : 자동화 모드가 SEMI-AUTO(S) 또는 FULL-AUTO(F)로 설정되어 있습니다. 컨트롤 모드는 반드시 ON-LINE LOCAL(OL) 또는 ON-LINE REMOTE(OR) 모드이어야 합니다.', 'RAS-0086 : Auto-Mode ist auf SEMI-AUTO(S) oder FULL-AUTO(F)  gesetzt. Der Control-Mode muss auf ON-LINE LOCAL(OL) oder ON-LINE REMOTE(OR) mode gesetzt werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0087', 'RAS', 'RAS-0087 : Auto mode is defined, so Control mode must be defined with the auto mode.', 'RAS-0087 : 자동화 모드가 설정되어 있습니다. 컨트롤 모드도 함께 설정되어야만 합니다.', 'RAS-0087 : Auto-Mode ist definiert, deshalb muss der Control-Mode durch den Auto-Mode definiert werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0088', 'RAS', 'RAS-0088 : This is a system event.', 'RAS-0088 : 시스템 이벤트 입니다.', 'RAS-0088 : Es hanelt sich um ein System-Event.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0089', 'RAS', 'RAS-0089 : Cannot create system event manually.', 'RAS-0089 : 시스템 이벤트는 임의로 생성할 수 없습니다.', 'RAS-0089 : Das System-Event kann nich manuell erstellt weden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0090', 'RAS', 'RAS-0090 : Cannot delete system event.', 'RAS-0090 : 시스템 이벤트는 임의로 지울 수 없습니다.', 'RAS-0090 : Das System-Event konnte nicht geloescht werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0091', 'RAS', 'RAS-0091 : The carrier status is not WAIT.', 'RAS-0091 : 카세트의 상태가 대기 상태가 아닙니다.', 'RAS-0091 : Der Carrier-Status ist nicht WAIT.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0092', 'RAS', 'RAS-0092 : The main resource is a sub-resource of another resource. Cannot setup the resource as the main resource.', 'RAS-0092 : 메인 장비로 지정한 장비가 이미 다른 장비의 보조 장비로 설정되어 있습니다. 그 장비를 메인 장비로 설정할 수 없습니다.', 'RAS-0092 : Die Hauptresource ist selbst eine Sub-resource einer anderen Resource, deshalb kann die Resource nicht als Hauptresource verwendet werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0093', 'RAS', 'RAS-0093 : The date format is invalid. Please check format.', 'RAS-0093 : 이 날짜는 형식이 유효하지 않습니다. 형식을 확인 하세요.', 'RAS-0093 : Dieses Datum hat ein ungueltiges Format.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0094', 'RAS', 'RAS-0094 : This date already has PM SCHEDULE.', 'RAS-0094 : 이 날짜에는 이미 PM SCHEDULE이 이미 존재 합니다.', 'RAS-0094 : Fur dieses Datum existiert bereis ein PM SCHEDULE.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0095', 'RAS', 'RAS-0095 : PM SCHEDULE does not exist for this date.', 'RAS-0095 : 이 날짜에는 PM SCHEDULE이 존재 하지 않습니다.', 'RAS-0095 : PM SCHEDULE existiert fuer dieses Datum nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0096', 'RAS', 'RAS-0096 : PM SCHEDULE date is in past. Old PM SCHEDULE can not be recreated or modified.', 'RAS-0096 : PM SCHEDULE의 날짜가 과거 입니다. 과거 날짜의 PM SCHEDULE을 생성,수정 할 수 없습니다.', 'RAS-0096 : PM SCHEDULE liegt in der Vergangenheit, der alte PM Zeitplan kann nich veraendert werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0097', 'RAS', 'RAS-0097 : PM SCHEDULE is already processed. Only comments can be modified.', 'RAS-0097 : PM SCHEDULE은 이미 실행 되었습니다. COMMENT외에는 수정 할 수 없습니다.', 'RAS-0097 : PM SCHEDULE ist bereits abgearbeitet, es koennen nur mehr Kommentare bearbeitet werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0098', 'RAS', 'RAS-0098 : Invalid unit level. Only  values 0 - 3 are valid.', 'RAS-0098 : 유효하지 않는  UNIT LEVEL입니다. 0 ~ 3 사이의 값만이 유효 합니다.', 'RAS-0098 : Ungueltiger Unit-Level. Nur Werte von 0 bis 3 sind erlaubt..', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0099', 'RAS', 'RAS-0099 : The Alarm Message does not exist.', 'RAS-0099 : 존재하지 않는 알람 메시지입니다.', 'RAS-0099 : Diese Alarm-Messag existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0100', 'RAS', 'RAS-0100 : This PM PART already exists.', 'RAS-0100 : 이 PM PART는 이미 존재 합니다.', 'RAS-0100 : Dieser PM Artikel existiert bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0101', 'RAS', 'RAS-0101 : This PM PART is not exist.', 'RAS-0101 : 이 PM PART는 존재 하지 않습니다.', 'RAS-0101 : This PM PARTl existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0102', 'RAS', 'RAS-0102 : No PM schedule exist for entered period.', 'RAS-0102 : 입력된 기간에 PM SCHEDULE이 존재하지 않습니다.', 'RAS-0102 : Es existiert kein PM schedule fuer den angegebenen Zeitraum.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0103', 'RAS', 'RAS-0103 : No record exists for the entered condition.', 'RAS-0103 : 입력된 조건과 일치하는 항목이 존재하지 않습니다.', 'RAS-0103 : Fur die angefuerte Bedingung existiert keine Aufzeichnung.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0104', 'RAS', 'RAS-0104 : The equip model id does not exist.', 'RAS-0104 : 존재하지 않는 장비 MODEL 입니다.', 'RAS-0104 : Diese Equip-Model ID existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0105', 'RAS', 'RAS-0105 : This policy does not exist.', 'RAS-0105 : 이 POLICY는 존재 하지 않습니다.', 'RAS-0105 : Diese Richtlinie existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0106', 'RAS', 'RAS-0106 : Area does not exist in this factory.', 'RAS-0106 : 이 공장에는 AREA가 존재하지 않습니다.', 'RAS-0106 : Dieses Area existiert in der Fabrik nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0107', 'RAS', 'RAS-0107 : Bay does not exist in this factory.', 'RAS-0107 : 이 공장에는 BAY가 존재하지 않습니다.', 'RAS-0107 : Bay existiert in dieser Fabrik nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0108', 'RAS', 'RAS-0108 : This lot does not exist.', 'RAS-0108 : 이 LOT은 존재하지 않습니다.', 'RAS-0108 : Dieses Los existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0109', 'RAS', 'RAS-0109 : This lot is already deleted. Please check lot id.', 'RAS-0109 : 이 LOT은 이미 삭제된 LOT 입니다. LOT을  확인 하세요.', 'RAS-0109 : Dieses Los wurde bereits geloescht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0110', 'RAS', 'RAS-0110 : This Stocker does not exist .', 'RAS-0110 : 이 STOCKER는 존재하지 않습니다.', 'RAS-0110 : Dieser Stocker existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0111', 'RAS', 'RAS-0111 : No lot is located in this stocker.', 'RAS-0111 : 이 STOCKER에는 LOT이 존재하지 않습니다 .', 'RAS-0111 : In diesem Stocker ist kein Los.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0112', 'RAS', 'RAS-0112 : Lot(s) exists in this material-flow-operation. Move the lot(s) to other operation first.', 'RAS-0112 : 이 DEVICE-FLOW-OPERATION에 속한 Lot이 존재합니다. 먼저 Lot을 다른 그룹으로 옮긴 후 작업하십시요.', 'RAS-0112 : Die Material-Flow-Operation Beziehung hat zumindest ein Los, verschieben sie dieses Los.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0113', 'RAS', 'RAS-0113 : This port status is not allowed.', 'RAS-0113 : 이 PORT 상태는 허용되지 않습니다.', 'RAS-0113 : Dieser Portstatus ist nicht erlaubt.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0114', 'RAS', 'RAS-0114 : This data is invalid. Please check data (floor < 100, top < 12000, left < 16000, height < 12000, width < 16000).', 'RAS-0114 : 이 DATA는 유효하지 않습니다. DATA를 확인 하세요(Floor < 100, top < 12000, left < 16000, height < 12000, width < 16000).', 'RAS-0114 : Diese Daten sind ungueltig. Erlaubt sind (Boden < 100, Decke < 12000, Links < 16000, Hoehe < 12000, Weite < 16000).', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0115', 'RAS', 'RAS-0115 : This tag does not exist. Please check tag id.', 'RAS-0115 : 이 TAG는 존재 하지 않습니다. TAG 이름을 확인 하세요.', 'RAS-0115 : Dieser Tag existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0116', 'RAS', 'RAS-0116 : This tag already exists. Please check tag id.', 'RAS-0116 : 이 TAG는 이미 존재 합니다. TAG 이름을 확인 하세요.', 'RAS-0116 : Dieser Tag existiert bereits. Bitte ueberpruefen Sie die Tag ID.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0117', 'RAS', 'RAS-0117 : The operation is not set for the resource.', 'RAS-0117 : 장비에 설정되어 있지 않은 공정입니다.', 'RAS-0117 : Dieser Operation ist der Resource nicht zugewiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0118', 'RAS', 'RAS-0118 : The operation is already set for the resource.', 'RAS-0118 : 이 공정은 이미 장비에 설정되어 있습니다.', 'RAS-0118 : Dieser Operation ist der Resource bereits zugewiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0119', 'RAS', 'RAS-0119 : The resource was deleted.', 'RAS-0119 : 이 장비는 삭제되었습니다.', 'RAS-0119 : Die Resource wurde geloescht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0120', 'RAS', 'RAS-0120 : The resource was deleted. Do you want to recover?', 'RAS-0120 : 이 장비는 삭제되었습니다. 다시 복구 하시겠습니까?', 'RAS-0120 : Diese Resource wurde geloescht, wollen Sie die Resource wiederherstellen?', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0121', 'RAS', 'RAS-0121 : The resource was not deleted.', 'RAS-0121 : 이 장비는 삭제되지 않았습니다.', 'RAS-0121 : Die Resource wurde nicht geloescht.', 'ADMIN', '20050104102622', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0122', 'RAS', 'RAS-0122 : This User does not exist. Please check the user name.', 'RAS-0122 : 이 사용자는 존재하지 않습니다. 다시 확인하여 주십시요.', 'RAS-0122 : Dieser Benutzer existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0123', 'RAS', 'RAS-0123 : The user is not set for the resource.', 'RAS-0123 : 장비 사용가능자에 등록되어 있지 않은  사용자입니다.', 'RAS-0123 : Der Benuzer ist der Resource nicht zugewiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0124', 'RAS', 'RAS-0124 : Resource does not have a Privilege Group', 'RAS-0124 : 이 장비는 장비 사용자 그룹이 설정되어 있지 않습니다.', 'RAS-0124 : Die Resource ist keiner Privilege-Group zugewiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0125', 'RAS', 'RAS-0125 : The user (resource) is not set for the PM Security.', 'RAS-0125 : 이 사용자(장비)는 PM 관련 작업에 할당되어 있지 않습니다.', 'RAS-0125 : Der Benutzer (Resource) ist keiner PM Security zugewiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0126', 'RAS', 'RAS-0126 : The user (resource) is already set for the PM Security.', 'RAS-0126 : 이 사용자(장비)는 이미 PM 관련 작업에 할당되어 있습니다.', 'RAS-0126 : Der Benutzer (Resource) ist bereits einer PM Security zugwiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0127', 'RAS', 'RAS-0127 : PM Schedule of the resource does not exist at the date.', 'RAS-0127 : 장비의 해당 날짜에 대한 PM Schedule이 존재하지 않습니다.', 'RAS-0127 : Fuer dieses Datum und Resource exisiert kein PM Schedule.', 'ADMIN', '20050418152006', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0128', 'RAS', 'RAS-0128 : PM Schedule of the resource already exist at the date.', 'RAS-0128 : 장비의 해당 날짜에 대한 PM Schedule이 이미 존재합니다.', 'RAS-0128 : An diesem Datum exisiert bereits ein PM Schedule fuer diese Resource.', 'ADMIN', '20050418152120', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0129', 'RAS', 'RAS-0129 : PM Schedule date is past. It does not allow to Create or Delete PM Schedule in past date.', 'RAS-0129 : PM Schedule의 날짜가 과거입니다. 과거에 대한 PM SChedule은 생성, 삭제할수 없습니다.', 'RAS-0129 : Das Datum fuer den PM Schedule liegt in der Vergangenheit, muss aber in der Zukunft liegen.', 'ADMIN', '20050418152432', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0130', 'RAS', 'RAS-0130 : It is not allowed to setup a PM schedule for this Resource. Please check PM Schedule Enable option in Resource Setup.', 'RAS-0130 : 해당 장비는 PM Schedule 설정이 허가 되어 있지 않습니다. 장비에 대한 PM Schedule 설정을 먼저 허용해 주세요.', 'RAS-0130 : Diese Resource darf keinen PM Zeitplan erstellen.', 'ADMIN', '20050419152206', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0131', 'RAS', 'RAS-0131 : PM Schedule date is past. You can only modify comment.', 'RAS-0131 : PM Schedule의 날짜가 과거입니다.. Comment 외에는 수정할 수 없습니다.', 'RAS-0131 : PM Zeitplan liegt in der Vergangenheit, Sie koennen nur Kommentare aendern.', 'ADMIN', '20050419155836', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0132', 'RAS', 'RAS-0132 : PM Schedule is already processed. It is not possible to update/delete PM schedule.', 'RAS-0132 : PM Schedule이 이미 실행되었습니다. 이미 실행된 Schedule은 변경/삭제할 수 없습니다.', 'RAS-0132 : PM Zeitpaln ist bereits abgearbeitet, Sie koennen nichts mehr veraendern.', 'ADMIN', '20050419161653', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0133', 'RAS', 'RAS-0133 : This Privilege Group does not exist.', 'RAS-0133 : PRIVILEGE GROUP 이 존재하지 않습니다.', 'RAS-0133 : Diese Privilege-Group existiert nicht.', 'ADMIN', '20050426201831', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0134', 'RAS', 'RAS-0134 : The User has no privilege to raise PM Event of the resource.', 'RAS-0134 : 이 사용자는 해당 장비에 대한 PM 실시 권한이 없습니다.', 'RAS-0134 : Dem Benutzer fehlen die Rechte um ein PM Event der Resource auszuloesen.', 'ADMIN', '20050509174352', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0135', 'RAS', 'RAS-0135 : PM Period does not registered.', 'RAS-0135 : 등록되어 있지 않은 PM 주기 입니다.', 'RAS-0135 : Die PM Period ist nicht registriert.', 'ADMIN', '20050509181154', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0136', 'RAS', 'RAS-0136 : PM is already done. Please check PM Schedule and PM Status.', 'RAS-0136 : 이미 PM을 실시하셨습니다. PM 계획과 PM 상태를 확인하세요.', 'RAS-0136 : PM ist bereits abgearbeitet. Ueberpruefen Sie den Status und Schedule.', 'ADMIN', '20050509200918', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0137', 'RAS', 'RAS-0137 : Tool Type does not exist.', 'RAS-0137 : TOOL TYPE이 존재하지 않습니다.', 'RAS-0137 : Tool-Type existiert nicht.', 'ADMIN', '20050621143053', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0138', 'RAS', 'RAS-0138 : Tool Type already exist.', 'RAS-0138 : TOOL TYPE 이 이미 존재합니다.', 'RAS-0138 : Tool-Type existiert bereits.', 'ADMIN', '20050621143153', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0139', 'RAS', 'RAS-0139 : Some tools are included in this Tool Type. So you can not delete this Tool Type.', 'RAS-0139 : TOOL TYPE에 속한 TOOL이 공장에서 사용중이므로 TOOL TYPE을 삭제할  수 없습니다.', 'RAS-0139 : Einige andere Werkzeugtypen haengen von diesem Werkzeugtypen ab, deshalb kann er nicht geloescht werden.', 'ADMIN', '20050621143321', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0140', 'RAS', 'RAS-0140 : Cannot create system tool type by manual.', 'RAS-0140 : 시스템 TOOL TYPE은 임의로 생성할 수 없습니다.', 'RAS-0140 : Ein System-Tool-Type kann nicht manuell erstellt werden.', 'ADMIN', '20050621144325', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0141', 'RAS', 'RAS-0141 : Cannot delete system tool type.', 'RAS-0141 : 시스템 TOOL TYPE은 임의로 삭제할 수 없습니다.', 'RAS-0141 : Der System-Tool-Type kann nicht geloescht werden.', 'ADMIN', '20050621144647', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0142', 'RAS', 'RAS-0142 : Cannot change system flag of Tool Type.', 'RAS-0142 : 시스템 TOOL TYPE을 일반 TOOL TYPE으로, 또는 일반 TOOL TYPE을 시스템 TOOL TYPE으로 변경하는 것은 불가능 합니다.', 'RAS-0142 : Das Flag System des Tool-Type kannn nicht geaendert werden.', 'ADMIN', '20050621145435', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0143', 'RAS', 'RAS-0143 : Tool Type Status Value size must between 0 and 30.', 'RAS-0143 : TOOL TYPE에서 지정하는 상태값의 길이는 0~30사이만 허용됩니다.', 'RAS-0143 : Der Wertebereich des Tool-Type-Status liegt zwischen 0 und 30.', 'ADMIN', '20050621152126', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0144', 'RAS', 'RAS-0144 : Tool Type Status Value format must be ''A''(Ascii), ''N'' (Number), ''F''(Float).', 'RAS-0144 : TOOL TYPE에서 지정하는 상태값의 형식은 ''A''(문자), ''N''(정수), ''F''(실수) 만 허용됩니다.', 'RAS-0144 : Gueltige Werte fuer den Tool-Type-Status sind  ''A''(Ascii), ''N'' (Number), ''F''(Float).', 'ADMIN', '20050621160337', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0145', 'RAS', 'RAS-0145 : Tool Type Name cannot be "SYSTEM".', 'RAS-0145 : "SYSTEM" 은 TOOL TYPE 이름으로 사용할 수 없습니다.', 'RAS-0145 : "SYSTEM" ist als Tool-Type-Name nicht erlaubt.', 'ADMIN', '20050621173305', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0146', 'RAS', 'RAS-0146 : Tool Event does not exist.', 'RAS-0146 : TOOL EVENT가 존재하지 않습니다.', 'RAS-0146 : Tool-Event existiert nicht.', 'ADMIN', '20050622145935', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0147', 'RAS', 'RAS-0147 : Tool Event already exist.', 'RAS-0147 : TOOL EVENT가 이미 존재합니다.', 'RAS-0147 : Tool Type Name existiert bereits.', 'ADMIN', '20050622150017', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0148', 'RAS', 'RAS-0148 : Cannot create system tool event by manual.', 'RAS-0148 : 시스템 TOOL EVENT는 임의로 생성할 수 없습니다.', 'RAS-0148 : System-Tool-Event kann nicht manuell erzeugt werden.', 'ADMIN', '20050622150511', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0149', 'RAS', 'RAS-0149 : Cannot delete system tool event.', 'RAS-0149 : 시스템 TOOL EVENT는 임의로 삭제할 수 없습니다.', 'RAS-0149 : Das System-Tool-Event kann nicht geloescht werden.', 'ADMIN', '20050622151818', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0150', 'RAS', 'RAS-0150 : Cannot change system flag of Tool Event.', 'RAS-0150 : 시스템 TOOL EVENT를 일반 TOOL EVENT로, 또는 일반 TOOL EVENT을 시스템 TOOL EVENT로 변경하는 것은 불가능 합니다.', 'RAS-0150 : Das Flag System des Tool-Events kann nicht geloescht werden.', 'ADMIN', '20050622151911', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0151', 'RAS', 'RAS-0151 : Some tools are using this Tool Event. So you can not delete this Tool Event.', 'RAS-0151 : 몇몇 TOOL이 TOOL EVENT를 사용중이므로 TOOL EVENT를 삭제할  수 없습니다.', 'RAS-0151 : Das Tool-Event wird duch einige Tools verwendet, deshalb kann es nicht geloescht werden.', 'ADMIN', '20050622154303', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0152', 'RAS', 'RAS-0152 : The Number of Check Items / Change Items for a Tool Event have a limit of 30.', 'RAS-0152 : TOOL EVENT에서 지정할수 있는 CHECK ITEM, CHANGE ITEM의 갯수는 30개로 제한되어 있습니다.', 'RAS-0152 : Das Limit fuer Check Item bzw. Change Item fuer dieses Tool-Event liegt bei 30.', 'ADMIN', '20050622163615', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0153', 'RAS', 'RAS-0153 : Tool Event check flag must be ''N''(Not Check), ''=''(Equal), ''!''(Not Equal), ''<''(Less than), ''>''(Greater than).', 'RAS-0153 : TOOL EVENT의 Check Flag 값은 N''(체크안함), ''=''(같음), ''!''(같지않음), ''<''(~보다작음), ''>''(~보다큼) 만 허용됩니다.', 'RAS-0153 : Das Flag Tool-Event-Check muss auf ''N''(Not Check), ''=''(Equal), ''!''(Not Equal), ''<''(Less than) oder ''>''(Greater than) gesetzt sein.', 'ADMIN', '20050622164534', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0154', 'RAS', 'RAS-0154 : Check Item can not have both Check Value and Check Field.', 'RAS-0154 : CHECK ITEM이 그 비교값으로 CHECK VALUE 와 CHECK FIELD값을 둘다 가질 수 없습니다.', 'RAS-0154 : Ein Check-Item kann nich zugleich auf Check-Value  und Check- Field gesetzt sein.', 'ADMIN', '20050622165754', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0155', 'RAS', 'RAS-0155 : Unused Check/Change Item. Please verify check/change item.', 'RAS-0155 : 사용할 수  없는 CHECK/CHANGE ITEM입니다. CHECK/CHANGE ITEM이 올바른지 확인하세요.', 'RAS-0155 : Nicht verwendetes Check/Change Item. Bitte ueberpruefen Sie dieses Item.', 'ADMIN', '20050623092850', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0156', 'RAS', 'RAS-0156 : Tool Type is restricted to use this tool status.', 'RAS-0156 : 해당 TOOL STATUS는 TOOL TYPE에서 사용하지 못하도록 설정되어 있습니다.', 'RAS-0156 : Der Tool-Type ist auf diesen Status eingeschraenkt.', 'ADMIN', '20050623111512', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0157', 'RAS', 'RAS-0157 : Check Item must have Check Value or Check Field.', 'RAS-0157 : CHECK ITEM은 CHECK VALUE 또는 CHECK FIELD값을 가져야 합니다.', 'RAS-0157 : Das Check Item muss eine Check Value oder Check Field besitzen.', 'ADMIN', '20050623120221', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0158', 'RAS', 'RAS-0158 : Format of the Item is set to ''N''(Number) or ''F''(Float) in Tool Type Setup. But value type does not match with these types.', 'RAS-0158 : TOOL TYPE에서 해당 ITEM에 대한 값의 형식을 ''N''(정수) 또는 ''F''(실수) 로 지정하셨고, 현재 입력하신 값은 이 형식에 맞지 않는 값입니다.', 'RAS-0158 : Das Format des Item ist im Tool-Setup auf ''N''(Number) oder ''F''(Float) eingestellt Der aktuelle Wert stimmt jedoch nicht mit diesen ueberein.', 'ADMIN', '20050623133926', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0159', 'RAS', 'RAS-0159 : This Tool Type is aleady deleted.', 'RAS-0159 : 이미 삭제된 TOOL TYPE입니다.', 'RAS-0159 : Dieser Tool-Type wurde bereits geloescht.', 'ADMIN', '20050623142434', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0160', 'RAS', 'RAS-0160 : The data size exceeds the proper value. Please input again.', 'RAS-0160 : 설정된 SIZE 보다 더 큰 값입니다. 다시 입력하여 주세요.', 'RAS-0160 : Der eingegebene Wert liegt ueber den dafuer vorgesehenen Limit. Bitte geben Sie einen anderen Wert ein.', 'ADMIN', '20050623155928', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0161', 'RAS', 'RAS-0161 : Unused Check Field. Please verify check Field.', 'RAS-0161 : 사용할 수  없는 CHECK FIELD입니다. CHECK FILED값이 올바른지 확인하세요.', 'RAS-0161 : Ein Check-Field ist nicht gesetzt. Bitte ueberpruefen Sie das Check-Field.', 'ADMIN', '20050630110316', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0162', 'RAS', 'RAS-0162 : Check Item and Check Field must have the same data type.', 'RAS-0162 : CHECK ITEM과 CHECK FIELD는 데이타 형식이 같아야 합니다.', 'RAS-0162 : Das Check-Item und Check-Field muessen den gleichen Datentyp besitzen.', 'ADMIN', '20050630113628', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0163', 'RAS', 'RAS-0163 : Tool Type is restrict to use this tool status.', 'RAS-0163 : 해당 TOOL STATUS는 TOOL EVENT 발생시 값을 변경할수 있는 상태값이 아닙니다.', 'RAS-0163 : Der Tool-Type ist auf diesen Tool-Status beschraenkt.', 'ADMIN', '20050630122218', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0164', 'RAS', 'RAS-0164 : When CHANGE ITEM is not TOOL_STATUS_1 ~ TOOL_STATUS_30, Can''t use ''+''(plus), ''-''(minus), ''*''(multiply), ''/''(divide), ''mod''(MOD), ''pow''(POW), ''T''(Time)', 'RAS-0164 : CHANGE ITEM이 TOOL_STATUS_1 ~ TOOL_STATUS_30 가 아닐 때 ''+''(더하기), ''-''(빼기), ''*''(곱하기), ''/''(나누기), ''mod''(MOD), ''pow''(POW), ''T''(Time)을 사용할 수 없습니다.', 'RAS-0164 : Wenn CHANGE ITEM nicht TOOL_STATUS_1 ~ TOOL_STATUS_30 aufweist, koennen ''+''(Plus), ''-''(Minus), ''*''(Multiplizieren), ''/''(Dividieren), ''mod''(MOD), ''pow''(POW), ''T''(Time) nicht benutzt werden.', 'ADMIN', '20130529153559', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0165', 'RAS', 'RAS-0165 : Value of Change Item is not valid for the selected Change Flag. (Ex. Change Item is "GCM DATA" when Change Flag is one of ''+'', ''-'', or ''T'')', 'RAS-0165 : CHANGE ITEM 값과 CHANGE FLAG 값이 호환되지 않습니다. (예. CHANGE ITEM 값은 GCM DATA이고 , CHANGE FLAG는 ''+'', ''-'', ''T'' 중 하나인 경우.)', 'RAS-0165 : Der Wert fuer Change-Item stimmt mit dem Flag  Change  ueberein.  (Ex. Change Item ist  ''GCM DATA'' , sofern das Flag Chance ''+'', ''-'' oder ''T'' ist.)', 'ADMIN', '20050630142218', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0166', 'RAS', 'RAS-0166 : Data type of Change Item is not valid for the selected Change Flag. (Ex. The data type of Change Item is ASCII when Change Flag is one of ''+'' or ''-'')', 'RAS-0166 : CHANGE ITEM의 데이타 형식이 CHANGE FLAG 값과 호환되지 않는 형식입니다. (예. CHANGE ITEM의 데이타 형식은 ASCII이고, CHANGE FLAG는 ''+'', ''-''중 하나인 경우)', 'RAS-0166 : Der Datentyp fuer Change-Item stimmt mit dem Flag  Change  nicht ueberein.  (Ex. Datentyp des Change Item ist  ASCII , sofern das Flag Chance ''+'' oder ''-'' ist.)', 'ADMIN', '20050630143407', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0167', 'RAS', 'RAS-0167 : Tool Type is already deleted.', 'RAS-0167 : 삭제된 TOOL TYPE입니다.', 'RAS-0167 : Der Tool-Type ist bereits geloescht.', 'ADMIN', '20050701140812', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0168', 'RAS', 'RAS-0168 : Tool does not exist.', 'RAS-0168 : TOOL 이 존재하지 않습니다.', 'RAS-0168 : Tool existiert nicht.', 'ADMIN', '20050704102457', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0169', 'RAS', 'RAS-0169 : Tool already exists.', 'RAS-0169 : TOOL이 이미 존재합니다.', 'RAS-0169 : Tool existiert bereits.', 'ADMIN', '20050704102537', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0170', 'RAS', 'RAS-0170 : Tool is not included in the Tool type.', 'RAS-0170 : TOOL이 TOOL TYPE에 속해 있지 않습니다.', 'RAS-0170 : Das Tool ist nicht im Tool-Type enthalten.', 'ADMIN', '20050704102630', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0171', 'RAS', 'RAS-0171 : Tool is already deleted/scrapped/returned.', 'RAS-0171 : 삭제/폐기/반품된 TOOL입니다.', 'RAS-0171 : Dieses Werkzeug ist bereits deleted, scrapped oder returned.', 'ADMIN', '20050704121556', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0172', 'RAS', 'RAS-0172 : The tool event is not set for the Tool.', 'RAS-0172 : TOOL에 설정되어 있지 않은 이벤트입니다.', 'RAS-0172 : Das Tool-Event ist dem Tool nicht zugeordnet.', 'ADMIN', '20050704122647', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0173', 'RAS', 'RAS-0173 : The event is already set for the Tool.', 'RAS-0173 : 이 이벤트는 이미 TOOL에 설정되어 있습니다.', 'RAS-0173 : Dieses Event existiert bereits fuer dieses Tool.', 'ADMIN', '20050704130927', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0174', 'RAS', 'RAS-0174 : Cannot detach system event from Tool.', 'RAS-0174 : 시스템 이벤트는 TOOL에서 분리할 수 없습니다.', 'RAS-0174 : Dieses Event kann nicht vom Tool losgeloest werden.', 'ADMIN', '20050704132613', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0175', 'RAS', 'RAS-0175 : Tool is not returned. Regeneration is allowed for the returned tool.', 'RAS-0175 : 이 TOOL은 반품된 TOOL이 아닙니다. 재입고는 반품된 TOOL에 대해서만 가능합니다.', 'RAS-0175 : Das Werkzeug antwortet nicht.', 'ADMIN', '20050704162513', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0176', 'RAS', 'RAS-0176 : There is processing going on or reserved lot / sublot exists in the tool. Move the lot /sublot from tool first.', 'RAS-0176 : TOOL에서 진행중인 또는 예약된 Lot / Sublot이 존재합니다. 먼저 Lot/ Sublot을 진행하신 후에 TOOL을 폐기또는 반품하시기 바랍니다.', 'RAS-0176 : Es existiert ein Los oder Wafer fuer das Tool oder das Tool wird gerade prozessiert. Bitte verschieben Sie das/den Los oder Wafer zuerst.', 'ADMIN', '20050704164619', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0177', 'RAS', 'RAS-0177 : Tool is processing a job in the Resource/SubResource. Move this Tool from the Resource/ Subresource first.', 'RAS-0177 : TOOL이 현재 장비/서브장비에서 작업중입니다. 장비/서브장비로부터 TOOL을 먼저 분리하세요.', 'RAS-0177 : Das Tool verarbeitet gerade einen Auftrag fur die Resource oder Subresource. Bitte verschieben Sie zuerst dieses Tool von der  Resource/Subresource.', 'ADMIN', '20050704164817', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0178', 'RAS', 'RAS-0178 : It is not possible to Scrap the Tool when the Tool is not in "WAIT" status.', 'RAS-0178 : 이 TOOL은 현재 대기상태가 아니므로 폐기 또는 반품 시킬수 없습니다.', 'RAS-0178 : Ein Scrap ist  nicht moeglich wenn das Tool nicht im Status WAIT'' ist.', 'ADMIN', '20050704170652', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0179', 'RAS', 'RAS-0179 : You cannot change tool type of existing tool.', 'RAS-0179 : 이미 생성된 TOOL의 TOOL TYPE은 변경이 불가능 합니다.', 'RAS-0179 : Der Tool-Type eines existierenden Tools kann nicht geaendert werden.', 'ADMIN', '20050704171515', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0180', 'RAS', 'RAS-0180 : The value of Check Field can not be same with the value of Check Item.', 'RAS-0180 : CHECK ITEM과 동일한 CHECK FIELD를 가질수 없습니다.', 'RAS-0180 : Der Wert des Check-Field darf nicht mit dem des Check-Items uebereinstimmen.', 'ADMIN', '20050718113234', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0181', 'RAS', 'RAS-0181 : This carrier needs to be cleaned.', 'RAS-0181 : 이 카세트는 Clean이 필요한 상태입니다.', 'RAS-0181 : Dieser Carrier muss gereinigt werden.', 'ADMIN', '20050701142111', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0182', 'RAS', 'RAS-0182 : This data is invalid. Please check data.', 'RAS-0182 : 이 DATA는 유효하지 않습니다. DATA를 확인 하세요.', 'RAS-0182 : Dieser Daten sind ungueltig. Bitte ueberpruefen Sie die Daten.', 'ADMIN', '20050708145049', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0183', 'RAS', 'RAS-0183 : SubLot quantity is mismatch. Please check quantity.', 'RAS-0183 : SUBLOT의 수량이 일치 하지 않습니다. 수량을 확인 하세요.', 'RAS-0183 : Die Sub-Lot-Quantity stimmt nicht. Bitte ueberpruefen Sie die Menge.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0184', 'RAS', 'RAS-0184 : It is not  possible to modify TOOL_STATUS_N by Tool Event.', 'RAS-0184 : TOOL_STATUS_N 은 EVENT에서 값을 변경할 수 없습니다.', 'RAS-0184 : Sie koennen den TOOL_STATUS_N nicht durch ein Tool-Event aendern.', 'ADMIN', '20050722112423', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0185', 'RAS', 'RAS-0185 : Tool event is different from tool history.', 'RAS-0185 : TOOL EVENT 가 TOOL 이력의 TOOL EVENT와 다릅니다.', 'RAS-0185 : Das Tool-Event stimmt nicht mit der Historie ueberein.', 'ADMIN', '20050721154736', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0186', 'RAS', 'RAS-0186 : Tool history already deleted.', 'RAS-0186 : 삭제된 TOOL 이력 입니다.', 'RAS-0186 : Die Tool-Historie ist bereits geloescht.', 'ADMIN', '20050721154247', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0187', 'RAS', 'RAS-0187 : Tool History does not exist', 'RAS-0187 : TOOL 이력이 존재하지 않습니다.', 'RAS-0187 : Die Historie existiert nicht.', 'ADMIN', '20050721154054', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0188', 'RAS', 'RAS-0188 : You can not collect defect data at current tool event.', 'RAS-0188 : 해당 TOOL EVNT에서는 DEFECT DATA를 수집할 수 없습니다.', 'RAS-0188 : Das aktuelle Tool-Event kann keine Defect-Data sammeln.', 'ADMIN', '20050721153817', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0189', 'RAS', 'RAS-0189 : Same defect code does aleardy exist in one location.', 'RAS-0189 : TOOL내 현 위치에 동일한 DEFECT CODE가 이미 존재합니다.', 'RAS-0189 : Dieser Defect-Code existiert bereits fuer diesen Standort.', 'ADMIN', '20050721152639', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0190', 'RAS', 'RAS-0190 : Defect Code overriding is not allowed in one location.', 'RAS-0190 : TOOL내 한 위치에 동일한 DEFECT CODE가 중복되어 들어갈 수 없습니다.', 'RAS-0190 : Das ueberschreiben des Defect-Codes fuer diesen Standort ist nicht erlaubt.', 'ADMIN', '20050721150528', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0191', 'RAS', 'RAS-0191 : The number of tool_status must be 30.', 'RAS-0191 : Tool Status의 갯수는 30개여야 합니다.', 'RAS-0191 : Der Wert fuer tool_status muss 30 sein.', 'ADMIN', '20050718121212', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0192', 'RAS', 'RAS-0192 : TOOL_STS_N cannot have value.', 'RAS-0192 : TOOL_STATUS_N 은 값을가질수 없습니다.', 'RAS-0192 : TOOL_STS_N darf keinen Wert besitzen.', 'ADMIN', '20050718121425', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0193', 'RAS', 'RAS-0193 : Prompt cannot be same with Other Prompt in one Tool type.', 'RAS-0193 : 하나의 TOOL TYPE에서 PROMPT를 중복하여 사용할 수 없습니다.', 'RAS-0193 : Innerhalb eines Werkzeugtyps darf der Prompt nicht gleich sein.', 'ADMIN', '20050718153712', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0194', 'RAS', 'RAS-0194 : Tool Status Value can not be modified.', 'RAS-0194 : TOOL_STATUS_N 값은 변경이 불가능합니다.', 'RAS-0194 : Der Tool-Status-Wert kann mich veraendert werden.', 'ADMIN', '20050718164251', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0195', 'RAS', 'RAS-0195 : Cannot raise event. The current tool status is not same to tool event setup for the tool. Check tool event setup.', 'RAS-0195 : TOOL 이벤트를 발생 시킬 수 없습니다. 현재 TOOL의 상태가 TOOL 이벤트 설정과 일치하지 않습니다. TOOL 이벤트 설정을 확인하십시요.', 'RAS-0195 : Es kann kein Event ausgeloest werden. Der aktelle Tool-Status ist nicht der gleiche wie im Tool-Event-Setup. Ueberpruefen Sie das das Tool-Event-Setup.', 'ADMIN', '20050720111525', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0196', 'RAS', 'RAS-0196 : Cannot raise event. The current tool status is same to tool event setup for the tool. Check tool event setup.', 'RAS-0196 : 이벤트를 발생 시킬 수 없습니다. 현재 TOOL 상태가 TOOL 이벤트 설정과 일치합니다. TOOL 이벤트 설정을 확인하십시요.', 'RAS-0196 : Es kann kein Event ausgeloest werden. Der aktuelle Tool-Status ist identisch mit dem im Tool-Event-Setup fuer dieses Tool.', 'ADMIN', '20050720112012', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0197', 'RAS', 'RAS-0197 : Cannot raise event. The current tool status value is less than tool event setup for the tool. Check tool event setup.', 'RAS-0197 : 이벤트를 발생 시킬 수 없습니다. 현재 TOOL상태 값이 TOOL 이벤트 설정보다 작습니다. TOOL 이벤트 설정을 확인하십시요.', 'RAS-0197 : Es kann keine Event ausgeloest werden. Der aktuelle Event-Status ist kleiner als im Tool-Event-Setup. Ueberpruefen Sie das Tool-Event-Setup.', 'ADMIN', '20050720112249', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0198', 'RAS', 'RAS-0198 : Cannot raise event. The current tool status value is greater than tool event setup for the tool. Check tool event setup.', 'RAS-0198 : 이벤트를 발생 시킬 수 없습니다. 현재 TOOL상태 값이 TOOL 이벤트 설정보다 큽니다. TOOL 이벤트 설정을 확인하십시요.', 'RAS-0198 : Es kann keine Event ausgeloest werden. Der aktuelle Tool-Satus ist groesser als im Tool-Event-Setup. Ueberpruefen Sie das Tool-Event-Setup.', 'ADMIN', '20050720112535', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0199', 'RAS', 'RAS-0199 : Overriding Change Item in one Tool Event is not allowed.', 'RAS-0199 : 하나의 TOOL EVENT에서 CHANGE ITEM은 중복해서 사용할 수 없습니다.', 'RAS-0199 : Es ist nicht erlaubt eine Change-Item eines Tool-Events zu aendern.', 'ADMIN', '20050720114427', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0200', 'RAS', 'RAS-0200 : The counter for Cleaning has reached its limit.', 'RAS-0200 : Clean limit을 초과합니다.', 'RAS-0200 : Der Cleaning-Counter hat sein Limit erreicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0201', 'RAS', 'RAS-0201 : Carrier does not have enough space.', 'RAS-0201 : 카셋트에 충분한 공간이 없습니다.', 'RAS-0201 : Der Carrier hat nicht genuegend Platz.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0211', 'RAS', 'RAS-0211 : You can not clean defect data at current tool event.', 'RAS-0211 : 해당 TOOL EVNT에서는 DEFECT DATA를 CLEAN 할 수 없습니다.', 'RAS-0211 : Es koennen keine Defektdaten fuer das aktuelle Tool-Event geloescht werden.', 'ADMIN', '20050722113205', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0212', 'RAS', 'RAS-0212 : No Tool defect data for the defect code at the specified position or the defect is already cleared.', 'RAS-0212 : TOOL에서 입력한 위치에 해당 DEFECT CODE로 DEFECT가 기록되어 있지 않거나 이미 DEFECT를 제거했습니다.', 'RAS-0212 : Es existieren keine Defect-Data fuer diesen Defect-Code und diese Position oder sie wurden bereits geloescht.', 'ADMIN', '20050722141551', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0213', 'RAS', 'RAS-0213 : Defect data for the tool does not exist.', 'RAS-0213 : TOOL에 대한 DEFECT DATA가 존재하지 않습니다.', 'RAS-0213 : Es existieren keine Defek-Data fuer dieses Tool.', 'ADMIN', '20050722174250', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0214', 'RAS', 'RAS-0214 : History sequence is not the latest. Please check it again.', 'RAS-0214 : HISTORY SEQUENCE가 마지막이 아닙니다. 다시 확인 하세요', 'RAS-0214 : History Sequence ist nicht die aktuellste. Bitte uberprufen Sie es erneut.', 'ADMIN', '20050726122311', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0215', 'RAS', 'RAS-0215 : Tool History Information does not match. Please check it again.', 'RAS-0215 : TOOL 이력 정보가 올바르지 않습니다. 다시 확인 하세요', 'RAS-0215 : Tool History Information stimmen nicht ueber ein. Bitte ueberpruefen Sie es erneut.', 'ADMIN', '20050726134157', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0216', 'RAS', 'RAS-0216 : Tool History does not exist. please check tool id and history sequence.', 'RAS-0216 : TOOL 이력이 존재하지 않습니다. TOOL ID와 History Sequence를 확인하세요.', 'RAS-0216 : Die Tool-Historie existiert nicht. Ueberpruefen Sie die Tool ID und Historiensequenz.', 'ADMIN', '20050726140220', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0217', 'RAS', 'RAS-0217 : Tool History is aleady deleted.', 'RAS-0217 : TOOL 이력이 이미 삭제되었습니다.', 'RAS-0217 : Die Historie wurde bereits geloescht.', 'ADMIN', '20050726140259', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0218', 'RAS', 'RAS-0218 : The following Tool Event name is already reserved for the System (''CREATE'', ''UPDATE'', ''DELETE'', ''SCRAP'', ''RETURN'', ''REGENEERATE'' )', 'RAS-0218 :  다음 이름들은 시스템 내부에서 사용하는 이름으로  TOOL EVENT ID로 사용할 수 없습니다.  (''CREATE'', ''UPDATE'', ''DELETE'', ''SCRAP'', ''RETURN'', ''REGENEERATE'')', 'RAS-0218 : Der folgende Tool-Event-Name wurde bereits reserviert ''CREATE'', ''UPDATE'', ''DELETE'', ''SCRAP'', ''RETURN'', ''REGENEERATE''.', 'ADMIN', '20050822113844', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0219', 'RAS', 'RAS-0219 : This resource can not use the current operation.', 'RAS-0219 :  이 Resource는 현 공정에서 진행 할 수 없습니다.', 'RAS-0219 : Diese Resource kann die aktuelle Operation nicht verwenden.', 'ADMIN', '20051223150005', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0230', 'RAS', 'RAS-0230 : Resource(s) has Sub Resource. Delete the sub resource(s) first.', 'RAS-0230 : 장비에 Sub 장비가 있습니다. 먼저 Sub 장비를 지우세요.', 'RAS-0230 : Die Resource hat Subresourcen, loeschen Sie die Subresourcen zuerst.', 'ADMIN', '20050726101721', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0231', 'RAS', 'RAS-0231 : This sequence number already exists. Please use another sequence.', 'RAS-0231 : 동일한시퀀스 번호가 존재 합니다.  시퀀스 번호를 확인 하세요.', 'RAS-0231 : Diese Sequenznummer existiert bereits, verwenden Sie eine andere.', 'ADMIN', '20051117173843', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0232', 'RAS', 'RAS-0232 : This port does not exist.', 'RAS-0232 : 이 포트는 존재하지 않는 포트 입니다.', 'RAS-0232 : Dieser Port existiert nicht.', 'ADMIN', '20051118100817', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0233', 'RAS', 'RAS-0233 : This port already exists.', 'RAS-0233 : 이 포트는 이미 존재 합니다.', 'RAS-0233 : Dieser Port existiert bereits.', 'ADMIN', '20051118101450', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0234', 'RAS', 'RAS-0234 : Port sequence must large than 0;', 'RAS-0234 : 포트 시퀀스는 1 이상만 허용됩니다.', 'RAS-0234 : Die Portsequenz muss groesser als 0 sein.', 'ADMIN', '20051118141208', ' ', ' ');
