INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0238', 'RAS', 'RAS-0238 : This lot is not attach to a carrier.', 'RAS-0238 : 이 LOT은 캐리어에 담겨있지 않습니다.', 'RAS-0238 : Dieses Los ist keinem Carrier zugewiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0239', 'RAS', 'RAS-0239 : The sum of total Lot quantity in carrier(s) and Lot quantity will attach to the carrier is greater than quantity of this Lot.', 'RAS-0239 : 캐리어들에 담겨진 LOT의 수량과 이 캐리어에 담겨질 LOT의 수량의 합이 이 LOT의 수량을 초과합니다.', 'RAS-0239 : Anzahl der Lose im Carrier und die noch hinzugefuegt werden muessen, ist groesser als die Losmenge.', 'ADMIN', '20081201010101', ' ', ' ');
