INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0266', 'RAS', 'RAS-0266 : Carrier Event already exist.', 'RAS-0266 : CARRIER 이벤트가 이미 존재합니다.', 'RAS-0266: Carrier Event existiert bereits.', 'ADMIN', '20080924100607', 'ADMIN', '20081218110704');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0267', 'RAS', 'RAS-0267 : Carrier Event does not exist.', 'RAS-0267 : CARRIER 이벤트가 존재하지 않습니다.', 'RAS-0267 : Carrier Event existiert nicht.', 'ADMIN', '20080924100520', 'ADMIN', '20081218110717');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0268', 'RAS', 'RAS-0268 : Cannot create system carrier event by manual.', 'RAS-0268 : 시스템 CARRIER EVENT는 임의로 생성할 수 없습니다.', 'RAS-0268 : System-Carrier Event kann nicht manuell erzeugt werden.', 'ADMIN', '20080924100704', 'ADMIN', '20081218111158');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0269', 'RAS', 'RAS-0269 : Cannot change system flag of Carrier Event.', 'RAS-0269 : 시스템 CARRIER를 일반 CARRIER로, 또는 일반 CARRIER를 시스템 CARRIER로 변경하는 것은 불가능 합니다.', 'RAS-0269 : Das Flag System des Carrier Events kann nicht geloescht werden.', 'ADMIN', '20080924100749', 'ADMIN', '20081218111348');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0270', 'RAS', 'RAS-0270 : Cannot delete system Carrier Event.', 'RAS-0270 : 시스템 CARRIER 이벤트는 임의로 삭제할 수 없습니다.', 'RAS-0270 : Das System-Carrier Event kann nicht geloescht werden.', 'ADMIN', '20080924100837', 'ADMIN', '20081218111549');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0271', 'RAS', 'RAS-0271 : The Number of Check Items / Change Items for a Carrier Event have a limit of 30.', 'RAS-0271 : CARRIER EVENT에서 지정할수 있는 CHECK ITEM, CHANGE ITEM의 갯수는 30개로 제한되어 있습니다.', 'RAS-0271 : Das Limit fuer Check Item bzw. Change Item fuer dieses Carrier Event liegt bei 30.', 'ADMIN', '20080924100932', 'ADMIN', '20081218111840');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0272', 'RAS', 'RAS-0272 : Carrier Event check flag must be ''N''(Not Check), ''=''(Equal), ''!''(Not Equal), ''<''(Less than), ''>''(Greater than).', 'RAS-0272 : CARRIER EVENT의 Check Flag 값은 N''(체크안함), ''=''(같음), ''!''(같지않음), ''<''(~보다작음), ''>''(~보다큼) 만 허용됩니다.', 'RAS-0272 : Das Flag Carrier EventCheck muss auf ''N''(Not Check), ''=''(Equal), ''!''(Not Equal), ''<''(Less than) oder ''>''(Greater than) gesetzt sein.', 'ADMIN', '20080924101244', 'ADMIN', '20081218111919');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0273', 'RAS', 'RAS-0273 : Overriding Change Item in one Carrier Event is not allowed.', 'RAS-0273 : 하나의 CARRIER EVENT에서 CHANGE ITEM은 중복해서 사용할 수 없습니다.', 'RAS-0273 : Es ist nicht erlaubt eine Change-Item eines Tool-Events zu aendern.', 'ADMIN', '20080924101650', 'ADMIN', '20081218112038');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0274', 'RAS', 'RAS-0274 : No have sublot movement information.', 'RAS-0274 : SUBLOT 이동 정보가 없습니다.', 'RAS-0274 : Keine SUBLOT Movement Informationen vorhanden.', 'ADMIN', '20080924160726', 'ADMIN', '20081218112142');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0275', 'RAS', 'RAS-0275 : The carrier status is not "WAIT", "INIT" or "CLEAN".', 'RAS-0275 : CARRIER 상태가 "WAIT", "INIT" 혹은 "CLEAN"이 아닙니다.', 'RAS-0275 : CARRIER status ist nicht "WAIT", "INIT", "CLEAN".', 'ADMIN', '20080924160959', 'ADMIN', '20081218112206');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0276', 'RAS', 'RAS-0276 : The carrier status is not ''RESV''', 'RAS-0276 : CARRIER 상태가 ''RESV''가 아닙니다.', 'RAS-0276 : CARRIER status ist nicht ''RESV''.', 'ADMIN', '20080924161101', 'ADMIN', '20081218113340');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0277', 'RAS', 'RAS-0277 : The carrier reserved to use specific resource. Can not process.', 'RAS-0277 : 이 CARRIER는 특정 장비에 예약되어 있으므로 작업할 수 없습니다.', 'RAS-0277 : Da dieser CARRIER reserviert ist um spezielle Resourcen zu nutzen, kann es nicht bearbeitet werden.', 'ADMIN', '20080924193156', 'ADMIN', '20081218113444');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0278', 'RAS', 'RAS-0278 : Cannot raise event. The current carrier status is not same to carrier event setup for the carrier. Check carrier event setup.', 'RAS-0278 : CARRIER 이벤트를 발생 시킬 수 없습니다. 현재 CARRIER의 상태가 CARRIER 이벤트 설정과 일치하지 않습니다. CARRIER 이벤트 설정을 확인하십시요.', 'RAS-0278 : Es kann kein Event ausgeloest werden. Der aktuelle Carrier-Status ist nicht der gleiche wie im Carrier-Event-Setup. Ueberpruefen Sie das das Carrier-Event-Setup.', 'ADMIN', '20081027085118', 'ADMIN', '20081218113540');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0279', 'RAS', 'RAS-0279 : Cannot raise event. The current carrier status is same to carrier event setup for the carrier. Check carrier event setup.', 'RAS-0279 : 이벤트를 발생 시킬 수 없습니다. 현재 CARRIER 상태가 CARRIER 이벤트 설정과 일치합니다. CARRIER 이벤트 설정을 확인하십시요.', 'RAS-0279 : Es kann kein Event ausgeloest werden. Der aktuelle Carrier-Status ist identisch mit dem im Carrier-Event-Setup fuer dieses Carrier.', 'ADMIN', '20081027085229', 'ADMIN', '20081218113629');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0280', 'RAS', 'RAS-0280 : Cannot raise event. The current carrier status value is less than carrier event setup for the carrier. Check carrier event setup.', 'RAS-0280 : 이벤트를 발생 시킬 수 없습니다. 현재 CARRIER 상태 값이 CARRIER 이벤트 설정보다 작습니다. CARRIER 이벤트 설정을 확인하십시요.', 'RAS-0280 : Es kann keine Event ausgeloest werden. Der aktuelle Carrier-Status ist kleiner als im Carrier-Event-Setup. Ueberpruefen Sie das Carrier-Event-Setup.', 'ADMIN', '20081027085329', 'ADMIN', '20081218113707');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0281', 'RAS', 'RAS-0281 : Cannot raise event. The current carrier status value is greater than carrier event setup for the carrier. Check carrier event setup.', 'RAS-0281 : 이벤트를 발생 시킬 수 없습니다. 현재 CARRIER 상태 값이 CARRIER 이벤트 설정보다 큽니다. CARRIER 이벤트 설정을 확인하십시요.', 'RAS-0281 : Es kann keine Event ausgeloest werden. Der aktuelle Carrier-Satus ist groesser als im Carrier-Event-Setup. Ueberpruefen Sie das Carrier-Event-Setup.', 'ADMIN', '20081027085432', 'ADMIN', '20081218113740');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0282', 'RAS', 'RAS-0282 : The resource already has resource group. The resource can have only one resource group.', 'RAS-0282 : 장비에는 이미 장비그룹이 할당되어 있습니다. 장비는 한개의 장비그룹만을 가질수 있습니다.', 'RAS-0282 : Die Resource wurde bereits der Resource Gruppe zugeeordnet. Eine Resource kann nur eine Resourcegruppe haben.', 'ADMIN', '20090303153310', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0283', 'RAS', 'RAS-0283 : Access mode state is not correct. Please input A or M.', 'RAS-0283 : Access mode state 가 틀립니다. A 혹은 M을 입력하여주십시오', 'RAS-0283 : Zugriffsmodus ist nicht korrekt. Bitte geben Sie A oder M ein.', 'ADMIN', '20090303153310', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0284', 'RAS', 'RAS-0284 : Association state is not correct. Please input A or N.', 'RAS-0284 : Association mode state 가 틀립니다. A 혹은 N을 입력하여주십시오', 'RAS-0284 : Association mode state ist nicht korrekt. Bitte geben Sie A oder N ein.', 'ADMIN', '20090303153310', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0285', 'RAS', 'RAS-0285 : Reservation state is not correct. Please input R or N.', 'RAS-0285 : Reservation state 가 틀립니다. R 혹은 N을 입력하여주십시오', 'RAS-0285 : Reservierungszustand ist nicht korrekt. Bitte geben Sie R oder N ein.', 'ADMIN', '20090303153310', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0286', 'RAS', 'RAS-0286 : Data Code is not existed.', 'RAS-0286 : Data Code 가 존재하지 않습니다.', 'RAS-0286 : Datencode existiert nicht.', 'ADMIN', '20090303153310', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0287', 'RAS', 'RAS-0287 : Sub Resource and Parent Sub Resource cannot be same.', 'RAS-0287 : 서브 리소스와 부모 서브 리소스는 같을 수 없습니다.', 'RAS-0287 : Sub Resource und Parent Sub Resource durfen nicht identisch sein.', 'ADMIN', '20090303153310', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0288', 'RAS', 'RAS-0288 : History Sequence and last active history are not matched or Event ID and Last Event ID are not matched', 'RAS-0288 : 히스토리 시퀸스 와 최근 사용된 히스토리 시퀸스가 같지 않거나 이벤트 이름과 최근 이벤트 이름이 같지 않습니다.', 'RAS-0288 :  History Sequence und die Last active history stimmen nicht ueberein oder Event ID und Last Event ID stimmen nicht ueberein.', 'ADMIN', '20090303153310', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0289', 'RAS', 'RAS-0289 : The sub resource does not exist.', 'RAS-0289 : 서브 리소스가 존재하지 않습니다.', 'RAS-0289 : Dieser Sub Resource existiert nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0290', 'RAS', 'RAS-0290 : This sublot is located in carrier already.', 'RAS-0290 : 이 Sublot 는 이미 CARRIER에 속해 있습니다.', 'RAS-0290 : Dieser Sublot ist bereits im CARRIER platziert.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0291', 'RAS', 'RAS-0291 : This slot is occupied by another slot.', 'RAS-0291 : 이 SLOT NO는 이미 다른 SUBLOT에 사용 중입니다.', 'RAS-0291 : Diese SLOT Nummer wird bereits von einem anderen SUBLOT benutzt.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0292', 'RAS', 'RAS-0292 : The factory of input lot no match with the assigned lots factory into carrier.', 'RAS-0292 : 입력 LOT의 FACTORY는 CARRIER에 이미 할당된 LOT와 다릅니다.', 'RAS-0292 : Eingegebene LOT FACTORY unterscheidet sich vom bereits zugeordneten Los im Carrier.', 'ADMIN', '20090515231051', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0293', 'RAS', 'RAS-0293 : The factory of input lot no match with the carrier.', 'RAS-0293 : 입력 LOT의 FACTORY는 CARRIER의 FACTORY와 다릅니다.', 'RAS-0293 : Eingegebene LOT FACTORY unterscheidet sich vom CARRIER FACTORY.', 'ADMIN', '20090518004709', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0294', 'RAS', 'RAS-0294: This lot has sublots. Please input sublot list information to attach lot to carrier.', 'RAS-0294 : 입력 LOT은 SUBLOT을 가지고 있습니다. LOT을 CARRIER에 할당하기 위해서는 SUBLOT 정보를 입력해 주십시오.', 'RAS-0294 : Eingebenes Los hat Sublots. Geben Sie Sublot Informationen ein, um das Los dem Carrier zuzuordnen.', 'ADMIN', '20090520052649', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0295', 'RAS', 'RAS-0295 : The input detach quantity is greater than attached lot quantity in carrier.', 'RAS-0295 : CARRIER에 할당된 LOT의 수량보다 많은 수량이 입력되었습니다.', 'RAS-0295 : Die eingegebene Menge ist groesser als die dem Carrier zugeordnete Losanzahl.', 'ADMIN', '20090520070836', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0296', 'RAS', 'RAS-0296 : This service is successful. But it did not make relationship carrier and lot, it did not input quantity for attach or detach lot to carrier.', 'RAS-0296 : 작업을 성공적으로 수행하였으나, CARRIER에 LOT을 할당 또는 분리하기 위한 수량이 입력되지 않아 CARRIER와 LOT간의 관계는 형성되지 않았습니다.', 'RAS-0296 : Service war erfolgreich. Aber um CARRIER LOT zuzuordnen oder zu trennen, fehlt die Mengenangabe und das Verhaeltnis zwischen CARRIER und LOT festzustellen.', 'ADMIN', '20090529132534', 'ADMIN', '20090529135526');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0297', 'RAS', 'RAS-0297 : This Resource has relation with Resource Group. Please try again after breaking off relation resource and resource group.', 'RAS-0297 : 이 장비와 장비그룹간에 관계가 있습니다. 이 관계를 풀고 다시 실행해 주십시오.', 'RAS-0297 : Resource und Resource Gruppe sind verknuepft. Fuehren Sie es erneut aus nachdem die Verbindung geloest wurde.', 'ADMIN', '20090604154933', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0298', 'RAS', 'RAS-0298 : This resource has relation with MFO. Please try again after breaking off relation resource and MFO.', 'RAS-0298 : 이 장비와 사용 가능한 MFO간에 관계가 있습니다. 이 관계를 풀고 다시 실행해 주십시오.', 'RAS-0298 : Resource und MFO sind verknuepft. Fuehren Sie es erneut aus nachdem die Verbindung geloest wurde.', 'ADMIN', '20090604160317', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0299', 'RAS', 'RAS-0299 : You cannot delete this resource because the resource has history.', 'RAS-0299 : 이 장비는 이력이 존재하기 때문에 삭제할 수 없습니다.', 'RAS-0299 : Resource kann nicht geloescht werde, da sie eine History hat.', 'ADMIN', '20070830140906', 'ADMIN', '20081217172742');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0300', 'RAS', 'RAS-0300 : You cannot delete this sub resource because the sub resource has history.', 'RAS-0300 : 이 서브 장비는 이력이 존재하기 때문에 삭제할 수 없습니다.', 'RAS-0300 : Dieses Sub-equipment kann nicht geloescht werden, da es eine History besitzt.', 'ADMIN', '20070830140906', 'ADMIN', '20081217172742');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0301', 'RAS', 'RAS-0301 : No have carrier slot history.', 'RAS-0301 : Carrier Slot 이력을 찾지 못했습니다.', 'RAS-0301 : Carrier Slot History kann nicht gefunden werden.', 'ADMIN', '20091120172927', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0302', 'RAS', 'RAS-0302 : Cannot raise an event. The elapsed time of current tool status is less than the time for tool event setup. Check tool event setup.', 'RAS-0302 : 이벤트를 발생 시킬 수 없습니다. 현재 TOOL상태의 경과 시간값이 TOOL 이벤트 설정시간보다 작습니다. TOOL 이벤트 설정을 확인하십시요.', 'RAS-0302 : Event kann nicht generiert werden. Die abgelaufene Zeit des aktuellen Tool Status ist geringer als die die fuer Tool Event Setup. Bitte ueberpruefen Sie Tool Event Setup.', 'ADMIN', '20100507153339', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0303', 'RAS', 'RAS-0303 : Cannot raise an event. The elapsed time of current tool status is higher than the time for tool event setup. Check tool event setup.', 'RAS-0303 : 이벤트를 발생 시킬 수 없습니다. 현재 TOOL상태의 경과 시간값이 TOOL 이벤트 설정시간보다 큽니다. TOOL 이벤트 설정을 확인하십시요.', 'RAS-0303 : Event kann nicht generiert werden. Die abgelaufene Zeit des aktuellen Tool Status ist hoeher als die die fuer Tool Event Setup. Bitte ueberpruefen Sie Tool Event Setup.', 'ADMIN', '20100507153436', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0304', 'RAS', 'RAS-0304 : Please enter a value of carrier size which is greater than 0.', 'RAS-0304 : 0보다 큰 Carrier Size 값을 입력해 주세요.', 'RAS-0304 : Bitte geben Sie einen "Carrier Size" Wert groesser 0 ein.', 'ADMIN', '20100527083406', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0305', 'RAS', 'RAS-0305 : This field requires a positive number. Please enter a positive number.', 'RAS-0305 : 이 필드에는 양수를 입력해야 합니다. 확인 후 다시 입력해 주십시오.', 'RAS-0305 : Dieses Eingabefeld verlangt positve Zahlen. Bitte geben Sie  positive Zahlen ein.', 'ADMIN', '20100528101701', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0306', 'RAS', 'RAS-0306 : Invalid slot change mode. Slot change mode should be "ST", "SF" , "XC", "XF" or "AD".', 'RAS-0306 : 유효하지 않은 캐리어 슬롯 변경 모드 입니다. 캐리어 슬롯 변경 모드는 "ST", "SF" , "XC", "XF" 혹은, "AD" 중 하나이어야 합니다.', 'RAS-0306 : Ungueltiger Carrier-Slot Aenderungsmodus, gueltige werte sind "ST", "SF" , "XC", "XF" oder "AD".', 'ADMIN', '20100930164539', 'ADMIN', '20100930165437');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0307', 'RAS', 'RAS-0307 : Carrier-change point is invalid. Carrier-change point should be "A", "S" or "E".', 'RAS-0307 : 유효하지 않은 캐리어 변경 포인트 입니다. 캐리어 변경 포인트는 "A", "S", "E" 중 하나여야 합니다.', 'RAS-0307 : Ungueltiger Carrier aendern Punkt, gueltige Werte sind "A", "S" , oder "E".', 'ADMIN', '20100930164539', 'ADMIN', '20120203163730');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RCP-0000', 'RCP', 'RCP-0000 :  This  process step number is not supported. Please check the process step number.', 'RCP-0000 : 지원되지 않는 STEP입니다. 다시 확인 하십시요.', 'RCP-0000 : Diese Prozess Ablaufnummer wird nicht unterstuetzt. Bitte ueberpruefen sie die Prozess-Ablaufnummer.', 'ADMIN', '20050616160527', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RCP-0001', 'RCP', 'RCP-0001 : A required field is empty. Please enter a valid value.', 'RCP-0001 : 이 항목은 필요한 필드 입니다. 입력 바랍니다.', 'RCP-0001 : Ein erforderliches Eingabefeld ist leer. Bitte geben Sie gueltige Daten ein.', 'ADMIN', '20081201010101', ' ', ' ');
