INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RCP-0006', 'RCP', 'RCP-0006 : This item does not existed in GCM Table.', 'RCP-0006 : 이 아이템은 GCM 테이블에 존재하지 않습니다.', 'RCP-0006 : Dieses Item existiert in der GCM Tabelle nicht.', 'ADMIN', '20081201010101', ' ', ' ');
