INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RCP-0035', 'RCP', 'RCP-0035 : This recipe version is not approved. Please approve first.', 'RCP-0035 : 승인이 필요한 레시피 버전입니다. 먼저 승인을 하세요.', 'RCP-0035 : Diese Recipe-Version ist nicht approved. Bitte tun Sie dies zuerst.', 'ADMIN', '20050621104625', ' ', ' ');
