INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0056', 'WIP', 'WIP-0056 : This port is already used by another lot.', 'WIP-0056 : 이 PORT는 이미 다른 LOT이 사용 중입니다.', 'WIP-0056 : Dieser Port wird bereits durch ein anderes Lot verwendet.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0057', 'WIP', 'WIP-0057 : This lot is not included in this resource.', 'WIP-0057 : 이 LOT은 이 장비에 속해 있지 않아  진행할 수 없습니다.', 'WIP-0057 : Dieses Lot ist nicht in dieser Resource inkludiert.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0058', 'WIP', 'WIP-0058 : This lot is already processing.', 'WIP-0058 : 이 LOT은 이미 진행 중입니다.', 'WIP-0058 : Dieses wurde bereits prozessiert.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0059', 'WIP', 'WIP-0059 : This lot is on hold. Release it first.', 'WIP-0059 : 이 LOT은 HOLD 중입니다. RELEASE 후 사용 하세요.', 'WIP-0059 : Dieses Los ist auf Hold, setzen Sie es zuerst auf Release.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0060', 'WIP', 'WIP-0060 : The Lot is in shipping. Please Receive the Lot first.', 'WIP-0060 : 이 LOT은 SHIPPING 중입니다. RECEIVE 후 사용 하세요.', 'WIP-0060 : Dieses Lot wird zur Zeit transportiert. Empfangen Sie es zuerst.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0061', 'WIP', 'WIP-0061 : This lot is in store operation. Unstore it first.', 'WIP-0061 : 이 LOT은 STORE 공정에 있습니다. UNSTORE 후 사용 하세요.', 'WIP-0061 : Diess Lot ist in einer Store-Operation. Rufen Sie zuerst Unstore auf.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0062', 'WIP', 'WIP-0062 : This lot is in a shipping operation. This transaction is impossible.', 'WIP-0062 : 이 LOT은 SHIPPING 공정에 있습니다. SHIPPING 공정에서는 이 작업을 할 수 없습니다.', 'WIP-0062 : Dieses Lot ist in einer Shipping-Operation. Diese Transaktion ist nicht moeglich.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0063', 'WIP', 'WIP-0063 : Current factory does not match with factory of lot.', 'WIP-0063 : LOT의 공장이 현재 공장과 일치 하지 않습니다. LOT을 확인 하세요.', 'WIP-0063 : Die aktuelle Factory stimmt nicht mit der Factory-ID ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0064', 'WIP', 'WIP-0064 : Current material does not match with material of lot.', 'WIP-0064 : LOT의 제품이 현재 제품과 일치 하지 않습니다. LOT을 확인 하세요.', 'WIP-0064 : Das aktuelle Material stimmt nicht mit dem Material des Loses ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0065', 'WIP', 'WIP-0065 : Current flow does not match with flow of lot.', 'WIP-0065 : LOT의 FLOW 현재 FLOW와 일치 하지 않습니다. LOT을 확인 하세요.', 'WIP-0065 : Der aktuelle Floe stimmt nicht mit dem Flow des Loses ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0066', 'WIP', 'WIP-0066 : Current operation does not match with operation of lot.', 'WIP-0066 : LOT의 공정이 현재 공정과 일치 하지 않습니다. LOT을 확인 하세요.', 'WIP-0066 : Die aktuelle Operation stimmt nicht mit der Operatin des Loses ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0067', 'WIP', 'WIP-0067 : The Lot ID in Carrier table and Lot ID in Lot table is different. Please contact Administrator.', 'WIP-0067 : 카세트의 LOT ID와 LOT의 LOT ID가 일치 하지 않습니다. 관리자에게 문의 하세요.', 'WIP-0067 : Die Lot-ID des Carrier und die Lot-ID stimmen nicht ueberein. Bitte kontaktieren Sie einen Administrator.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0068', 'WIP', 'WIP-0068 : The input transaction time must be future time than the last transaction time.', 'WIP-0068 : 수정된 TRANSACTION TIME은 마지막 진행 시간보다 미래여야 합니다.', 'WIP-0068 : Die Input-Transaction-Time muss nach der letzren Transaction-Time liegen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0069', 'WIP', 'WIP-0069 : This operation require "start" transaction. Do a move in first.', 'WIP-0069 : 이 공정은 START가 필요한 공정 입니다. 먼저 START 후 사용 하세요.', 'WIP-0069 : Diese Operation benoetigt eine Start-Transaction. Fuhren Sie zuerst ein Move-In durch.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0070', 'WIP', 'WIP-0070 : This lot is reserved or moved to another resource. Please check resource id.', 'WIP-0070 : 이 LOT은 다른 장비에서 진행 중이거나 예약 되어 있습니다. 장비 번호를 확인 하세요.', 'WIP-0070 : Dieses Lot ist  Reserved oder wurde zu einer anderen Resource Moved. Bitte ueberpruefen Sie die Resourcen ID.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0071', 'WIP', 'WIP-0071 : This is sample lot. Please merge the sample.', 'WIP-0071 : 이 LOT은 SAMPLE 입니다. 먼저 SAMPLE MERGE 후 진행 하세요.', 'WIP-0071 : Dies ist ein Sample-Lot. Mergen Sie das Sample.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0072', 'WIP', 'WIP-0072 : This resource is disabled for this operation. Please check MFO(Material-Flow-Oper) OPTION.', 'WIP-0072 : 이 장비는 현공정에서 사용 할 수 없는 장비 입니다. DFO(Device-Flow-Oper) OPTION을 확인 하세요.', 'WIP-0072 : Diese Resource ist Disabled fuer diese Operation. Bitte ueberpruefen Sie die MFO(Material-Flow-Oper) OPTION.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0073', 'WIP', 'WIP-0073 : This operation is the last operation for the material.', 'WIP-0073 : 이 공정은 제품의 마지막 공정입니다. 더이상 진행 할 수 없습니다.', 'WIP-0073 : Diese ist die letze Operation fuer das Material.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0074', 'WIP', 'WIP-0074 : This operation requires to_flow, to_operation. Please enter this fields.', 'WIP-0074 : 이 공정은 TO FLOW,TO OPERATION이 필요 합니다. 이 항목을 입력하세요.', 'WIP-0074 : Diese Operation verlangt nach to_flow und to_operation. Bitte geben Sie die Felder ein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0075', 'WIP', 'WIP-0075 : This lot exists at another factory. Please check lot id.', 'WIP-0075 : 이 LOT은 다른 공장에 존재 합니다. LOT을  확인 하세요.', 'WIP-0075 : Dieses Lot existiert in einer anderen Factory. Bitte ueberpruefen Sie die Lot ID.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0076', 'WIP', 'WIP-0076 : This lot is already deleted. Please check lot id.', 'WIP-0076 : 이 LOT은 이미 삭제된 LOT 입니다. LOT을  확인 하세요.', 'WIP-0076 : Dieses Lot wurde bereits geloescht. Bitte ueberpruefen Sie die Lot ID.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0077', 'WIP', 'WIP-0077 : At least one unit must be entered. Please enter unit.', 'WIP-0077 : 한개 이상의 UNIT을 입력 해야 합니다.', 'WIP-0077 : Es muss zumindest eine Unit eingegeben werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0078', 'WIP', 'WIP-0078 : Out qty must less or equal than current qty. Please check qty.', 'WIP-0078 : OUT 수량은 현재 수량 보다 작거나 같아야 합니다. 수량을 확인 하세요.', 'WIP-0078 : Die Out-Qty muss gleich oder wenige der Current-Qty sein. BItte ueberpruefen Sie die Qty.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0079', 'WIP', 'WIP-0079 : Duplicated loss code found. Please check loss code.', 'WIP-0079 : 중복 되는 LOSS CODE가 있습니다. LOSS CODE를 확인 하세요.', 'WIP-0079 : Es wurde ein Duplikat fuer den Loss-Code gefunden. Bitte ueberpruefen Sie den Loss-Code.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0080', 'WIP', 'WIP-0080 : Loss qty and out qty are not matching with current qty.', 'WIP-0080 : 각 LOSS CODE별 수량과 OUT 수량의 합이 현재 수량과 일치 하지 않습니다.', 'WIP-0080 : Die Loss-Qty und die Out-Qty stimmen nicht mir der Current-Qty ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0081', 'WIP', 'WIP-0081 : This rework code does not exist. Please check rework code.', 'WIP-0081 : 이 REWORK CODE는 SETUP되어 있지 않습니다. REWORK CODE를 확인하세요.', 'WIP-0081 : Dieser Rework-Code existiert nicht. Bitte ueberpruefen Sie den Rework-Code.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0082', 'WIP', 'WIP-0082 : This hold code does not exist. Please check hold code.', 'WIP-0082 : 이 HOLD CODE는 SETUP되어 있지 않습니다. HOLD CODE를 확인하세요.', 'WIP-0082 : Dieser Hold-Code existiert nicht. Bitte ueberpruefen Sie den Hold-Code.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0083', 'WIP', 'WIP-0083 : This lot is not on hold. Only hold lot can be released.', 'WIP-0083 : 이 LOT은 HOLD 중이 아닙니다. HOLD된 LOT만 RELEASE 할 수 있습니다.', 'WIP-0083 : Dieses Lot ist nicht auf Hold. Nur Hold-Lots koennen released werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0084', 'WIP', 'WIP-0084 : Invalid hold password is entered. Please enter valid password.', 'WIP-0084 : 입력한 HOLD PASSWORD 가 틀립니다. 정확한 PASSWORD를 다시 입력해 주십시오.', 'WIP-0084 : Ein ungueltiges Hold-Password wurde eingegeben. Bitte geben Sie ein gueltiges Passowrd ein.', 'ADMIN', '20081201010101', 'ADMIN', '20081217184719');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0085', 'WIP', 'WIP-0085 : This operation is set to prevent skip.', 'WIP-0085 : 이 공정은 SKIP 방지 공정으로 등록되어 SKIP 할 수 없습니다.', 'WIP-0085 : Diese Operation ist so konfiguriert, dass ein Skip vermieden wird.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0086', 'WIP', 'WIP-0086 : This lot is already started. This status does not permit current transaction.', 'WIP-0086 : 이 LOT은 START 상태 입니다. 이 상태에서는 현재 TRANSACTION을 사용할 수 없습니다.', 'WIP-0086 : Fuer dieses Lot wurde bereits ein Start durchgefuert. Dieser Status verhindert die aktuelle Transaktion.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0087', 'WIP', 'WIP-0087 : It is not possible to set Auto Skip Flag and Prevent Skip Flag at the same time.', 'WIP-0087 : AUTO SKIP FLAGS, PREVENT SKIP FLAG는 동시에 SETUP 될 수 없습니다.', 'WIP-0087 : Das Flag Auto-Skip alsauch das Flag Prevent-Skip sind zur gleichen Zeit gesetzt. Dies ist nicht erlaubt.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0088', 'WIP', 'WIP-0088 : This operation requires to_flow and to_operation. Please use "END" transaction.', 'WIP-0088 : 이 공정은 TO FLOW,TO OPERATION이 필요 합니다. END TRANSACTION을 사용 하세요.', 'WIP-0088 : Diese Operatin verlangt nach to_flow und to_operation. Bitte verwenden Sie die END-Transaction.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0089', 'WIP', 'WIP-0089 : Main lot flow does not match with flow of child lot.', 'WIP-0089 : MOTHER LOT의 FLOW와 CHILD LOT의 FLOW가 일치 하지 않습니다. LOT을 확인 하세요.', 'WIP-0089 : Der Main-Lot-Flow stimmt nicht mit dem des Child-Lot ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0090', 'WIP', 'WIP-0090 : Main lot operation does not match with operation of child lot.', 'WIP-0090 : MOTHER LOT의 공정과 CHILD LOT의 공정이 일치 하지 않습니다. LOT을 확인 하세요.', 'WIP-0090 : Die Operation des Main-Lot stimmt nicht mit der des Child-Lot ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0091', 'WIP', 'WIP-0091 : Due time has invalid format. Please check time format.', 'WIP-0091 : Due Time은 형식이 유효하지 않습니다. 형식을 확인 하세요.', 'WIP-0091 : Die Due-Time hat ein ungueltiges Format. Bitte ueberpruefen Sie das Format.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0092', 'WIP', 'WIP-0092 : Split or Merge qty is greater than mother qty. Please check qty.', 'WIP-0092 : SPLIT(MERGE) 할려고 하는 수량이 MOTHER의 양보다 많습니다. 수량을 확인 하세요.', 'WIP-0092 : Die Split- oder Merge-Qty ist groesser ald die Mother-Qty. Bitte ueberpruefen Sie die Qty.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0093', 'WIP', 'WIP-0093 : Mother lot and child lot have different processing status.', 'WIP-0093 : MOTHER LOT과 CHILD LOT이 모두 진행중 이거나 모두 진행중이 아니여야 합니다.', 'WIP-0093 : Das Mother- und Child-Lot haben unteschiedliche Processing-Status.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0094', 'WIP', 'WIP-0094 : Mother lot and child lot processing at different resource.', 'WIP-0094 : MOTHER LOT과 CHILD LOT이 서로 다른 장비에서 진행 중입니다.', 'WIP-0094 : Das Mother- und Child-Lot prozessieren an unteschiedlichen Resourcen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0095', 'WIP', 'WIP-0095 : This operation is no transit operation. Please check operation.', 'WIP-0095 : 이 공정은 INTRANSIT 공정이 아닙니다. 공정을 확인 하세요.', 'WIP-0095 : Diese Operation ist keine Transit-Operation. Bitte ueberpruefen Sie die Check-Operation.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0096', 'WIP', 'WIP-0096 : The specified Shipping Factory and Operation already exists.', 'WIP-0096 : 이 SHIPPING 공장,공정은 이미 존재 합니다.', 'WIP-0096 : Die spezifizierte Shipping-Factory und Operation existieren bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0097', 'WIP', 'WIP-0097 : The specified Shipping Factory and Operation does not exist.', 'WIP-0097 : 이 SHIPPING 공장,공정은 존재 하지 않습니다.', 'WIP-0097 : Die spezifizierte Shipping-Factory und Operation existieren nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0098', 'WIP', 'WIP-0098 : This shipping(transfer) factory is not setup. Please setup first.', 'WIP-0098 : 이 SHIPPING(TRANSFER) 공장은 등록 되어 있지 않습니다. 먼저 등록후 사용하세요.', 'WIP-0098 : Diese Shipping- Transfer-Factory ist nicht konfiguriert. Bitte konfigurieren Sie diese zuerst..', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0099', 'WIP', 'WIP-0099 : The Lot is not in Shipping (Transfer) Operation. It is only possible to make this transaction at Shipping (Transfer) Operation.', 'WIP-0099 : 이 LOT은 SHIPPING(TRANSFER) 공정에 있지 않습니다. SHIPPING(TRANSFER) 공정에서만 이 작업을 할 수 있습니다.', 'WIP-0099 : Das Lot befindet sich in keiner Shipping(Transfer) Operation. Diese Transaktion ist nur fuer Shipping(Transfer) Operation moeglich.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0100', 'WIP', 'WIP-0100 : This lot does not exist in transit operation. This lot was already received.', 'WIP-0100 : 이 LOT은 INTRANSIT 공정에 존재 하지 않습니다. 이미 RECEIVE 되었습니다.', 'WIP-0100 : Dieses Lot existiert in der Transit-Operation nicht. Dieses Lot wurde bereits received.', 'ADMIN', '20081201010101', ' ', ' ');
