INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0144', 'WIP', 'WIP-0144 : Current user can not use this operation. Please check user authorization (SECUSR).', 'WIP-0144 : 현 사용자는 이 공정을 사용할 권한이 없습니다. 사용 권한을 확인 하세요(SECUSR).', 'WIP-0144 : Der aktuelle User kann diese Operation nicht verwenden. Bitte ueberpruefen Sie die Autorisierung (SECUSR).', 'ADMIN', '20081201010101', ' ', ' ');
