INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0146', 'WIP', 'WIP-0146 : This is a transit operation. It can not receive at transit operation.', 'WIP-0146 : 이 공정은 INTRANSIT 공정 입니다. INTRANSIT 공정으로 RECEIVE 할 수 없습니다.', 'WIP-0146 : Dies ist eine Transit-Operation. Sie koennen nicht Receiven in einer  Transit-Operation.', 'ADMIN', '20081201010101', ' ', ' ');
