INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0233', 'WIP', 'WIP-0233 : Defect item does not exist at this resource .', 'WIP-0233 : 이 장비에는 DEFECT ITEM이 정의 되어 있지 않습니다.', 'WIP-0233 : Das Defect-Item existiert fuer diese Resource nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0234', 'WIP', 'WIP-0234 : Defect item already exists at this resource .', 'WIP-0234 : 이 장비에는 이미 DEFECT ITEM이 정의 되어 있습니다.', 'WIP-0234 : Das Defect-Item existiert fuer diese Resource bereits.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0235', 'WIP', 'WIP-0235 : Invalid collect type. Collect type should be "M" or "A".', 'WIP-0235 : 유효하지 않은 COLLECT TYPE 입니다. COLLECT TYPE은 "M", "A" 중 하나이어야 합니다.', 'WIP-0235 : Ungueltiger Collect-Type. Gueltie Werte sind "M" oder "A".', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0236', 'WIP', 'WIP-0236 : Default rework flow is not set at this MFO.', 'WIP-0236 : 이 DFO에는 DEFAULT REWORK FLOW가 설정 되지 않았습니다.', 'WIP-0236 : Der Default-Rework-Flow ist diesem MFO nicht zugewiesen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0237', 'WIP', 'WIP-0237 : Transfer can not use auto terminate. Please use shipping', 'WIP-0237 : TRANSFER에서는 자동 TERMINATE기능을 사용할 수 없습니다. SHIPPING을 사용하세요.', 'WIP-0237 : Der Transfer kann Auto-Terminate nicht verwenden. Bitte verwenden Sie Shipping.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0238', 'WIP', 'WIP-0238 : Start / end tracking flag can not be set at same time. Please set a flag.', 'WIP-0238 : START / END TRACKING FLAG를 동시에 설정 할 수 없습니다. 한개의 FLAG만 설정 하세요.', 'WIP-0238 : Die FlagsStart-  End-Tracking koennen nicht zur selben Zeit gesetzt werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0239', 'WIP', 'WIP-0239 : Sublot tracking flag does not exist at this operation.', 'WIP-0239 : 이 공정에는 SUBLOT TRACKING FLAG가 존재 하지 않습니다.', 'WIP-0239 : Das Flag Sub-Lot-Tracking existiert fuer diese Operation nicht.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0240', 'WIP', 'WIP-0240 : This field requires an integer. Please enter integer.', 'WIP-0240 : 이 항목은 정수가 아닙니다. 정수를 입력 하세요.', 'WIP-0240 : Dieses Eingabefeld verlangt ein Integer. Bitte geben Sie ein Integer ein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0241', 'WIP', 'WIP-0241 : This transaction can not create new unit.', 'WIP-0241 : 이 TRANSACTION은 새로운 UNIT을 생성할 수 없습니다.', 'WIP-0241 : Diese Transaktion kann keine neue Unit anlegen.', 'ADMIN', '20081201010101', 'ADMIN', '20081217184921');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0242', 'WIP', 'WIP-0242 : Sublot can not create new unit.', 'WIP-0242 : SUBLOT에 새로운 UNIT을 생성 할 수 없습니다.', 'WIP-0242 : Das Sub-Lot kann keine Unit anlegen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0243', 'WIP', 'WIP-0243 : Carrier and lot information are not matching.', 'WIP-0243 : LOT과 카세트의 CST_ID,LOT_ID정보가 일치 하지 않습니다.', 'WIP-0243 : Carrier und Lot-Information stimmen nicht ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0244', 'WIP', 'WIP-0244 : New unit is found. Please enter new unit quantity.', 'WIP-0244 : 새로운 UNIT이 발견 되었습니다. 새로운 UNIT의 수량을 입력하세요', 'WIP-0244 : Es wurde eine neue Unit gefunden. Geben Sie die Menge fuer die Einheit an.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0245', 'WIP', 'WIP-0245 : This operation has a lot. This operation can not deleted.', 'WIP-0245 : 이 공정에는 LOT이 존재합니다. 이 공정을 삭제 할 수 없습니다.', 'WIP-0245 : Diese Operation hat ein Lot. Diese Operation kann nicht geloescht weden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0246', 'WIP', 'WIP-0246 : This operation is a transit operation. It is impossible to attach at flow.', 'WIP-0246 : 이 공정은 INTRANSIT 공정 입니다. 이 공정은 FLOW에 들어갈 수 없습니다.', 'WIP-0246 : Dies ist eine Transit-Operation, deshalb ist es nicht moeglich einen Flow zu zuzuordnen.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0247', 'WIP', 'WIP-0247 : Some flow use this operation. Transit flag can not be set.', 'WIP-0247 : 이 공정은 FLOW에서 사용 중입니다. INTRANSIT 공정으로 지정 할 수 없습니다.', 'WIP-0247 : Ein Flow verwendet diese Operation, deshalb kann das Flag Transit nicht gesetzt werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0248', 'WIP', 'WIP-0248 : Shipping, Store, Start Required, End Oper flag can not be set at Transit operation.', 'WIP-0248 : INTRANSIT 공정에서는 SHIPPING FALG등의 다른 FLAG들이 설정될 수 없습니다.', 'WIP-0248 : Die Flags Shipping, Store, Start Required, End Oper koennen fuer eine Transit-Operation nicht gesetzt werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0249', 'WIP', 'WIP-0249 : This operation has lot. Transit flag can not modified.', 'WIP-0249 : 이 공정에는 LOT이 존재합니다. 이 공정의 INTRANSIT FLAG를 수정 할 수 없습니다.', 'WIP-0249 : Diese Operation hat ein Lot, deshalb kann das Flag Transit nicht veraendert werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0250', 'WIP', 'WIP-0250 : To flow,oper is the same as return flow,oper. This is not allowed.', 'WIP-0250 : TO FLOW, OPER가 RETURN FLOW,OPER 와 같을 수 없습니다. 특별한 이유가 없는한 RETURN FLOW,OPER는 입력이 필요 없습니다.', 'WIP-0250 : Der To-Flow-Oper ist identisch mit dem Return-Flow-Oper. Dies ist nicht erlaubt.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0251', 'WIP', 'WIP-0251 : SYSTEM FACTORY is default factory. It can not be deleted.', 'WIP-0251 : SYSTEM 공장은 삭제 할 수 없습니다. 이 공장은 DEFAULT 공장 입니다.', 'WIP-0251 : SYSTEM FACTORY ist die standard Factory. Sie kann nicht geloescht werden.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0252', 'WIP', 'WIP-0252 : This factory has lot. Please delete lot first.', 'WIP-0252 : 이 공장에는 LOT이 존재 합니다. 먼저 LOT을 지운 후 지우세요.', 'WIP-0252 : Diese Factory hat ein Lot. Bitte loeschen sie dieses Lot zuerset.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0253', 'WIP', 'WIP-0253 : Deleting factory is used by another factory as shiping factory.', 'WIP-0253 : 삭제할 공장을 다른 공장에서 SHIPPING 공장으로 설정 하고 있습니다.', 'WIP-0253 : Die zu loeschende Factory wird durch eine andere Factory als Shiping-Factory verwendet.', 'ADMIN', '20081201010101', ' ', ' ');
