INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0255', 'WIP', 'WIP-0255 : Current resource and change resource is the same. Please check resource.', 'WIP-0255 : 현재 장비와 바뀔 장비가 동일합니다. 장비를 확인 하세요.', 'WIP-0255 : Die Current-Resource und die Change-Resource sind identisch. Bitte ueberpruefen Sie die Resource.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0256', 'WIP', 'WIP-0256 : Current carrier does not match with carrier of lot.', 'WIP-0256 : LOT의 카세트가 현재 카세트와 일치 하지 않습니다. LOT을 확인 하세요.', 'WIP-0256 : Der Current-Carrier stimmt nicht mit Carrier des Lot ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0257', 'WIP', 'WIP-0257 : This is a Transit Operation. It is impossible to unstore Lot in Transit Operation.', 'WIP-0257 : 이 공정은 INTRANSIT 공정입니다. INTRANSIT 공정으로 UNSTORE할 수 없습니다.', 'WIP-0257 : Dies ist eine Transit-Operation. Es ist nicht moeglich ein Unstore fuer ein Lot durchzufuehren.', 'ADMIN', '20081201010101', ' ', ' ');
