INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0261', 'WIP', 'WIP-0261 : Main lot material does not match with material of child lot.', 'WIP-0261 : MOTHER LOT의 MATERIAL과 CHILD LOT의 MATERIAL이 일치 하지 않습니다. LOT을 확인 하세요.', 'WIP-0261 : Das Material des Lot stimmt nicht mit dem des Child-Lot ueberein.', 'ADMIN', '20081201010101', ' ', ' ');
