INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0268', 'WIP', 'WIP-0268 : The relation between the current Shift and previous Shift is invalid.', 'WIP-0268 : 현재 SHIFT와 이전 SHIFT와의 관계가 부적합합니다.', 'WIP-0268 : Die Relation zwischen der aktuellen und der vorhergehenden Shift ist ungueltig.', 'ADMIN', '20081201010101', ' ', ' ');
