INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0271', 'WIP', 'WIP-0271 : A rework flow for this condition already exists.', 'WIP-0271 : 조건의 Rework Flow가 이미 존재합니다.', 'WIP-0271 : Ein Rework-Flow fuer diese Condition existiert bereits.', 'ADMIN', '20081201010101', ' ', ' ');
