INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0273', 'WIP', 'WIP-0273 : No history for hold lot exists.', 'WIP-0273 : HOLD LOT 이력이 존재하지 않습니다.', 'WIP-0273 : Es existiert keine Historie fuer dieses Hold-Lot.', 'ADMIN', '20081201010101', ' ', ' ');
