INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0277', 'WIP', 'WIP-0277 : HpU PROC TIME is 1 / UpH PROC TIME.', 'WIP-0277 : HpU PROC TIME은 1 / UpH PROC TIME 입니다.', 'WIP-0277 : HpU PROC TIME ist 1 / UpH PROC TIME.', 'ADMIN', '20050120175204', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0278', 'WIP', 'WIP-0278 :  Can not move operation. Because this operation is PULL operation.', 'WIP-0278 : 이 공정은 PULL 공정이므로 이동할 수 없습니다.', 'WIP-0278 : Ein Move fuer diese Operation ist nicht moeglich. da es sich um eine PULL-Opeation handelt.', 'ADMIN', '20050203092650', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0279', 'WIP', 'WIP-0279 :  Can not move operation in PUSH operation. Use ''END'' transaction.', 'WIP-0279 : PUSH공정에서는 MOVE할 수 없습니다. END TRANSACTION을 사용하세요.', 'WIP-0279 : Die Operation kann durch Move nicht in eine PUSH-Operation umgewandelt werden. Verwenden Sie die END-Transaktion.', 'ADMIN', '20050203115637', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0280', 'WIP', 'WIP-0280 : This operation requires "END" transaction. End Lot first.', 'WIP-0280 : 이 공정은 END가 필요한 공정 입니다. 먼저 END 후 사용 하세요.', 'WIP-0280 : Diese Operation verlangt eine End-Transaktion. Fuehren Sie zuerst ein End Lot durch.', 'ADMIN', '20050203162807', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0281', 'WIP', 'WIP-0281 : The specified To Flow is in the same Optional Flow Group with the current Flow. Please input other To Flow.', 'WIP-0281 : 현 FLOW와 다음 FLOW는 동일 GROUP입니다. 다음 FLOW를 다시 입력해 주십시오.', 'WIP-0281 : Der spezifizierte To-Flow ist in der gleichen Optional-Flow-Group wie der aktuelle Flow. Bitte geben Sie einen anderen To-Flow ein.', 'ADMIN', '20050203115637', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0282', 'WIP', 'WIP-0282 : The first Operation of the specified To Flow is set as Optional Operation Group. Please input To Operation.', 'WIP-0282 : 다음 FLOW의 첫 공정은 GROUP으로 설정되어 있습니다. 다음 공정을 입력해 주십시오.', 'WIP-0282 : Die erste Operation des spezifizierten To-Flow ist der Optional-Operation-Group zugewiesen. Bitte geben Sie die To-Operation ein.', 'ADMIN', '20050203115637', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0283', 'WIP', 'WIP-0283 : This lot is using this hold code already. Use different hold code.', 'WIP-0283 : 입력된 HOLD CODE 는 이미 LOT에 사용되었습니다. 다른 HOLD CODE를 입력해 주십시오.', 'WIP-0283 : Dieser Lot verwendet diesen Holde-Code bereits, verwenden Sie einen anderen Holde-Code.', 'ADMIN', '20050311101959', 'ADMIN', '20081217184418');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0284', 'WIP', 'WIP-0284 : No history for the Hold Code. Please input another Hold Code.', 'WIP-0284 : 이 HOLD CODE로 HOLD된 이력이 없습니다. 다른 HOLD CODE를 입력하세요.', 'WIP-0284 : Fuer den Hold-Code existiert keine Historie, geben Sie einen anderen Hold-Code ein.', 'ADMIN', '20050311144354', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0285', 'WIP', 'WIP-0285 : A repair operation for this condition already exists.', 'WIP-0285 : 조건의 Repair Operation이 이미 존재합니다.', 'WIP-0285 : Eine Repair-Operation fuer diese Condition existiert bereits.', 'ADMIN', '20050406162659', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0286', 'WIP', 'WIP-0286 : This condition repair operation does not exist.', 'WIP-0286 : 조건의 Repair Operation이 존재하지 않습니다.', 'WIP-0286 : Die Repair Operation existiert nicht.', 'ADMIN', '20050406162733', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0287', 'WIP', 'WIP-0287 : Can not END without START in PULL Operation.', 'WIP-0287 : PULL 공정에서는 START 없이 END할 수 없습니다.', 'WIP-0287 : Ohne ein START in der PULL Operation gibt es kein END.', 'ADMIN', '20050413151221', ' ', ' ');
