INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0289', 'WIP', 'WIP-0289 : This Lot is not repaired. Please check Lot ID.', 'WIP-0289 : 이 Lot은 Repair중이 아닙니다. Lot ID를 확인하십시오.', 'WIP-0289 : Dieses Lot ist nicht repariert. Bitte ueberpruefen Sie die Lot ID.', 'ADMIN', '20050413151221', ' ', ' ');
