INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0291', 'WIP', 'WIP-0291 : This is required sublot for transaction. Please enter sublot info.', 'WIP-0291 : 이 Transaction을 위해서는 SUBLOT이 필요합니다.', 'WIP-0291 : Dieses Sub-Lot wird fuer die Transaction benoetigt. Bitte geben Sie bitte die Sub-Lot-Info ein.', 'ADMIN', '20081201010101', ' ', ' ');
