INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0293', 'WIP', 'WIP-0293 : This transaction is not support to sublot bundle.', 'WIP-0293 : 이 Transaction은 Sublot을 묶음으로 처리할수 없습니다.', 'WIP-0293 : Diese Transaction wird nicht fuer Sublot-Bundle unterstuetzt.', 'ADMIN', '20081201010101', ' ', ' ');
