INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0323', 'WIP', 'WIP-0323 : This lot has no trouble solve comment. Please input trouble solve comment.', 'WIP-0323 : 이 Lot의 이상발생 조치 결과가 입력되지 않았습니다. 먼저 이상발생 조치결과를 입력하시고 Release하세요.', 'WIP-0323 : Diese Lot hat keinen Trouble-Solve-Comment. Bitte geben Sie einen ein.', 'ADMIN', '20060201174652', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0324', 'WIP', 'WIP-0324 : The Unit between the last Operation of the Lot and new Operation is not same.', 'WIP-0324 : 현재의 공정과 새로운 공정의 UNIT이 일치하지 않습니다.', 'WIP-0324 :  Die Unit der letzten Operation des Sub-Lot und des Lot ist nicht gleich.', 'ADMIN', '20060410153024', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0325', 'WIP', 'WIP-0325 : The PULL operation does not require rework_flow, rework_operation.', 'WIP-0325 : PULL 공정에서는 REWORK FLOW/OPERATION 이 필요없습니다.', 'WIP-0325 : Die PULL-Operation benoetigt weder Rework-Flow noch Rework-Operation.', 'ADMIN', '20060410174913', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0326', 'WIP', 'WIP-0326 : If the lot is working or a start resource exists then unstore only stored flow-operation.', 'WIP-0326 : 작업중이거나 Start Resource가 존재하는 경우에는 Store 보낸 플로우-공정으로만 Unstore 가능합니다.', 'WIP-0326 : Wenn das Lot prozessiert wird oder eine Start-Resource vorhanden ist, darf Unstore nur fuer Stored-Flow-Operation aufgerufen werden.', 'ADMIN', '20060413174224', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0327', 'WIP', 'WIP-0327 : This carrier and slot number is duplicated with other sublot.', 'WIP-0327 : 이 SUBLOT의 CARRIER와 SLOT 번호가 동일한 다른 SUBLOT이 존재합니다.', 'WIP-0327 : Dieser Carrier und Slot-Number sind gleich mit anderen Sub-Lots.', 'ADMIN', '20060419101420', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0328', 'WIP', 'WIP-0328 : The calendar ID cannot use the same name as factory name.', 'WIP-0328 : 캘린더 ID는 Factory 이름과 동일한 이름을 사용할 수 없습니다.', 'WIP-0328 : Die Calendar-ID darf nicht mit dem Factory-Name uebereinstimmen.', 'ADMIN', '20060524105116', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0329', 'WIP', 'WIP-0329 : The material was deleted. Please check material id.', 'WIP-0329 : 이 제품은 삭제되었습니다. 제품 ID를 확인하세요.', 'WIP-0329 : Dieses Material wurde bereits geloescht. Bitte ueberpruefen Sie die Material-ID.', 'ADMIN', '20081201010101', 'ADMIN', '20081218134018');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0330', 'WIP', 'WIP-0330 : The material was deactivated. Please check material id.', 'WIP-0330 : 이 제품은 사용되지 않습니다. 제품 ID를 확인하세요.', 'WIP-0330 : Dieses Material wurde bereits deaktiviert. Bitte ueberpruefen Sie die Material-ID.', 'ADMIN', '20081201010101', 'ADMIN', '20081218134113');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0331', 'WIP', 'WIP-0331 : Current material version does not match with material version of lot.', 'WIP-0331 : 현재 제품 버전이 LOT의 제품 버전과 일치하지 않습니다.', 'WIP-0331 : Das Current-Material stimmt nicht mit der Material-Version des Lot ueberein.', 'ADMIN', '20081201010101', 'ADMIN', '20081218134254');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0332', 'WIP', 'WIP-0332 : Current flow sequence does not match with flow sequence of lot.', 'WIP-0332 : 현재 FLOW SEQ와 LOT의 FLOW SEQ가 일치하지 않습니다.', 'WIP-0332 : Die Current-Flow-Sequence stimmt nicht mit der Flow-Sequence des Lot ueberein.', 'ADMIN', '20081201010101', 'ADMIN', '20081218134325');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0333', 'WIP', 'WIP-0333 : If a start resource exists the same resource must also exist for child lot operation.', ' ', 'WIP-0333 : Wenn eine Start-Resource existiert, muss die selbe Resource auch fuer die Child-Lot-Operation exitieren.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0334', 'WIP', 'WIP-0334 : This Option Prompt does not exist.', 'WIP-0334 : 이 OPTION PROMPT는 존재하지 않습니다.', 'WIP-0334 : Diesers Option-Prompt existiert nicht.', 'ADMIN', '20081201010101', 'ADMIN', '20081218135122');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0335', 'WIP', 'WIP-0335 : This Option Prompt already exists.', 'WIP-0335 : 이 OPTION PROMPT는 이미 존재합니다.', 'WIP-0335 : Dieser Option-Prompt existiert bereits.', 'ADMIN', '20081201010101', 'ADMIN', '20081218135141');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0336', 'WIP', 'WIP-0336 : This option does not exist.', 'WIP-0336 : 이 OPTION은 존재하지 않습니다.', 'WIP-0336 : Diese Option existiert nicht.', 'ADMIN', '20081201010101', 'ADMIN', '20081218135157');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0337', 'WIP', 'WIP-0337 : This option already exists.', 'WIP-0337 : 이 OPTION은 이미 존재합니다.', 'WIP-0337 : Diese Option existiert bereits.', 'ADMIN', '20081201010101', 'ADMIN', '20081218135209');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0338', 'WIP', 'WIP-0338 : You can not delete this option prompt becase it is in use.', 'WIP-0338 : 이 OPTION PROMPT는 사용 중이기 때문에 삭제할 수 없습니다.', 'WIP-0338 : Dieser Option-Prompt kann nicht geloescht weden, da er in Verwendung ist.', 'ADMIN', '20081201010101', 'ADMIN', '20081218135235');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0339', 'WIP', 'WIP-0339 : Only numeric value is allowed. Please input again.', 'WIP-0339 : 숫자 형식의 값만 허용합니다. 다시 입력해주십시요.', 'WIP-0339 : Es sind nur numerische Werte erlaubt.', 'ADMIN', '20081201010101', 'ADMIN', '20081218135255');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0340', 'WIP', 'WIP-0340 : Integer value is only allowed. Please input again.', 'WIP-0340 : INTEGER 형식의 값만 허용합니다. 다시 입력해주십시요.', 'WIP-0340 : Es sind nur Integer-Werter erlaubt.', 'ADMIN', '20081201010101', 'ADMIN', '20081218135335');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0341', 'WIP', 'WIP-0341 : The lot does not have zero quantity, but it does not have a sublot. This transaction can not be processed.', 'WIP-0341 : 이 LOT은 SUBLOT을 가지고 있지 않습니다. 그래서 이 TRANSACTION을 처리할 수 없습니다.', 'WIP-0341 : Das Lot hat zwar keine Zero-Quantity jedoch hat es kein Sub-Lot. Deshalb kann die Transaction nicht prozessiert werden.', 'ADMIN', '20080128184916', 'ADMIN', '20081217184543');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0342', 'WIP', 'WIP-0342 : The move quantity and sublot count do not match.', 'WIP-0342 : 이동 수량과 SUBLOT 수량이 일치하지 않습니다.', 'WIP-0342 : Die Move-Quantity und der Sublot-Count stimmen nicht ueberein.', 'ADMIN', '20080213030155', 'ADMIN', '20081218142109');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0343', 'WIP', 'WIP-0343 : The lot does not have a sublot. But the sublot array has sublot information.', 'WIP-0343 : 이 LOT은 SUBLOT이 없습니다. 그러나 SUBLOT 배열에는 SUBLOT 정보를 가지고 있습니다.', 'WIP-0343 : Das Lot hat kein Sub-Lot, aber das Sub-Lot-Array hat Sub-Lot Informationen.', 'ADMIN', '20080213030431', 'ADMIN', '20081218142330');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0344', 'WIP', 'WIP-0344 : The lot does have a carrier. The carrier id is needed.', 'WIP-0344 : 이 LOT은 CARRIER를 가지고 있습니다. CARRIER ID가 필요합니다.', 'WIP-0344 : Das Lot hat einen Carrier, geben Sie die Carrier-ID an.', 'ADMIN', '20080213030535', 'ADMIN', '20081218142357');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0345', 'WIP', 'WIP-0345 : The sublot does have a carrier. Enter valid slot number.', 'WIP-0345 : 이 SUBLOT은 CARRIER를 가지고 있습니다. 유효한 SLOT 번호를 입력해주십시요.', 'WIP-0345 : Das Sub-Lot hat einen Carrier, geben Sie die Slot-Number an.', 'ADMIN', '20080213030656', 'ADMIN', '20081218142539');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0346', 'WIP', 'WIP-0346 : It is possible to set the system predefined prompt for the "SYSTEM" factory.', 'WIP-0346 : 시스템 PROMPT는 "SYSTEM" 공장에서 정의가 가능합니다.', 'WIP-0346 : Es ist moeglich den vordefinierten Prompt fuer die system-Factory zu verwenden.', 'ADMIN', '20080227215718', 'ADMIN', '20081218142812');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0347', 'WIP', 'WIP-0347 : The total Scrap count of SubLots is not same with Loss quantity of Loss Unit Code for the Lot.', 'WIP-0347 : SUBLOT의 전체 SCRAP 개수가 LOT의 UNIT 코드 별 LOSS 수량과 일치하지 않습니다.', 'WIP-0347 : Der Scrap-Count des Sub-Lot ist mit dem Loss-Unit-Code des Lot nicht identisch.', 'ADMIN', '20080228030614', 'ADMIN', '20081218142923');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0348', 'WIP', 'WIP-0348 : Successfully completed. But it does not mobilize the carrier of the part sublot.', 'WIP-0348 : 성공적으로 수행하였으나 일부 SUBLOT의 CARRIER를 복원할 수 없습니다.', 'WIP-0348 : Erfolgreich abgeschlossen, jedoch wurde der Carrier des Part-Sub-Lot. But nicht bewegt.', 'ADMIN', '20080314022501', 'ADMIN', '20081218143113');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0349', 'WIP', 'WIP-0349 : This rule does not exist.', 'WIP-0349 : 이 RULE은 존재하지 않습니다.', 'WIP-0349 : Diese RULE existiert nicht.', 'ADMIN', '20080530180238', 'ADMIN', '20081218143128');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0350', 'WIP', 'WIP-0350 : This rule already exists.', 'WIP-0350 : 이 RULE은 이미 존재합니다.', 'WIP-0350 : Diese RULE existiert bereits.', 'ADMIN', '20080530180302', 'ADMIN', '20081218143139');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0351', 'WIP', 'WIP-0351 : This rule definition does not exist.', 'WIP-0351 : 이 RULE 아이템은 존재하지 않습니다.', 'WIP-0351 : Diese RULE Definition existiert nicht.', 'ADMIN', '20080530180439', 'ADMIN', '20081218143417');
