INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0355', 'WIP', 'WIP-0355 : You can not generate id because transaction result is not success.', 'WIP-0355 : 트랜잭션 결과가 성공이 아니기 때문에 ID를 생성할 수 없습니다.', 'WIP-0355 : Da die Transaktion nicht erfolgreich war, kann keine ID erstellt werden.', 'ADMIN', '20080609184306', 'ADMIN', '20081218143632');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0356', 'WIP', 'WIP-0356 : The next sequence does not exist.', 'WIP-0356 : 다음 SEQUENCE가 존재하지 않습니다.', 'WIP-0356 : Die naechste Sequenz existiert nicht.', 'ADMIN', '20080609184733', 'ADMIN', '20081218143736');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0357', 'WIP', 'WIP-0357 : You can not generate id because the sequence is maximum and ALLOW_CYCLE_FLAG is not ''Y''.', 'WIP-0357 : SEQUENCE가 최대값이지만  ALLOW_CYCLE_FLAG 항목이 ''Y''가 아니기 때문에 ID를 생성할 수 없습니다.', 'WIP-0357 : Maximale SEQUENZ Wert is zwar erreicht, aber da ALLOW_CYCLE_FLAG nicht ''Y'' ist, kann ID nicht erstellt werden.', 'ADMIN', '20080609185511', 'ADMIN', '20081218143858');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0358', 'WIP', 'WIP-0358 : This rule needs argument of query. Please check query again.', 'WIP-0358 : 이 RULE은 쿼리에 대한 인수가 필요합니다. 쿼리를 다시 한번 확인해주세요.', 'WIP-0358 : Diese RULE erfordert Anfrage. Ueberpruefen Sie die Anfrage erneut.', 'ADMIN', '20080610102258', 'ADMIN', '20081218143931');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0359', 'WIP', 'WIP-0359 : You can not change sequence of rule because some rule dependent on this rule.', 'WIP-0359 : 특정 RULE이 이 RULE에 의존하기 때문에 순서를 변경할 수 없습니다.', 'WIP-0359 : Sequenz kann nicht geandert werden, da spezielle RULE von anderen Rule abhaengen.', 'ADMIN', '20080611200616', 'ADMIN', '20081218144031');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0360', 'WIP', 'WIP-0360 : This command will change the sequence of rule. Do you want to clear last sequence value?', 'WIP-0360 : 이 명령을 수행하면 RULE의 순서가 바뀔 것입니다. 최근 SEQUENCE 값을 초기화시키시겠습니까?', 'WIP-0360 : Dieser Befehl aendert die RULE Sequenz. Moechten Sie den letzten SEQUENZ Wert loeschen?', 'ADMIN', '20080611212234', 'ADMIN', '20081218144246');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0361', 'WIP', 'WIP-0361 : "DEP_RULE_SEQ" value can not be smaller than rule sequence.', 'WIP-0361 : "DEP_RULE_SEQ" 항목은 RULE SEQUENCE보다 작을 수 없습니다.', 'WIP-0361 : "DEP_RULE_SEQ" Wert darf nicht kleiner sein als RULE SEQUENCE.', 'ADMIN', '20080612095236', 'ADMIN', '20081218144308');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0362', 'WIP', 'WIP-0362 : This batch creation rule does not exist.', 'WIP-0362 : 이 배치 생성 룰은 존재하지 않습니다.', 'WIP-0362 : Diese Batch Creation Rule existiert nicht.', 'ADMIN', '20080617145427', 'ADMIN', '20081218144356');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0363', 'WIP', 'WIP-0363 : This batch creation rule already exists.', 'WIP-0363 : 이 배치 생성 룰은 이미 존재합니다.', 'WIP-0363 : Diese Batch Creation Rule existiert bereits.', 'ADMIN', '20080617145446', 'ADMIN', '20081218144409');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0364', 'WIP', 'WIP-0364 : This batch creation rule relation does not exist.', 'WIP-0364 : 이 배치 생성 룰의 Relation 정보는 존재하지 않습니다.', 'WIP-0364 : Diese Batch Creation Rule Relation existiert nicht.', 'ADMIN', '20080617145520', 'ADMIN', '20081218144435');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0365', 'WIP', 'WIP-0365 : This batch creation rule relation already exists.', 'WIP-0365 : 이 배치 생성 룰 Relation은 이미 존재합니다.', 'WIP-0365 : Diese Batch Creation Rule Relation existiert bereits.', 'ADMIN', '20080617145536', 'ADMIN', '20081218144459');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0366', 'WIP', 'WIP-0366 : This rule is not "BATCH" rule. Please check Generate Type of rule.', 'WIP-0366 : 이 RULE은 "BATCH"룰이 아닙니다. RULE의 "Generate Type"을 확인해보세요.', 'WIP-0366 : Dies ist keine "BATCH" Rule. Bitte ueberpruefen Sie "Generate Type" des RULE.', 'ADMIN', '20080617145707', 'ADMIN', '20081218144533');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0367', 'WIP', 'WIP-0367 : The total NPW count of batch lot is not same with NPW Count of rule.', 'WIP-0367 : 배치의 NPW 수량이 RULE에 정의된 NPW 수량과 일치하지 않습니다.', 'WIP-0367 : Anzahl des NPW Batch gleicht nicht dem definierten NPW RULE.', 'ADMIN', '20080617154850', 'ADMIN', '20081218144611');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0368', 'WIP', 'WIP-0368 : This reserve batch does not exist.', 'WIP-0368 : 이 RESERVE 배치가 존재하지 않습니다.', 'WIP-0368 : Dieser RESERVE Batch existiert nicht.', 'ADMIN', '20080620152907', 'ADMIN', '20081218144628');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0369', 'WIP', 'WIP-0369 : The remain queue time of lot is over MIN_QTIME of createion rule.', 'WIP-0369 : LOT의 남은 Queue Time이 배치 생성 룰의 MIN_QTIME 항목을 초과하였습니다.', 'WIP-0369 : Die restliche Los Queue Time hat die MIN_QTIME des Batch Creation Rule ueberschritten.', 'ADMIN', '20080620153220', 'ADMIN', '20081218144738');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0370', 'WIP', 'WIP-0370 : This MFO/resource has reserve batch.', 'WIP-0370 : 이 MFO/Resource는 RESERVE 배치를 가지고 있습니다.', 'WIP-0370 : Diese MFO/Resource hat einen RESERVE Batch.', 'ADMIN', '20080620154317', 'ADMIN', '20081218144808');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0371', 'WIP', 'WIP-0371 : This batch type is not ''S'' (Sub Lot).', 'WIP-0371 : 이 배치의 종류는 ''S'' (SUBLOT)이 아닙니다.', 'WIP-0371 : Dieser Batch Typ ist nicht ''S'' (SUBLOT).', 'ADMIN', '20080620160156', 'ADMIN', '20081218144851');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0372', 'WIP', 'WIP-0372 : This batch type is not ''L'' (Lot).', 'WIP-0372 : 이 배치의 종류는 ''L''(LOT)이 아닙니다.', 'WIP-0372 : Dieser Batch Typ ist nicht ''L''(LOT).', 'ADMIN', '20080620160212', 'ADMIN', '20081218144913');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0373', 'WIP', 'WIP-0373 : This rule does not allow mix sublot of different lots', 'WIP-0373 : 이 RULE은 여러 LOT의 SUBLOT들을 섞는 것을 허용하지 않습니다.', 'WIP-0373 : Diese RULE verbietet das Mischen von Sublots von mehreren Lots.', 'ADMIN', '20080623183132', 'ADMIN', '20081218144948');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0374', 'WIP', 'WIP-0374 : The NPW position of the batch is not same with creation rule definition.', 'WIP-0374 : 배치의 NPW 위치가 배치 생성 룰의 정의와 일치하지 않습니다.', 'WIP-0374 : NPW Position des Batch ist nicht gleich dem Batch Rule Creation Definition.', 'ADMIN', '20080623190031', 'ADMIN', '20081218145114');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0375', 'WIP', 'WIP-0375 : Wrong information between reserved lot and input information.', 'WIP-0375 : Lot의 예약 정보와 입력정보가 다릅니다.', 'WIP-0375 : Reservierte und eingegebene Los Information sind unterschiedlich.', 'ADMIN', '20080924161432', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0376', 'WIP', 'WIP-0376 : Lot status is not ''RESV''', 'WIP-0376 : Lot는 ''RESV'' 상태가 아닙니다.', 'WIP-0376 : Lot Status ist nicht ''RESV''.', 'ADMIN', '20080924162436', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0377', 'WIP', 'WIP-0377 : Lot status is not ''WAIT''', 'WIP-0377 : Lot는 ''WAIT'' 상태가 아닙니다.', 'WIP-0377 : Lot Status ist nicht ''WAIT''.', 'ADMIN', '20080924162622', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0378', 'WIP', 'WIP-0378 : Does not have the sublot option item in this condition.', 'WIP-0378 : Sublot option 설정 내용이 존재하지 않습니다.', 'WIP-0378 : Sublot option settings sind nicht vorhanden.', 'ADMIN', '20081029203313', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0379', 'WIP', 'WIP-0379 : This condition already have the sublot option item.', 'WIP-0379 : 해당 조건에는 이미 Sublot option 설정을 가지고 있습니다.', 'WIP-0379 : Sublot option ist bereits integriert.', 'ADMIN', '20081029203536', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0380', 'WIP', 'WIP-0380 : Invaild argument index in Where statement. Check Where statement in [ID Generator Setup] and argument value in this service.', 'WIP-0380 : Where 절에 설정된 인수 Index 값이 존재하지 않습니다. [ID Generator Setup]의 Where 절과 인수를 정확히 입력했는지 확인하십시오.', 'WIP-0380 : Ungueltiger Index in "Where" statement. Ueberpruefen Sie genau ob Where status im [GCM Table Setup] eingegeben wurde.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0381', 'WIP', 'WIP-0381 : Can not change unit 1 quantity, if lot have sublots.', 'WIP-0381 : SUBLOT이 존재하는 경우에는 UNIT 1의 수량을 변경할 수 없습니다.', 'WIP-0381 : Wenn SUBLOT existiert, kann die UNIT 1 Menge nicht geaendert werden.', 'ADMIN', '20090224174929', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0382', 'WIP', 'WIP-0382 : Can not do loss or bonus transaction by this unit. Check operation setup.', 'WIP-0382 : Loss/Bonus 하려는 UNIT이 존재하지 않습니다. 공정 설정을 확인하십시오.', 'WIP-0382 : Loss/Bonus kann nicht ausgefuehrt werden, da UNIT nicht existiert. Ueberpruefen Sie Operation setup.', 'ADMIN', '20090225084833', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0383', 'WIP', 'WIP-0383 : The result of unit2 after scribe is not integer. Only integer is allowed in factories that manage cell grade. Please check scribe count.', 'WIP-0383 : Scribe후 unit2의 결과가 정수가 아닙니다. CELL GRADE를 관리하는 공장에서는 정수만 허용됩니다. SCRIBE COUNT를 확인 하세요.', 'WIP-0383 : Nach dem Scribe ist Unit 2 Ergebnis nicht ganzzahlig/integer. Nur integer ist erlaubt in Produktionsstaetten die CELL GRADE regeln. Checken Sie SCRIBE COUNT.', 'ADMIN', '20090305153612', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0384', 'WIP', 'WIP-0384 : The input transaction time is not allowed future time.', 'WIP-0384 : 입력된 트랜젝션 시간은 미래시간을 허용하지 않습니다.', 'WIP-0384 : Eingegebene Transaktionszeit toleriert keine future time.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0385', 'WIP', 'WIP-0385 : MFO Option level is invalid. Only "1" (Material-Flow-Oper), "2" (Flow-Oper), or "3" (Oper) is allowed.', 'WIP-0385 : MFO 레벨이 유효하지 않습니다. "1" (Material-Flow-Oper), "2" (Flow-Oper), "3" (Oper)만 허용됩니다.', 'WIP-0385 : Ungueltiger MFO Level. Nur "1" (Material-Flow-Oper), "2" (Flow-Oper), "3" (Oper) ist erlaubt.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0386', 'WIP', 'WIP-0386 : Due time is not to be past time. Please check the due time.', 'WIP-0386 : Due time은 과거 시간이 될 수 없습니다. Due Time을 확인 하세요.', 'WIP-0386 : Due time kann nicht gleich der vergangenen Zeit sein. Ueberpruefen Sie die Due Time.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0387', 'WIP', 'WIP-0387 : Invalid batch level. Batch level must be "R",  "T" or "G".', 'WIP-0387 : 유효 하지 않은 배치 수준입니다. 배치 수준은 "R", "T", "G" 중의 하나 여야 합니다.', 'WIP-0387 : Ungueltiger Batch Level. Batch Level muss "R", "T" oder "G" sein.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0388', 'WIP', 'WIP-0388 : This lot has sublot. Please check lot id or use assign sublot carrier.', 'WIP-0388 : Lot이 sublot 를 가지고 있습니다. lot id를 확인하거나 Assign sublot carrier를 사용하여 주십시오.', 'WIP-0388 :  Dieses Los hat einen Teillos. Bitte uberprufen Sie die Los ID oder benuzten Sie den "Assign sublot carrier".', 'ADMIN', '20090305153612', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0389', 'WIP', 'WIP-0389 : This service is successful and SUBLOT is created.', 'WIP-0389 : 작업을 성공적으로 수행하고 SUBLOT을 생성하였습니다.', 'WIP-0389 : Service war erfolgreich und Sublot erstellt.', 'ADMIN', '20090416164021', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0390', 'WIP', 'WIP-0390 : This flow is last flow for the Material. Can not move to next flow.', 'WIP-0390 : 이 Flow는 Material 의 마지막 Flow 입니다. 따라서 다음 Flow로 이동할 수  없습니다.', 'WIP-0390 : Dieser Flow ist der letzte Material Flow. Transfer zum naechsten Flow ist nicht moeglich.', 'ADMIN', '20090417033441', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0391', 'WIP', 'WIP-0391 : This batch is already confirmed.', 'WIP-0391 : 이 BATCH은 이미 컨펌 되었습니다.', 'WIP-0391 : Dieser BATCH wurde bereits bestaetigt.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0392', 'WIP', 'WIP-0392 : Please cancel the confirmation of batch first. This batch is confirmed.', 'WIP-0392 : 이 BATCH는 컨펌 되었습니다. 컨펌을 먼저 취소 해주세요.', 'WIP-0392 : Dieser BATCH wurde bestaetigt. Loeschen Sie zuerst die Bestaetigung.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0393', 'WIP', 'WIP-0393 : Please confirm the batch before using batch. This batch is not confirmed.', 'WIP-0393 : 이 BATCH는 컨펌이 되지 않아 사용할 수 없습니다. 사용전에 컨펌을 해주세요.', 'WIP-0393 : Dieser BATCH kann wegen fehlender Bestaetigung nicht genutzt werden. Bitte vor Nutzung bestaetigen.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0394', 'WIP', 'WIP-0394 : The sequence of flow does not exist for the material.', 'WIP-0394 : 이 Flow 의 Sequence 는 현재 Material 에 존재하지 않습니다.', 'WIP-0394 : Diese Flow Sequenz besitzt nicht das derzeitige Material.', 'ADMIN', '20090417214402', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0395', 'WIP', 'WIP-0395 : The operation is not PULL operation. so this transaction is not allowed for the operation.', 'WIP-0395 : PULL 공정이 아니므로 이 Transaction을 처리할 수 없습니다.', 'WIP-0395 : Transaktion kann nicht durchgefuehrt werden, da es sich nicht um PULL Operation handelt.', 'ADMIN', '20090417221751', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0396', 'WIP', 'WIP-0396 : This initial value includes Exclude String. Pleas check initial value again.', 'WIP-0396 : 이 Initial Value에 제외 문자열이 포함되어 있습니다. Initial Value를 확인하세요.', 'WIP-0396 : String ist im Initial Value inbegriffen. Bitte ueberpruefen Sie Initial Value.', 'ADMIN', '20090420160504', 'ADMIN', '20090420161343');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0397', 'WIP', 'WIP-0397 : The format value must be ''A''(Ascii), ''N'' (Number), ''F''(Float).', 'WIP-0397 : Format 값은 ''A''(문자), ''N''(정수), ''F''(실수) 만 허용됩니다.', 'WIP-0397 : Format Wert muss ''A''(ASCII), ''N''(Zahl), ''F''(FLoat) sein.', 'ADMIN', '20090420160504', 'ADMIN', '20090420161343');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0398', 'WIP', 'WIP-0398 : The option value must be ''Y'', ''N''.', 'WIP-0398 : Option 값은 ''Y'', ''N''만 허용됩니다.', 'WIP-0398 : Option Wert muss ''Y'', ''N'' sein.', 'ADMIN', '20090420160504', 'ADMIN', '20090420161343');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0399', 'WIP', 'WIP-0399 : Invalid shift format. Please choose ''P'', ''T'' or ''N''.', 'WIP-0399 : SHIFT 형식이 올바르지 않습니다. ''P'', ''T'', ''N'' 중에서 선택해주세요.', 'WIP-0399 : Ungueltiges SHIFT Format. Waehle zwischen ''P'', ''T'' & ''N'' aus.', 'ADMIN', '20090420160504', 'ADMIN', '20090420161343');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0400', 'WIP', 'WIP-0400 : The data format is invalid. Please use "hhmm" format.', 'WIP-0400 : 이 데이터 형식이 유효하지 않습니다. "hhmm" 형식으로 입력해주세요.', 'WIP-0400 : Data Format ist ungueltig. Bitte geben Sie als "hhmm" Format ein.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0401', 'WIP', 'WIP-0401 : The material version must be greater than 0.', 'WIP-0401 : Material Version은 0보다 큰값을 입력해야합니다.', 'WIP-0401 : Material Version muss eine groesseren Wert als 0 eingeben.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0402', 'WIP', 'WIP-0402 : Invalid slot number of sublot. The slot number must be greater than 0.', 'WIP-0402 : 잘못된 SLOT NO 입니다. SLOT NO 는 0 보다 큰 값이어야 합니다.', 'WIP-0402 : Falsche SLOT Nummer. SLOT Nummer muss groesser sein als 0.', 'ADMIN', '20090426201018', 'ADMIN', '20090426201314');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0403', 'WIP', 'WIP-0403 : This sublot does not exist. Please check sublot id.', 'WIP-0403 :', 'WIP-0403 : Dieses Sublos existiert nicht. Ueberpruefen Sie die Sublos ID.', 'ADMIN', '20081201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0404', 'WIP', 'WIP-0404 : This SubLot is processed in PULL Operation.', 'WIP-0404 : 이 SUBLOT은 PULL 공정에서 작업 완료 되었습니다.', 'WIP-0404 : Das SubLot wird in der PULL Operation prozessiert.', 'ADMIN', '20090429015021', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0405', 'WIP', 'WIP-0405 : Reserved lot in a batch is not included. Please insert lot to batch.', 'WIP-0405 : BATCH에 예약 되어진 Lot이 BATCH에 포함 되진 않았습니다. BATCH에 Lot을 포함 시켜 주세요.', 'WIP-0405 : Im BATCH reserviertes Los ist nicht inbegriffen. Bitte fuegen Sie das Los ins Batch ein.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0406', 'WIP', 'WIP-0406 : There are different reserved batch ids in a batch. Please make the batch again.', 'WIP-0406 : BATCH 내에 다른 BATCH로 예약되어진 Lot이 있습니다. 다시 BATCH를 만드세요.', 'WIP-0406 : Es gibt verschiedene reservierte Batch ID is im Batch. Erstellen Sie ein neues Batch.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0407', 'WIP', 'WIP-0407 : The sublot of lot can not do this transaction. Please execute lot based transaction.', 'WIP-0407 : LOT을 가지는 SUBLOT은 이 TRANSACTION을 실행할 수 없습니다. LOT BASE TRANSACTION을 실행 하십시오.', 'WIP-0407 : Sublot kann diese Transaktion nicht ausfuehren. Bitte fuehren Sie LOT BASE TRANSAKTION aus.', 'ADMIN', '20090502171821', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0408', 'WIP', 'WIP-0408 : Lower value should be smaller then upper value.', 'WIP-0408 : LOWER 값은 UPPER 값보다 반드시 작아야 합니다.', 'WIP-0408 : LOWER Wert darf nicht hoeher als der UPPER Wert sein.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0409', 'WIP', 'WIP-0409 : Yield Range must be between 0 to 100.', 'WIP-0409 : Yield 범위는 0이상 100 이하만 허용합니다.', 'WIP-0409 : Yield Bereich muss zwischen 0 und 100 liegen.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0410', 'WIP', 'WIP-0410 : UNIT CHANGE is allowed when One lot has a one carrier.', 'WIP-0410 : Unit Change를 하기 위해서는 반드시 Lot과 Carrier는 1 : 1관계를 가져야 합니다.', 'WIP-0410 : Unit Change ist nur moeglich, wenn das Verhaeltnis zwischen Lot und Carrier 1 : 1 ist.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0411', 'WIP', 'WIP-0411 : Cannot update/delete the rule in this factory because the rule was created in other factory.', 'WIP-0411 : 이 Rule은 다른 공장에서 정의되었기 때문에 이 공장에서 수정하거나 삭제할 수 없습니다.', 'WIP-0411 : Da diese Rule in einer anderen Fabrik erstellt wurde, kann diese weder geloescht noch veraendert werden.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0412', 'WIP', 'WIP-0412 : This initial value includes invalid string. Please input initial value in Character Set.', 'WIP-0412 : Initial Value는 유효하지 않는 문자열을 포함하고 있습니다. Initial Value를 Character Set안에 있는 값으로 입력하십시오.', 'WIP-0412 : Initial Value enthaelt ungueltige String. Bitte geben Sie Initial Value vom Character Set ein.', ' ', ' ', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0413', 'WIP', 'WIP-0413 : This transaction allowed just one list item for the CHANGE_PORT_STATUS.', 'WIP-0413 : 이 TRANSACTION 에서는 한개의 CHANGE_PORT_STATUS 리스트만 가능합니다.', 'WIP-0413 : In dieser Transaktion ist nur eine CHANGE_PORT_STATUS Liste moeglich.', 'ADMIN', '20090515231546', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0414', 'WIP', 'WIP-0414 : This transaction allowed just one list item for the CHANGE_CARRIER.', 'WIP-0414 : 이 TRANSACTION 에서는 한개의 CHANGE_CARRIER 리스트만 가능합니다.', 'WIP-0414 : In dieser Transaktion ist nur eine CHANGE_CARRIER Liste moeglich.', 'ADMIN', '20090515231711', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0415', 'WIP', 'WIP-0415 : This transaction can not process lot of RESERVE status.', 'WIP-0415 : RESERVE 상태의 LOT 은 이 TRANSACTION을 진행할 수 없습니다.', 'WIP-0415 : Transaktion kann durch RESERVE Status LOT nicht ausgefuehrt werden.', 'ADMIN', '20090515232549', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0416', 'WIP', 'WIP-0416 : Some lot use this flow and flow sequence number of material. So can not change flow sequence number.', 'WIP-0416 : 이 FLOW 와 FLOW SEQ NUM 는 LOT 에 사용중입니다. 그래서 FLOW SEQ NUM 를 변경할 수 없습니다.', 'WIP-0416 : Dieser FLOW und FLOW SEQ NUM wird im Los verwendet. Daher kann die FLOW SEQ NUM nicht geaendert werden.', 'ADMIN', '20090518180730', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0417', 'WIP', 'WIP-0417 : This transaction is not allowed to the batched lot. Please release lot from the batch, and try again.', 'WIP-0417 : 이 LOT은 BATCH 로 구성되어 있으므로 이 TRANSACTION을 처리할 수 없습니다. BATCH 에서 LOT을 풀고 다시 시도해 주십시오.', 'WIP-0417 : Da das Los als BATCH konstituiert ist, kann diese Transaktion nicht bearbeitet werden. Loesen Sie das Los vom BATCH und versuchen Sie es erneut.', 'ADMIN', '20090518232245', 'ADMIN', '20090518232716');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0418', 'WIP', 'WIP-0418 : This transaction is not allowed to the batched sublot. Please release sublot from the batch, and try again.', 'WIP-0418 : 이 SUBLOT은 BATCH 로 구성되어 있으므로 이 TRANSACTION을 처리할 수 없습니다. BATCH 에서 SUBLOT을 풀고 다시 시도해 주십시오.', 'WIP-0418 : Da das SUBLOT als BATCH konstituiert ist, kann diese Transaktion nicht bearbeitet werden. Loesen Sie das Los vom BATCH und versuchen Sie es erneut.', 'ADMIN', '20090518234410', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0419', 'WIP', 'WIP-0419 : In batch processing, Not allow change M-F-O (Material-Flow-Operation).', 'WIP-0419 : BATCH 상태에서는 M-F-O (Material-Flow-Operation) 를 변경할 수 없습니다.', 'WIP-0419 : Waehren dem BATCH Prozess kann M-F-O (Material-Flow-Operation) nicht geaendert werden.', 'ADMIN', '20090519023047', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0420', 'WIP', 'WIP-0420 : There are one more different status of lots in the batch. Please contact IT Team.', 'WIP-0420 : BATCH내의 Lot의 Status가 다른 Lot가 있습니다. IT Team에 문의 바랍니다.', 'WIP-0420 : Es befindet sich ein anderes Los im BATCH. Wenden Sie sich an das IT Team.', 'ADMIN', '20090519045823', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0421', 'WIP', 'WIP-0421 : Can not change unit 1 quantity, if lot have sublot and different unit 1 quantity from previous.', 'WIP-0421 : LOT이 SUBLOT을 가지고 있고 이전 수량과 다른 경우에는 UNIT 1의 수량을 변경할 수 없습니다.', 'WIP-0421 : Anzahl von UNIT 1 kann nicht geaendert werden, wenn ein Los SUBLOT hat und sich von frueheren Mengen unterscheidet.', 'ADMIN', '20090525155451', 'ADMIN', '20100115181348');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0422', 'WIP', 'WIP-0422 : Can not change unit 1 quantity, if it have one lot to multi carrier relationship.', 'WIP-0422 : 한개 LOT가 여러 CARRIER에 할당되어 있는 경우에는 UNIT 1의 수량을 변경할 수 없습니다.', 'WIP-0422 : Wenn 1 Los dem CARRIER zugeordnet ist, kann die Menge von UNIT 1 nicht geaendert werden.', 'ADMIN', '20090526130421', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0423', 'WIP', 'WIP-0423 : This transaction can not process. Exceed lot quantity of not assigned to carrier.', 'WIP-0423 : CARRIER에 할당되지 않은 LOT의 수량 범위를 초과하여 진행할 수 없습니다.', 'WIP-0423 : Transaktion kannnicht ausgefuehrt werden, da die Menge des dem CARRIER nicht zugeordnetem Los ueberschritten ist.', 'ADMIN', '20090526195617', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0424', 'WIP', 'WIP-0424 : This lot attached two more carriers. So it does not allow to create sublot of lot by carrier.', 'WIP-0424 : 이 LOT은 2개 이상의 CARRIER에 할당 되어 있습니다. 그래서 SUBLOT에 CARRIER 를 할당하여 생성할 수 없습니다.', 'WIP-0424 : Dieses Los beinhaltet mehr als zwei CARRIER. Daher kann kein SUBLOT erstellt werden.', 'ADMIN', '20090528151225', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0425', 'WIP', 'WIP-0425 : It is different between starting Resource and Resource that had been used in making batch.', 'WIP-0425 : BATCH 생성시의 장비 이름과 START 하려는 장비 이름이 다릅니다.', 'WIP-0425 : Name des Resource generierenden Batch und Startbatch sind unterschiedlich.', 'ADMIN', '20090609172301', 'ADMIN', '20090609172809');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0426', 'WIP', 'WIP-0426 : It is different between starting Resource Type and Resource Type that had been used in making batch.', 'WIP-0426 : BATCH 생성시의 장비 타입과 START 하려는 장비 타입이 다릅니다.', 'WIP-0426 : Typdes Resource generierenden Batch und Startbatch sind unterschiedlich.', 'ADMIN', '20090609172328', 'ADMIN', '20090609172830');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0427', 'WIP', 'WIP-0427 : It is different starting Resource Group and Resource Group that had been used in making batch.', 'WIP-0427 : BATCH 생성시의 장비 그룹과 START 하려는 장비 그룹이 다릅니다.', 'WIP-0427 : Gruppe des Resource generierenden Batch und Startbatch sind unterschiedlich.', 'ADMIN', '20090609172351', 'ADMIN', '20090609172847');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0428', 'WIP', 'WIP-0428 : It does not allow to decrease partial quantity of Lot when Lot has SubLot.', 'WIP-0428 : SUBLOT을 가진 LOT에 대해 수량을 차감하는 경우에는 일부 수량의 차감은 허용하지 않습니다.', 'WIP-0428 : Es ist nicht erlaubt Teilmengen von Lots, die Sublots haben, zu reduzieren.', 'ADMIN', '20090611145251', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0429', 'WIP', 'WIP-0429 : The decrease quantity is greater than Lot quantity. Please check decrease quantity.', 'WIP-0429 : 차감되는 수량이 LOT의 수량보다 많습니다. 차감 수량을 확인하십시오.', 'WIP-0429 : Die reduzierte Menge ist hoeher als die Losmenge. Ueberpruefen Sie die reduzierte Menge.', 'ADMIN', '20090611150316', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0430', 'WIP', 'WIP-0430 : CV code is duplicated. Please check CV code.', 'WIP-0430 : 중복 되는 CV CODE가 있습니다. CV CODE를 확인 하십시오.', 'WIP-0430 : CV CODE wurde dupliziert. Bitte ueberprufen Sie CV CODE.', 'ADMIN', '20090611150413', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0431', 'WIP', 'WIP-0431 : No CV code and quantity is specified. Please check CV code and quantity.', 'WIP-0431 : CV 코드와 수량이 입력되지 않았습니다. CV 코드와 수량을 확인해 주십시오.', 'WIP-0431 : CV code und Menge sind nicht eingegeben. Bitte erneut ueberpruefen.', 'ADMIN', '20090611174207', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0432', 'WIP', 'WIP-0432 : Can not set "AND" or "OR" to first condition.', 'WIP-0432 : 첫번째 조건에는 AND 또는 OR 를 설정할 수 없습니다.', 'WIP-0432 : AND und OR koennen nicht als erste Bedingung installiert werden.', 'ADMIN', '20090811145229', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0433', 'WIP', 'WIP-0433 : No have input field on the condition in master table. Please check field name.', 'WIP-0433 : 조건으로 입력한 필드를 찾을 수 없습니다. 필드 이름을 확인하십시오.', 'WIP-0433 : Eingegebens Feld kann nicht gefunden werden. Bitte ueberpruefen Sie Feldnamen.', 'ADMIN', '20090811145757', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0434', 'WIP', 'WIP-0434 : No allow "IN" or "NOT IN" operand on the Fixed Value type.', 'WIP-0434 : Fixed Value 값 타입으로는 "IN", "NOT IN" 연산자를 사용할 수 없습니다.', 'WIP-0434 : Nur "IN", "NOT IN" Operator kann Fixed Value Werttyp benutzen.', 'ADMIN', '20090811150024', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0435', 'WIP', 'WIP-0435 : Allow "IN" or "NOT IN" operand on the GCM Table value type only.', 'WIP-0435 : GCM Table 값 타입으로는 "IN", "NOT IN" 연산자만 사용할 수 있습니다.', 'WIP-0435 : Nur "IN", "NOT IN" Operator kann GCM Werttabelle benutzen.', 'ADMIN', '20090811150249', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0436', 'WIP', 'WIP-0436 : No have GCM table of GCM Table value type', 'WIP-0436 : GCM Table 값 타입으로 입력한 Table 이 존재하지 않습니다.', 'WIP-0436 : Die als GCM Tabellen value typ eingegebene Tabelle existiert nicht.', 'ADMIN', '20090811150600', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0437', 'WIP', 'WIP-0437 : Invalid SQL of User SQL value type. Please check SQL.', 'WIP-0437 : User SQL 값 타입으로 입력한 SQL 에 문제가 있습니다. SQL 문을 확인해 주십시오.', 'WIP-0437 : Die als User SQL value typ eingegebene SQL hat ein Problem. Bitte ueberpruefen Sie SQL.', 'ADMIN', '20090811150901', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0438', 'WIP', 'WIP-0438 : Left and right bracket count is not match.', 'WIP-0438 : 왼쪽 괄호와 오른쪽 괄호의 개수가 맞지 않습니다.', 'WIP-0438 : Anzahl der rechten und linken Bracket stimmt nicht ueberein.', 'ADMIN', '20090811151008', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0439', 'WIP', 'WIP-0439 : No allow assign the service to each transaction on the same MFO and POINT.', 'WIP-0439 : 동일한 MFO, POINT 조건에서 SERVICE 는 다른 TRANSACTION 에 각각 할당될 수 없습니다.', 'WIP-0439 : Unter gleichen MFO, POINT Bedingungen kann der SERVICE nicht jeder anderen Transaktion zugeordnet werden.', 'ADMIN', '20090811151728', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0440', 'WIP', 'WIP-0440 : Only one action allow Tue/False action on action type of the transaction with each MFO level and same POINT and service.', 'WIP-0440 :  각 MFO LEVEL 과 동일한 POINT, SERVICE 조건에서  TRANSACTION 의 ACTION_TYPE 중 TRUE/FALSE ACTION 은 하나만 허용됩니다.', 'WIP-0440 : Nur eins von TRUE/FALSE ACTION im Transaction Action Type ist moeglich unter den gleichen MFO Level Bedingungen.', 'ADMIN', '20090811152830', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0441', 'WIP', 'WIP-0441 : Conflict action on the same MFO, POINT, TRANSACTION and no condition.', 'WIP-0441 : 동일한 MFO, POINT, TRANSACTION 에 대해 아무런 조건도 없이 중복 정의할 수 없습니다.', 'WIP-0441 : Ohne Bedingungen koennen sich gleiche MFO, POINT, TRANSACTION Definition ueberschneiden.', 'ADMIN', '20090811155501', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0442', 'WIP', 'WIP-0442 : Conflict action on the same MFO, POINT, TRANSACTION and CONDITION.', 'WIP-0442 : 동일한 MFO, POINT, TRANSACTION 에 중복된 조건으로 정의할 수 없습니다.', 'WIP-0442 : Sich ueberlappende Bedingungen der gleichen MFO, POINT, TRANSACTION koennen nicht definiert werden.', 'ADMIN', '20090811155718', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0443', 'WIP', 'WIP-0443 : This action have the condition could be duplicated with the same MFO, POINT and TRANSACTION. Please confirm this action.', 'WIP-0443 : 동일한 MFO, POINT, TRANSACTION 에서 중복될 수 있는 조건이 존재합니다. 이 조건은 사용자의 판단이 필요합니다.', 'WIP-0443 : Bedingungen koennen sich unter den gleichen MFO, POINT, TRANSACTION ueberschneiden. Dies muss vom User bestaetigt werden.', 'ADMIN', '20090811160322', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0444', 'WIP', 'WIP-0444 : No have next flow of material while move out by operation count.', 'WIP-0444 : OPER COUNT 에 의해 이동 중 현재 FLOW 에서 다음 공정을 찾을 수 없어 MATERIAL 의 다음 FLOW 를 찾았으나 존재하지 않습니다.', 'WIP-0444 : Da keine Operation im aktuellen Flow gefunden wurde, konnte kein MATERIAL im naechsten Flow gefunden werden.', 'ADMIN', '20090811201842', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0445', 'WIP', 'WIP-0445 : No have previous flow of material while move out by operation count.', 'WIP-0445 : OPER COUNT 에 의해 이동 중 현재 FLOW 에서 이전 공정을 찾을 수 없어 MATERIAL 의 이전 FLOW 를 찾았으나 존재하지 않습니다.', 'WIP-0445 : Da keine Operation im aktuellen Flow gefunden wurde, konnte kein MATERIAL im vorherigen Flow gefunden werden.', 'ADMIN', '20090811201930', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0446', 'WIP', 'WIP-0446 : Invalid operator. Available operator list is ''@, =, +, -'' .', 'WIP-0446 : 연산자는 ''@, =, +, -''  만 가능합니다.', 'WIP-0446 : Verfuegbare Operator Liste ist ''@, =, +, -''.', 'ADMIN', '20090812155547', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0447', 'WIP', 'WIP-0447 : Invalid Batch. Reserve batch item allow only batch as same name.', 'WIP-0447 : Reserve Batch Item은 동일한 이름의 Batch 에만 할당할 수  있습니다.', 'WIP-0447 : Reserve Batch Item erlaubt nur dem Batch den gleichen Namen zu haben.', 'ADMIN', '20090821112920', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0448', 'WIP', 'WIP-0448 : Cannot assign Lot to not existing Reserve Batch ID. Please input correct Reserve Batch ID or remove Reserve Batch ID to assign Lot.', 'WIP-0448 : 존재하지 않는 Resv. Batch ID에 Lot을 assign할 수 없습니다. 존재하는 Resv. Batch ID를 입력하거나, Resv. Batch ID를 지운 상태에서 Lot을 assign하세요.', 'WIP-0448 : Los kann nicht dem nicht vorhandenen Resv. Batch ID zugeordnet werden. Geben Sie korrekten Resv. Batch ID ein.', 'ADMIN', '20090821113632', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0449', 'WIP', 'WIP-0449 : Not allow to Reserve Batch to the existing Batch ID. Please input new Reserve Batch ID in manual input case, or use auto generation function.', 'WIP-0449 : 이미 사용 중인 Batch ID에 Reserve Batch 할 수 없습니다. Manual로 입력 시 새로운 Reserve Batch ID를 입력하거나, 자동발번 기능을 사용하십시요.', 'WIP-0449 : Bereist in Benutzung stehende Batch ID kannnicht in Reserve Batch umgewandelt werden. Gebebn Sie neue Reserve Batch ID manuell ein der verwenden Sie die automatische Funktion.', 'ADMIN', '20090821114109', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0450', 'WIP', 'WIP-0450 : Not allow to Release Batch from started batch. Please revert to before started batch using "Delete Start Batch", and try again.', 'WIP-0450 : START 상태의 BATCH 는 RELEASE 할 수 없습니다. "Delete Start Batch" 를 이용하여 START 이전 상태로 복원한 후 RELEASE 해 주십시오.', 'WIP-0450 : BATCH RELEASE kann nicht im START Status erfolgen. Benutze "Delete Start Batch" um zum vorherigen status zurueckzukehren und versuchen Sie es erneut.', 'ADMIN', '20090822111452', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0451', 'WIP', 'WIP-0451 : Lot count of Batch and number of Started Lot doesnot match.', 'WIP-0451 : BATCH LOT 갯수와 START 된 LOT 의 갯수가 일치하지 않습니다.', 'WIP-0451 : Anzahl des BATCH LOT und gestartetem LOT stimmt nicht ueberein.', 'ADMIN', '20090822140304', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0452', 'WIP', 'WIP-0452 : Can not delete Start Batch history of the batch because the last history of Lot is not START.', 'WIP-0452 : BATCH 로 작업 시작한 LOT의 마지막 이력이 START가 아니어서 START BATCH 이력을 지울수 없습니다.', 'WIP-0452 : START BATCH HISTORY kann nicht geloescht werden, da die letzte LOS HISTORY nicht im START Status steht.', 'ADMIN', '20090822140842', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0453', 'WIP', 'WIP-0453 : Not allow to Change Batch Properties from started batch. Please revert to the status before Batch started using "Delete Start Batch", and try again.', 'WIP-0453 : START 상태의 BATCH는 속성을 변경할 수 없습니다. "Delete Start Batch" 를 이용하여 START 이전 상태로 복원한 후 진행 해 주십시오.', 'WIP-0453 : Change Batch Properties des gestarten Batch kann nicht geaendert werden. Benutze "Delete Start Batch" um zu den vorherigen Status zurueckzukehren.', 'ADMIN', '20090824114318', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0454', 'WIP', 'WIP-0454 : This priority already exists at the Material-Flow-Operation.', 'WIP-0454 : 이 우선순위는 이미 해당 Material-Flow-Operation에 존재 합니다.', 'WIP-0454 : Die Prioritaetenfolge existiert bereits in der entsprechenden Material-Flow-Operation.', 'ADMIN', '20091008163819', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0455', 'WIP', 'WIP-0455 : Please enter the deleted lot ID to revive lot.', 'WIP-0455 : LOT을 되살리기 위해서는 삭제된 LOT을 입력해 주십시오.', 'WIP-0455 : Bitte geben Sie die geloeschte Lot ID ein, um das Lot wiederherzustellen.', 'ADMIN', '20100222112044', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0456', 'WIP', 'WIP-0456 : The set which is defined by this Material ID exists. Please process it again after remove setting from related screen.', 'WIP-0456 : 이 제품코드로 정의된 설정이 존재합니다. 먼저 해당 설정을 제거 후 사용해 주십시오.', 'WIP-0456 : Diese Einstellung, definiert gemaess dem Produkt code (Material ID), existiert. Setting vor Nutzung bitte erst entfernen.', 'ADMIN', '20101124184746', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0457', 'WIP', 'WIP-0457 : The set which is defined by this Flow exists. Please process it again after remove setting from related screen.', 'WIP-0457 : 이 Flow로 정의된 설정이 존재합니다. 먼저 해당 설정을 제거 후 사용해 주십시오.', 'WIP-0457 : Diese Einstellung, definiert gemaess dem Flow, existiert. Setting vor Nutzung bitte erst entfernen.', 'ADMIN', '20101124184746', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0458', 'WIP', 'WIP-0458 : The set which is defined by this Operation exists. Please process it again after remove setting from related screen.', 'WIP-0458 : 이 공정으로 정의된 설정이 존재합니다. 먼저 해당 설정을 제거 후 사용해 주십시오.', 'WIP-0458 : Diese Einstellung, definiert gemaess der Operation, existiert. Setting vor Nutzung bitte erst entfernen.', 'ADMIN', '20101124184746', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0459', 'WIP', 'WIP-0459 : Generator type ''U'' is allowed to set only when save point is  ''Generate with save''.', 'WIP-0459 : Generator Type ''U''는 Save Point가 ''Generate with save'' 일 경우에만 가능합니다.', 'WIP-0459 : Generator Typ ''U'' kann nur bestimmt werden, wenn Save Point gleich ''Generate with save'' ist.', 'ADMIN', '20101201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0460', 'WIP', 'WIP-0460 : This rule is not approved.', 'WIP-0460 : 이 Rule은 Approval 상태가 아닙니다.', 'WIP-0460 : Diese Rule befindet sich nicht im Bestaetigungsstatus.', 'ADMIN', '20101201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0461', 'WIP', 'WIP-0461 : History of generated ID is already exist. Please execute initialization of rule history first.', 'WIP-0461 : 해당 Rule에 대한 생성 이력이 존재합니다. 먼저 Rule 이력 초기화를 실행 후에 진행하시기 바랍니다.', 'WIP-0461 : Liste (History) der generierten IDs (Rule) existiert bereits. Erst Initialisierung der generierten IDs ausfuehren bevor Sie fortfahren.', 'ADMIN', '20101201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0462', 'WIP', 'WIP-0462 : This rule is already approved.', 'WIP-0462 : 이 Rule은 이미 Approval 상태입니다.', 'WIP-0462 : Diese Rule befindet sich bereits im Bestaetigungsstatus.', 'ADMIN', '20101201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0463', 'WIP', 'WIP-0463 : Please cancel the approval of rule first. This rule is approved.', 'WIP-0463 : 이 Rule은 Approval 상태입니다. 먼저 Approval를 취소한 후에 진행하시기 바랍니다.', 'WIP-0463 : Diese Rule befindet sich bereits im Bestaetigungsstatus. Bitte Bestaetigung loeschen bevor Sie fortfahren.', 'ADMIN', '20101201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0464', 'WIP', 'WIP-0464 : This rule is not approved. Please approve first.', 'WIP-0464 : 이 Rule은 Approval 상태가 아닙니다. 먼저 Approval 후에 진행하시기 바랍니다.', 'WIP-0464 : Diese Rule befindet sich nicht Bestaetigungsstatus. Bitte erst bestaetigen bevor Sie fortfahren.', 'ADMIN', '20101201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0465', 'WIP', 'WIP-0465 : "Save Point" and "FulFill Sequence" options can not change at the approval. Please cancel the approval of rule first.', 'WIP-0465 : Approval 상태에서는 "Save Point" Option과 "FulFill Sequence" Option은 변경할 수 없습니다. 먼저 Approval를 취소한 후에 진행하시기 바랍니다.', 'WIP-0465 : "Save Point" Option & "FulFill Sequence" Option kann nicht geaendert werden im Bestaetigungsstatus. Bitte Bestaetigung erst loeschen bevor Sie fortfahren.', 'ADMIN', '20101201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0466', 'WIP', 'WIP-0466 : It can not generate ID for test at the approval status. Please cancel the approval of rule first.', 'WIP-0466 : Approval 상태에서는 Test를 할 수 없습니다. Approval를 취소한 후에 진행하시기 바랍니다.', 'WIP-0466 :  Test kann nicht im Bestaetigungsstatus ausgefuehrt werden. Bitte Bestaetigung erst loeschen bevor Sie fortfahren.', 'ADMIN', '20101201010101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0467', 'WIP', 'WIP-0467 : The Rework Stop Operation must be set same Rework Operation or Follow Operation of Rework Operation on the Rework Flow.', 'WIP-0467 : 재작업 중단 공정은 재작업 플로우의 재작업 공정과 같거나 이후 공정이어야만 합니다.', 'WIP-0467 : Entweder ''rework stop operation'' und ''rework operation'' des ''rework flow'' sind equivalent oder Operation sollte nach ''rework operation'' generiert werden.', 'ADMIN', '20101124184746', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0468', 'WIP', 'WIP-0468 : No allow set Return Flow/Operation when it select "Move to Next Operation" option.', 'WIP-0468 : "Move to Next Operation" 설정에서는 반환 플로우/공정을 정의할 수 없습니다.', 'WIP-0468 : Waehrend der ''Move to Operation'' Einstellung kann der Ruecklauf/Operation (return flow/operation) nicht definiert werden.', 'ADMIN', '20101124184746', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0469', 'WIP', 'WIP-0469 : No allow set to Rework Lot in Adapt Transaction.', 'WIP-0469 : Adapt Transaction 을 통해 Rework Lot 으로 변경할 수 없습니다.', 'WIP-0469 : Einstellen zu Rework Lot in "Adapt" Transaktion nicht erlaubt.', 'ADMIN', '20101124184746', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0470', 'WIP', 'WIP-0470 : This step does not exist.', 'WIP-0470 : 이 Step은 존재하지 않습니다.', 'WIP-0470 : Dieser Schritt existiert nicht.', 'ADMIN', '20101224150556', 'ADMIN', '20120206103159');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0471', 'WIP', 'WIP-0471 : This step already exists.', 'WIP-0471 : 이 Step은 이미 존재하고 있습니다.', 'WIP-0471 : Dieser Schritt existiert bereist.', 'ADMIN', '20101224150626', 'ADMIN', '20120206103211');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0472', 'WIP', 'WIP-0472 : This step is not attached to operation.', 'WIP-0472 : 이 step은 operation 에 속해 있지 않습니다.', 'WIP-0472 : Dieser Schritt ist der Operation nicht beigefuegt.', 'ADMIN', '20101224150828', 'ADMIN', '20120206103224');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0473', 'WIP', 'WIP-0473 : This step is already attached to operation.', 'WIP-0473 : 이 step은 이미 operation에 속해 있습니다.', 'WIP-0473 : Der vorherige Schritt ist der Operation beigefuegt.', 'ADMIN', '20101224150919', 'ADMIN', '20120206103240');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0474', 'WIP', 'WIP-0474 : The previous step is not attached to operation.', 'WIP-0474 : 이 이전 STEP는 operation에 속해 있지 않습니다.', 'WIP-0474 : Der vorherige Schritt ist der Operation nicht beigefuegt.', 'ADMIN', '20101224154618', 'ADMIN', '20120206103254');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0475', 'WIP', 'WIP-0475 : Some operation is using this step. Please detach this step from operation.', 'WIP-0475 : 이 STEP은 OPERATION 에서 사용 중입니다. 먼저 OPERATION 에서 분리 후 지우세요.', 'WIP-0475 : Einige Operation nutzten diesen Schritt. Bitte trennen Sie diesen Schritt von Operation.', 'ADMIN', '20101224160043', 'ADMIN', '20120206103306');
