INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0480', 'WIP', 'WIP-0480 : This Step doesn''t have MFO relationship. Please check the definition of MFO - Step relationship.', 'WIP-0480 : 이 Step은 MFO 관계가 정립되어 있지 않습니다. MFO - Step 관계를 확인하시기 바랍니다.', 'WIP-0480 : Dieser Schritt hat keine MFO Beziehung. Bitte ueberpruefen Sie die Defintion von MFO-Schritt.', 'ADMIN', '20110104093438', 'ADMIN', '20120206103609');
