INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0483', 'WIP', 'WIP-0483 : Can''t delete step history created by lot transaction.', 'WIP-0483 : Lot 트랜잭션으로 생긴 step history는 삭제할 수 없습니다.', 'WIP-0483 : Step History, erstellt durch Los Transaktion, kann nicht geloescht werden.', 'ADMIN', '20110105192100', 'ADMIN', '20120206103718');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0484', 'WIP', 'WIP-0484 : Updating FLOW is not allowed on STORE status.', 'WIP-0484 : STORE 상태에서는 FLOW의 변경이 허용되지 않습니다.', 'WIP-0484 : Im Store Status ist ein FLOW Aktualisierung nicht erlaubt.', 'ADMIN', '20110113151912', 'ADMIN', '20120206103751');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0485', 'WIP', 'WIP-0485 : Updating operation is not allowed on STORE and REPAIR status.', 'WIP-0485 : STORE, REPAIR 상태에서는 공정의 변경이 허용되지 않습니다.', 'WIP-0485 : Im Store und Repair Status ist ein Betriebsaktualisierung nicht erlaubt.', 'ADMIN', '20110113152027', 'ADMIN', '20120206104903');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0486', 'WIP', 'WIP-0486 : Execution points of current action and dependent action are different. Current point and dependent action must be on same execution Point.', 'WIP-0486 : 현재 Action 과 Dependent Action 의 실행 Point 가 다릅니다. Depenent Action 과 현재 Action 은 반드시 동일한 실행 Point 에 있어야 합니다.', 'WIP-0486 : Ausfuehrungspunkte der aktuellen und abhaengigen Aktion sind verschieden. Aktuelle und abhaengige Aktion muessen am gleichen Ausfuehrungspunkt sein.', 'ADMIN', '20110209230558', 'ADMIN', '20120206104148');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0487', 'WIP', 'WIP-0487 : This action does not exist.', 'WIP-0487 : 이 Action 은 존재하지 않습니다.', 'WIP-0487 : Diese Aktion existiert nicht.', 'ADMIN', '20110209231011', 'ADMIN', '20120206103934');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0488', 'WIP', 'WIP-0488 : Current action and dependent action can''t be same.', 'WIP-0488 : 현재 Action 과 설정한 Depenent Action 은 같을 수 없습니다.', 'WIP-0488 : Aktuelle und abhaengige Aktion koennen nicht identisch sein.', 'ADMIN', '20110209231305', 'ADMIN', '20120206103952');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0489', 'WIP', 'WIP-0489 : Only "Just Positive Condition" is allowed  for Action Type when the selected Point already has another Actions.', 'WIP-0489 : 선택된 Point 에 이미 다른 Action 이 설정되어 있어 ActionType 은 JustPositiveCondition 만 가능합니다.', 'WIP-0489 : Nur "positive Bedingung" ist fuer Action Type erlaubt, wenn der ausgewaehlte Punkt bereits weitere Aktionen hat.', 'ADMIN', '20110209232636', 'ADMIN', '20120206104008');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0490', 'WIP', 'WIP-0490 : Only "Just Positive Condition" is allowed  for Action Type when several actions have the same point.', 'WIP-0490 : 동일한 Point 에 여러 Action 이 설정된 경우, Action Type 은 Just Positive Condition 만 허용됩니다.', 'WIP-0490 : Nur "positive Bedingung" ist fuer Action Type erlaubt, wenn mehrere Aktionen den gleichen Punkt haben.', 'ADMIN', '20110209232828', 'ADMIN', '20120206104029');
