INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0020','WEM','WEM-0020 : This work process event already exists.','WEM-0020 : 이 업무처리는 이벤트는 이미 존재합니다.','WEM-0020 : Event ist in diesem Arbeitsprozess bereits vorhanden.','ADMIN','20130104141529',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0021','WEM','WEM-0021 : This history sequence is not last. Please check it again.','WEM-0021 : HISTORY SEQUENCE가 마지막이 아닙니다. 확인후 다시 시도 하세요.','WEM-0021 : HISTORY SEQUENCE ist nicht die letzte. Bitte fuehren Sie nach Ueberpruefung erneut aus.','ADMIN','20130104141742',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0022','WEM','WEM-0022 : Can not process event, when event status is neither "Create" or "Process".','WEM-0022 : 업무처리 이벤트의 상태가 ''생성'' 또는 ''진행중'' 이 아니면 이벤트를 진행시킬수 없습니다.','WEM-0022 : Wenn der Arbeitsprozess Event nicht im "erstellen" oder "in Bearbeitung" Zustand ist, kann das Event nicht ausgefuehrt werden.','ADMIN','20130104142547',' ',' ');                  
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0023','WEM','WEM-0023 : Not allowed "Approval", Skip step and "Arbitrary Decision" action at "Create".','WEM-0023 : 업무처리 이벤트를 생성하는 경우에는 ''승인'',''스텝 건너뛰기'',''전결'' 처리를 함께 할수 없습니다.','WEM-0023 : Wenn ein Arbeitsprozess Event erstellt wird, koennen "Genehmigung", "Schritt ueberspringen" und "Entscheidung" nicht zusammen ausgefuehrt werden.','ADMIN','20130104143112',' ',' ');                 
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0024','WEM','WEM-0024 : Not allowed "Create" and "Skip step" action at "Approval".','WEM-0024 : 업무처리 이벤트를 승인하는 경우에는 ''생성'',''스텝 건너뛰기'' 처리를 함께 할수 없습니다.','WEM-0024 : Wenn ein Arbeitsprozess Event genehmigt wird, koennen "Erstellen" und "Schritt ueberspringen" nicht ausgefuehrt werden.','ADMIN','20130104143250',' ',' ');                  
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0025','WEM','WEM-0025 : Not allowed "Create", "Approval" and "Arbitrary Decision" action at "Skip Step".','WEM-0025 : 업무처리 이벤트를 건너뛰기 하는 경우에는 ''생성'',''승인'',''전결'' 처리를 함께 할수 없습니다.','WEM-0025 : Wenn ein Arbeitsprozess Event uebersprungen wird, koennen "Erstellen", "Genehmigung" und "Entscheidung" nicht zusammen ausgefuehrt werden.','ADMIN','20130104143452',' ',' ');                
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0026','WEM','WEM-0026 : Arbitrary Decision has to be done with "Approval" action.','WEM-0026 : 업무처리 이벤트를 전결처리하는 경우에는 ''승인'' 과 함께 처리되어야 합니다.','WEM-0026 : Wenn ein Arbeitsprozess Event festgelegt wird, kann dies nicht zusammen mit "Genehmigung" erfolgen.','ADMIN','20130104143803',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0027','WEM','WEM-0027 : It"s allowed to input next step ID only when action is either "Approval" or "Skip step".','WEM-0027 : ''승인'' 이나 ''스텝 건너뛰기'' 일때만 다음 스텝을 입력할 수 있습니다.','WEM-0027 : Der naechste Schritt kann nur eingegeben werden, wenn der Zustand auf "bewilligt" oder "Schritt ueberspringen" ist.','ADMIN','20130104144303',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0028','WEM','WEM-0028 : When it"s "Read only", only "Approval", Skip step or "Go to any step" authority is allowed to perform event.','WEM-0028 : 읽기 전용인 경우 이벤트를 처리하기 위해서는 "승인","스텝 건너뛰기","임의 스텝 이동"의 권한이 있어야 합니다.','WEM-0028 : Um ein schreibgeschuetztes Event durchzufuehren, wird eine Berechtigung fuer "Genehmigung", "Schritt ueberspringen" und "Go to optional step" benoetigt.','ADMIN','20130104145005','ADMIN','20130104150123');               
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0029','WEM','WEM-0029 : When it"s "Read Only", It"s allowed to perform only "Approval" or "Skip step".','WEM-0029 : 읽기 전용인 경우 ''승인'' 또는 ''스텝 건너뛰기'' 만을 처리할 수 있습니다.','WEM-0029 : Im schreibgeschuetzten Zustand kann nur "genehmigt" oder "Schritt ueberspringen" ausgefuehrt werden.','ADMIN','20130104150325',' ',' ');                  
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0030','WEM','WEM-0030 : To perform "Skip step", you have to have "Skip step" authority or process step is optional.','WEM-0030 : ''스텝 건너뛰기'' 는 ''스텝 건너뛰기'' 권한이 있거나 선택적 스텝인 경우에만 가능합니다.','WEM-0030 : Schritt ueberspringen'' kann nur ausgefuehrt werden, wenn man die Authorisierung dafuer hat oder es als Option aufgefuehrt ist. ','ADMIN','20130104150836',' ',' ');                  
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0031','WEM','WEM-0031 : To perform "Approval", you have to have "Approval" authority.','WEM-0031 : "승인"은 "승인"권한이 있어야 합니다.','WEM-0031 : Zustimmung'' kann nur mit einer Zustimmungsberechtigung ausgefuehrt werden.','ADMIN','20130104151255',' ',' ');                  
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0032','WEM','WEM-0032 : Status value was changed when you do not have "Writable" authority.','WEM-0032 : 쓰기 권한이 없는데 상태값이 변경되었습니다.','WEM-0032 : Der Statuswert hat sich ohne schriftliche Zustimmung veraendert.','ADMIN','20130104151531',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0033','WEM','WEM-0033 : This process step is not arbitrary decision step.','WEM-0033 : 전결 가능한 스텝이 아닙니다.','WEM-0033 : Dies ist kein Entscheidungsschritt.','ADMIN','20130104151753',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0034','WEM','WEM-0034 : Approver for the next step is not inputted.','WEM-0034 : 다음 스텝에 대한 승인자가 입력되지 않았습니다.','WEM-0034 : Die Person zur Genehmigung fuer den naechsten Schritt ist nicht eingetragen.','ADMIN','20130104151916',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0035','WEM','WEM-0035 : The history of the work process event does not exist.','WEM-0035 : 이 업무처리 이벤트의 이력이 존재하지 않습니다.','WEM-0035 : Die History dieses Arbeitsprozesses existiert nicht.','ADMIN','20130104153426',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0036','WEM','WEM-0036 : Authority for process event doesn"t exist.','WEM-0036 : 업무처리 이벤트를 처리할 수 있는 권한이 없습니다.','WEM-0036 : Die Befugnis fuer die Ausfuehrung des Arbeitsprozesses ist nicht vorhanden.','ADMIN','20130104154002',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0037','WEM','WEM-0037 : Next step ID must be inputted when next step is defined as step group.','WEM-0037 : 다음 스텝이 스텝 그룹으로 설정되어 있는 경우 다음 스텝은 입력되어야 합니다.','WEM-0037 : Wenn der naechste Schritt der Schrittgruppe zugeordnet wird, muss dieser eingegeben werden.','ADMIN','20130104154316',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0038','WEM','WEM-0038 : Last step does not need next step id.','WEM-0038 : 마지막 스텝이므로 다음 스텝은 필요하지 않습니다.','WEM-0038 : Weil es der letzte Schritt ist, ist der nachste Schritt nicht erforderlich.','ADMIN','20130104154433',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0039','WEM','WEM-0039 : Invalid next step id.','WEM-0039 : 입력된 다음 스텝과 프로세스의 다음 스텝이 일치하지 않습니다.','WEM-0039 : Der eingetragene naechste Schritt und der naechste Schritt des Arbeitsvorgangs gleichen sich nicht.','ADMIN','20130104154648',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0040','WEM','WEM-0040 : Next step doesn"t exist.','WEM-0040 : 다음 스텝이 존재하지 않습니다.','WEM-0040 : Der naechste Schritt existiert nicht.','ADMIN','20130104155947',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0041','WEM','WEM-0041 : All process steps of group were not processed. Please input next step id.','WEM-0041 : 그룹의 모든 스텝이 진행되지 않았습니다. 다음 스텝을 입력해 주십시오.','WEM-0041 : Nicht alle Schritt in der Gruppe konnten ausgefuehrt werden. Bitte geben Sie den naechsten Schritt ein.','ADMIN','20130104160405',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0042','WEM','WEM-0042 : Can not move to next step before processing more than minimum count of step process of the step group.','WEM-0042 : 스텝그룹의 최소 진행 스텝개수를 진행하지 않고 다음 스텝으로 이동할 수 없습니다.','WEM-0042 : Der naechste Schritt kann nicht ausgefuehrt werden, solange die minimale Anzahl der Schritte nicht ausgefuehrt wurden.','ADMIN','20130107112213','ADMIN','20130107112646');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0043','WEM','WEM-0043 : Can not move to next step before processing mandatory process step of the step group.','WEM-0043 : 스텝그룹의 필수 진행 스텝을 진행하지 않고 다음 스텝으로 이동할 수 없습니다.','WEM-0043 : Der naechste Schritt kann nicht ausgefuehrt werden, solange vorher die erforderlichen Schritte nicht ausgefuehrt wurden.','ADMIN','20130107112842',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0508','WIP','WIP-0508 : The BIN ID does not exist.','WIP-0508 : 이 BIN ID는 존재하지 않습니다.','WIP-0508 : Diese BIN ID existiert nicht.','ADMIN','20130204173603',' ',' ');                   
