INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0510','WIP','WIP-0510 : The BIN ID is deleted. Please check BIN ID.','WIP-0510 : 이 BIN ID 는 삭제처리 되었습니다. BIN ID 를 확인해 주십시오.','WIP-0510 : Diese BIN ID wurde geloescht. Bitte ueberpruefen Sie die BIN ID.','ADMIN','20130204174409',' ',' ');                   
