INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0517','WIP','WIP-0517 : The BIN Version is either approved or released. It can"t be updated','WIP-0517 : 이 BIN VERSION 은 이미 승인 또는 배포되어 변경이 불가능 합니다.','WIP-0517 : Diese BIN Version ist weder genehmigt noch freigegeben. Update ist nicht moeglich.','ADMIN','20130205093337',' ',' ');                   
