INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0521','WIP','WIP-0521 : The BIN Unit already exists.','WIP-0521 : 이 BIN UNIT 은 이미 존재합니다.','WIP-0521 : Diese BIN Einheit existiert bereits.','ADMIN','20130205100521',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0522','WIP','WIP-0522 : Fixed upper and lower limitation value are not needed when using Product Specification.','WIP-0522 : 제품 스펙을 사용하는 경우 고정된 한계값은 입력할 필요가 없습니다.','WIP-0522 : Der fixe Grenzwert muss nicht eingegeben werden, wenn Produktspezifikationen genutzt werden.','ADMIN','20130205101119',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0523','WIP','WIP-0523 : Some BIN GRADE for BIN UNIT exists. So BIN UNIT can not be deleted.','WIP-0523 : 이 BIN UNIT 에 설정된 BIN GRADE 가 존재합니다. 따라서 BIN UNIT 을 삭제할 수 없습니다.','WIP-0523 : BIN GRADE im BIN UNIT existiert nicht. Daher kann BIN UNIT nicht geloescht werden.','ADMIN','20130205101648',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0524','WIP','WIP-0524 : Some BIN UNIT for BIN VERSION exists. So BIN VERSION can not be deleted.','WIP-0524 : 이 BIN VERSION 에 설정된 BIN UNIT 이 존재합니다. 따라서 BIN VERSION 을 삭제할 수 없습니다.','WIP-0524 : BIN UNIT existiert in dieser BIN VERSION nicht. Daher kann BIN VERSION nicht geloescht werden,','ADMIN','20130205101909',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0525','WIP','WIP-0525 : Some BIN GRADE for BIN VERSION are exist. So can not delete BIN VERSION.','WIP-0525 : 이 BIN VERSION 에 설정된 BIN GRADE 가 존재합니다. 따라서 BIN VERSION 을 삭제할 수 없습니다.','WIP-0525 : BIN GRADE existiert in dieser BIN VERSION nicht. Daher kann BIN GRADE nicht geloescht werden.','ADMIN','20130205102021',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0526','WIP','WIP-0526 : Canceling approval is only allowed on approved BIN VERSION.','WIP-0526 : 승인 취소는 이미 승인된 VERSION 에서만 처리 가능합니다.','WIP-0526 : Stornierung der Genehmigung kann nur in der bereits genehmigten Version erfolgen.','ADMIN','20130205102618',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0527','WIP','WIP-0527 : The specified apply end time is prior than apply start time. Please check the apply start and end time.','WIP-0527 : 버전의 적용 만료 날짜가 적용 시작 날짜 이전입니다. 만료 날짜를 시작날짜 이후로 수정해 주세요.','WIP-0527 : Ablauftag der Version ist auf den Starttag der Anwendung versetzt. Bitte setzen Sie den Ablauftag nach den Starttag.','ADMIN','20130205102858',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0528','WIP','WIP-0528 : When processing approval or release, cancel approval for BIN VERSION, apply time can"t be updated.','WIP-0528 : 버전에 대한 승인, 배포 또는 승인 취소 처리시에는 적용 시간을 함께 처리할 수 없습니다.','WIP-0528 : Die Anwendungszeit kann nicht gleichzeitig aktualisiert werden, wenn die Genehmigung, Verteilung oder die Genehmigungsaufhebung durchgefuehrt wird.','ADMIN','20130205103703',' ',' ');                
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0529','WIP','WIP-0529 : "Cancel Approval" for BIN VERSION can"t be processed with approval or release.','WIP-0529 : 버전에 대한 승인 취소 처리시에는 승인 및 배포와 함께 처리할 수 없습니다.','WIP-0529 : Genehmigung und Verteilung koennen nicht zusammen ausgefuehrt werden, wenn die Genehmigungsaufhebung durchgefuehrt wird.','ADMIN','20130205103919',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0530','WIP','WIP-0530 : The BIN requires approval for the version. Please release this version after approval.','WIP-0530 : 버전에 대한 승인이 필수인 BIN 입니다. 먼저 승인 처리 후 배포해 주십시오.','WIP-0530 : BIN der Version muss genehmigt werden. Bitte um Zuteilung nach der Genehmigung.','ADMIN','20130205104535',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0531','WIP','WIP-0531 : Current user does not have the authority of version approval.','WIP-0531 : 현 사용자는 버전에 대한 승인을 처리할 권한이 없습니다.','WIP-0531 : Der aktuelle Benutzer ist nicht authorisiert, die Version zu genehmigen.','ADMIN','20130205104849',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0532','WIP','WIP-0532 : The priority control does not exist.','WIP-0532 : 이 우선순위 설정은 존재하지 않습니다.','WIP-0532 : Die Prioritatskontrolle existiert nicht.','ADMIN','20130205110804',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0533','WIP','WIP-0533 : The priority control already exists.','WIP-0533 : 이 우선순위 설정은 이미 존재합니다.','WIP-0533 : Die Prioritatskontrolle existiert bereits.','ADMIN','20130205111944',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0534','WIP','WIP-0534 : BIN history for the lot doesn"t exist.','WIP-0534 : 이 LOT 에 대한 BIN 이력이 존재하지 않습니다.','WIP-0534 : Die BIN History fuer das Los existiert nicht.','ADMIN','20130216140123',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0535','WIP','WIP-0535 : BIN history for the sublot doesn"t exist.','WIP-0535 : 이 SUBLOT 에 대한 BIN 이력이 존재하지 않습니다.','WIP-0535 : Die BIN History fuer das sublot existiert nicht.','ADMIN','20130216140257',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0536','WIP','WIP-0536 : Low yield has been issued at BIN data of the lot.','WIP-0536 : 이 LOT 에 대한 BIN 데이터에서 저수율이 발생하였습니다.','WIP-0536 : Ein geringer Ertrag wurde in den BIN Daten dieses Los'' erzielt.','ADMIN','20130216140613',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0537','WIP','WIP-0537 : Processing sublots still exist, Please try again after all processing sublot completes.','WIP-0537 : 아직 진행중인 SUBLOT 이 존재합니다. 모든 SUBLOT 이 작업완료한 이후 다시 실행해 주십시오,','WIP-0537 : Das aktuell in Bearbeitung stehende Sublot existiert. Bitte erneut durchfuehren, nachdem alle Sublot abgewickelt wurden.','ADMIN','20130216205152',' ',' ');                  
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0538','WIP','WIP-0538 : Complete sublots doesn"t exist, Please try again after all processing sublot completes.','WIP-0538 : 작업완료된 SUBLOT 이 존재하지 않습니다. 모든 SUBLOT을 작업완료한 이후 다시 실행해 주십시오,','WIP-0538 : Das fertige Sublot ist nich vorhanden. Bitte erneut durchfuehren, nachdem alle Sublot abgewickelt wurden.','ADMIN','20130216205511',' ',' ');                  
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0539','WIP','WIP-0539 : Not allowed BIN Management feature in this factory. Please check Global option.','WIP-0539 : 이 공장에서는 BIN 관리 기능을 사용할 수 없습니다. Global Option 을 확인해 주십시오.','WIP-0539 : In diesem Werk kann die BIN Management Funktion nicht genutzt werden. Bitte ueberpruefen Sie die Global Option.','ADMIN','20130227235305',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0540','WIP','WIP-0540 : BIN history for inputted lot doesn"t exist.','WIP-0540 : 입력된 LOT 의 BIN 이력이 존재하지 않습니다.','WIP-0540 : BIN History fuer das eingegebene Los existiert nicht.','ADMIN','20130227235548',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0541','WIP','WIP-0541 : BIN History Sequence of inputted lot is deleted.','WIP-0541 : 입력된 LOT 의 BIN 이력 순번은 삭제 되었습니다.','WIP-0541 : BIN History Sequenz fuer das eingetragene Los wurde geloescht.','ADMIN','20130227235908',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0542','WIP','WIP-0542 : The lot does not pass BIN Management Process.','WIP-0542 : 입력된 LOT은 BIN 데이터 저수율 관리를 통과하지 못했습니다.','WIP-0542 : Das eingegebene Los konnte das BIN Daten Management nicht durchfuehren.','ADMIN','20130228000528',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0543','WIP','WIP-0543 : This lot has no data which has passed BIN Management Process.','WIP-0543 : 이 LOT은 BIN 저수율 통과된 데이터가 존재하지 않습니다.','WIP-0543 : Dieses Los verfuegt ueber keine Daten, welche das Bin Datenmanagement durchlaufen hat.','ADMIN','20130228000823','ADMIN','20130228002318');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0544','WIP','WIP-0544 : Test Program Setup does not exist for this Lot.','WIP-0544 : 선택된 Lot에 맞는 테스트 프로그램 설정이 존재하지 않습니다.','WIP-0544 : Das TEST PROGRAM Setup, welches zum ausgewaehlten Los passt, existiert nicht.','ADMIN','20130304152750',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0545','WIP','WIP-0545 : TEST Program Version is already approved or released. It can''t be updated.','WIP-0545 : 이 테스트 프로그램 버전은 이미 승인 또는 배포되어 변경이 불가능 합니다.','WIP-0545 : Diese TEST PROGRAM Version wurde bereits genehmigt oder verteilt. Keine Aenderungen mehr moeglich.','ADMIN','20130313153926',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0546','WIP','WIP-0546 : The count of requested ID exceeds the maximum count of generation ID.','WIP-0546 : 요청된 ID 생성 개수가 최대 생성 가능한 ID 개수를 초과 하였습니다.','WIP-0546 : Die maximale Anzahl der ID Erstellung wurde ueberschritten.','ADMIN','20130405151422',' ',' ');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0310','RAS','RAS-0310 : Tool Event change flag must be ''Y''(Change) ''N''(Not Change), ''+''(Plus), ''-''(Minus), ''*''(Multiply), ''/''(Division), ''mod''(MOD), ''pow''(POW) or ''R'' (Reset) or ''T'' (Time).', 'RAS-0310 : TOOL EVENT의 Change Flag 값은  ''Y''(변경) ''N''(변경안함), ''+''(더하기), ''-''(빼기), ''*''(곱하기), ''/''(나누기), ''mod''(MOD), ''pow''(POW), ''R'' (초기화), ''T'' (Time)만 사용할 수 있습니다.', 'RAS-0310 : Change Flag Wert des TOOL EVENT kann nur ''Y''(Wechsel)''N''(Kein Wechsel),''+''(Plus),''-''(Minus),''*''(Multiplizieren),''/''(Dividieren),''mod''(MOD),''pow''(POW),''R''(Voreinstellen),''T''(Time)benutzen.', 'ADMIN', '20130425155134', 'ADMIN', '20130529143542');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0055','BAS','BAS-0055 : This Checklist already exists.','BAS-0055 : 이미 존재하는 체크리스트입니다.','BAS-0055 : Dieses Checklist existiert bereits.','ADMIN','20130509140350','ADMIN','20130509140505');                   
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0056','BAS','BAS-0056 : This Checklist does not  exist.','BAS-0056 : 존재하지 않는 체크리스트입니다.','BAS-0056 : Dieses Checklist existiert nicht.','ADMIN','20130509140426','ADMIN','20130509140516'); 
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0547', 'WIP', 'WIP-0547 : This is the highest priority.', 'WIP-0547 : 이미 최상위 우선순위입니다.', 'WIP-0547 : Dies ist die hoechste Prioritaet.', 'ADMIN', '20130527104922', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0548', 'WIP', 'WIP-0548 : This is the lowest priority.', 'WIP-0548 : 이미 최하위 우선순위입니다.', 'WIP-0548 : Dies ist die niedrigste Prioritaet.', 'ADMIN', '20130527104947', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0311', 'RAS', 'RAS-0311 : When CHANGE FLAG is ''+''(plus), ''-''(minus), ''*''(multiply), ''/''(divide), ''mod''(MOD), ''pow''(POW), CHANGE FIELD must be TOOL_STATUS_1 ~ TOOL_STATUS_30', 'RAS-0311 : CHANGE FLAG가 ''+''(더하기), ''-''(빼기), ''*''(곱하기), ''/''(나누기), ''mod''(MOD), ''pow''(POW) 일 때 CHANGE FIELD는 TOOL_STATUS_1 ~ TOOL_STATUS_30 만 가능합니다.', 'RAS-0311 : CHANGE FIELD kann nur TOOL_STATUS_1 ~ TOOL_STATUS_30 sein, wenn CHANGE FLAG ''+''(plus), ''-''(minus), ''*''(multiplizieren), ''/''(dividieren), ''mod''(MOD), ''pow''(POW) ist.', 'ADMIN', '20130529140654', 'ADMIN', '20130529141118');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0312', 'RAS', 'RAS-0312 : Data format of CHANGE FIELD is incompatible with CHANGE FLAG.', 'RAS-0312 : CHANGE FIELD의 데이타 형식이 CHANGE FLAG 값과 호환되지 않는 형식입니다.', 'RAS-0312 : Datenformat des CHANGE FIELD ist unvereinbar mit dem CHANGE FLAG Wert.', 'ADMIN', '20130529143101', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0313', 'RAS', 'RAS-0313 : It can''t exceed the date size of CHANGE ITEM.', 'RAS-0313 : CHANGE ITEM 의 데이터 크기를 초과할 수 없습니다.', 'RAS-0313 : Die Datengroesse des CHANGE ITEM kann nicht ueberschritten werden.', 'ADMIN', '20130529145424', 'ADMIN', '20130529152835');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0314', 'RAS', 'RAS-0314 : Tool relation doesn''t exist in this MFO or Resource.', 'RAS-0314 : 이 MFO 또는 장비에 설정된 Tool Relation 이 존재하지 않습니다.', 'RAS-0314 : Die definierte Toolbeziehung existiert weder im MFO noch im Equipment.', 'ADMIN', '20130529153538', 'ADMIN', '20130531104052');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0315', 'RAS', 'RAS-0315 : Tool relation already exists in this MFO or Resource.', 'RAS-0315 : 이 MFO 또는 장비에 Tool Relation이 이미 존재합니다.', 'RAS-0315 : Eine Toolbeziehung existiert bereits in diesem MFO oder Equipment.', 'ADMIN', '20130529153559', 'ADMIN', '20130531104118');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('SEC-0053', 'SEC', 'SEC-0053 : The maximum count of Simultaneous User in Licenses for this Server has been exceeded.', 'SEC-0053 : 라이센스에서 허용하는 최대 사용자수를 초과하였습니다.', 'SEC-0053 : Die in der Lizenz maximal erlaubte Benutzeranzahl wurde ueberschritten.', 'ADMIN', '20130415131348', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('SEC-0054', 'SEC', 'SEC-0054 : Login has been succeeded. But a number of users has exceeded the limitation. Please be careful.', 'SEC-0054 : 로그인에 성공했습니다. 하지만 사용자 수 제한을 초과하였습니다. 주의하여 주십시요.', 'SEC-0053 : Anmeldung war erfolgreich. Die Benutzeranzahl wurde jedoch ueberschritten. Bitte geben Sie Acht.', 'ADMIN', '20130515135118', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('SEC-0055', 'SEC', 'SEC-0055 : The server has been expired.', 'SEC-0055 : 서버의 유효기간이 만료되었습니다.', 'SEC-0055 : Der Server ist abgelaufen.', 'ADMIN', '20130523111024', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0044', 'WEM', 'WEM-0044 : Some Statuses are used on Steps. Therefore, they can not be deleted from Work Process Type.', 'WEM-0044 : 스텝에서 사용하는 상태값이 존재합니다. 따라서 현재의 업무처리 타입을 삭제할 수 없습니다.', 'WEM-0044 : Manche Zustande sind auf Schritte verwendet. Daher kann es den Arbeitsprozesstyp nicht loschen.', 'ADMIN', '20130719141503', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0045', 'WEM', 'WEM-0045 : Work Process Type has some Steps. Please try again after deleting all Steps from Work Process Type first.', 'WEM-0045 : 업무처리 타입에 속한 스텝이 존재합니다. 먼저 업무처리 타입내의 스텝을 모두 제거후 실행해 주십시오.', 'WEM-0045 : Arbeitsprozess Typ hat einige Schritte. Bitte versuchen Sie es erneut, nachdem alle Schritte des Arbeitsprozesstyps geloscht zuerst wurden.', 'ADMIN', '20130719145006', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0046', 'WEM', 'WEM-0046 : Work Process Type has some Statuses. Please try again after deleting all Statuses from Work Process Type first.', 'WEM-0046 : 업무처리 타입에 속한 상태값이 존재합니다. 먼저 업무처리 타입내의 상태값을 모두 제거후 실행해 주십시오.', 'WEM-0046 : Arbeitsprozess Typ hat einige Zustande. Bitte versuchen Sie es erneut, nachdem alle Zustande des Arbeitsprozesstyps geloscht zuerst wurden.', 'ADMIN', '20130719145150', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0047', 'WEM', 'WEM-0047 : Work Process Type has some Processes. Please try again after deleting all Processes from Work Process Type first.', 'WEM-0047 : 업무처리 타입에 속한 프로세스가 존재합니다. 먼저 업무처리 타입내의 프로세스를 모두 제거후 실행해 주십시오.', 'WEM-0047 : Arbeitsprozess Typ hat einige Prozesse. Bitte versuchen Sie es erneut, nachdem alle Prozesse des Arbeitsprozesstyps geloscht zuerst wurden.', 'ADMIN', '20130719145400', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0048', 'WEM', 'WEM-0048 : Work Process Type has some Actions. Please try again after deleting all Actions from Work Process Type first.', 'WEM-0048 : 업무처리 타입에 속한 액션이 존재합니다. 먼저 업무처리 타입내의 액션을 모두 제거후 실행해 주십시오.', 'WEM-0048 : Arbeitsprozess Typ hat einige Aktionen. Bitte versuchen Sie es erneut, nachdem alle Aktionen des Arbeitsprozesstyps geloscht zuerst wurden. ', 'ADMIN', '20130719145507', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0316', 'RAS', 'RAS-0316 : Resource group must have at least one Resource.', 'RAS-0316 : 장비 그룹에는 최소 한개 이상의 장비가 있어야 합니다.', 'RAS-0316 : Ressourcen-Gruppe muss uber mindestens eine Ressource verfugen.', 'ADMIN', '20130405151422', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0057', 'BAS', 'BAS-0057 : This upgrade file does not exist.', 'BAS-0057 : 이 업그레이트 파일은 존재하지 않습니다.', 'BAS-0057 : Diese Upgrade-Datei exisitiert nicht.', 'ADMIN', '20130620111607', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0058', 'BAS', 'BAS-0058 : This batch job processor ID does not exist', 'BAS-0058 : 이 배치 작업 프로세스 ID는 존재하지 않습니다.', 'BAS-0058 : Diese Batch-Job-Prozessor ID existiert nicht ', 'ADMIN', '20130820160340', 'ADMIN', '20130822202016');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0059', 'BAS', 'BAS-0059 : This batch job processor ID  already exists.', 'BAS-0059 : 이 배치 작업 프로세스 ID는 이미 존재 합니다.', 'BAS-0059 : Diese Batch-Job-Prozessor-ID existiert bereits.', 'ADMIN', '20130821102405', 'ADMIN', '20130822202035');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0549', 'WIP', 'WIP-0549 : This ID is confirmed that it is already in use. Please use another ID.', 'WIP-0549 : 이미 사용처리된 ID 입니다. 다른 ID 를 사용해 주십시오.', 'WIP-0549 : Diese ID ist bereits zur Verwendung freigegeben. Bitte benutzen Sie eine andere ID. ', 'ADMIN', '20130902132646', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0550', 'WIP', 'WIP-0550 : The ID can not be confirmed if it is in use, because the ID does not exist in ID Generator History.', 'WIP-0550 : 입력된 ID 는 생성 이력이 존재하지 않아 사용확인할 수 없습니다.', 'WIP-0550 : Die ID kann nicht bestaetigt werden, wenn sie bereits verwendet wird, da die ID nicht in den Eintragungen (Generator History) existiert.', 'ADMIN', '20130902134837', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0551', 'WIP', 'WIP-0551 : The ID does not exist in Generator history.', 'WIP-0551 : 입력된 ID 는 생성 이력이 존재하지 않습니다.', 'WIP-0551 : Diese ID existiert nicht in den Eintragungen (Generator History).', 'ADMIN', '20130903140538', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WEM-0049', 'WEM', 'WEM-0049 : This Action ID is used on some Steps. Please try again after deleting all relations with Step first.', 'WEM-0049 : 이 액션은 스탭의 액션으로 사용되고 있습니다. 먼저 스탭에서 사용중인 이 액션을 모두 제거후 실행해 주십시오.', 'WEM-0049 : Die Action ID ist auf mehrere Schritte angewandt. Bitte versuchen Sie es erneut, nachdem alle Beziehungen mit dem Schritt geloscht zuerst wurden.', 'ADMIN', '20130906135223', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0552', 'WIP', 'WIP-0552 : No data was found to be changed. Please input some data.', 'WIP-0552 : 수정될 데이타가 하나도 없습니다. 최소 한개의 데이타를 입력해 주세요.', 'WIP-0552 : Es wurden keine Daten zum Bearbeiten gefunden. Ueberpruefen Sie die Eingabe.', 'ADMIN', '20140213133036', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0553', 'WIP', 'WIP-0553 : This service is successful. But this lot exceeds the queue time. Please check lot.', 'WIP-0553 : 작업을 성공적으로 수행하였습니다, 그러나 이 Lot은 Queue Time 설정 시간이 지났습니다. Lot을 확인하세요.', 'WIP-0553 : Service wurde erfolgreich ausgefuehrt. Aber die Queue-Time fuer dieses Los ist ueberschritten.', 'ADMIN', '20140522113006', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0060', 'BAS', 'BAS-0060 : Please enter a value which is smaller than 1000 to attribute value size.', 'BAS-0060 : Attribute 값의 크기로 1000 이하의 값을 입력해 주세요', 'BAS-0060 : Bitte geben Sie einen Wert von weniger als 1000.', 'ADMIN', '20140522161130', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('SEC-0056', 'SEC', 'SEC-0056 : The license does not allow the services of this module.', 'SEC-0056 : 이 모듈의 서비스는 라이센스에서 허용하지 않습니다.', 'SEC-0056 : Die Dienste von diesem Modul sind anhand der Lizenz nicht erlaubt.', 'ADMIN', '20140529123257', 'ADMIN', '20140529123705');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0061', 'BAS', 'BAS-0061 : In CALENDAR TYPE, either "F (FACTORY)" or "W (WORK)" is only allowed.', 'BAS-0061 : CALENDAR TYPE는 "F(FACTORY)" 또는 "W(WORK)"만 허용 됩니다.', 'BAS-0061 : Im Kalendertyp ist entweder "F (FACTORY)" oder "W (WORK)" ist erlaubt.', 'ADMIN', '20140529123257', 'ADMIN', '20140717101708');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0062', 'BAS', 'BAS-0062 : Answer history of checklist does not exist.', 'BAS-0062 : 체크리스트 답변 이력이 존재하지 않습니다.', 'BAS-0062 : Die History ist nicht vorhanden.', 'ADMIN', '20140529123257', 'ADMIN', '20140717102128');
