INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0066', 'BAS', 'BAS-0066 : This template is not included in the document format.', 'BAS-0066 : 이 문서 템플릿은 문서 포맷에 존재하지 않습니다.', 'BAS-0066 : Diese Vorlage ist nicht im Dokument-Format enthalten.', 'ADMIN', '20140529123257', 'ADMIN', '20140717102640');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0067', 'BAS', 'BAS-0067 : This template is already included in the document format.', 'BAS-0067 : 이 문서 템플릿은 문서 포맷에 이미 포함되어 있습니다.', 'BAS-0067 : Diese Vorlage ist bereits im Dokument-Format enthalten.', 'ADMIN', '20140529123257', 'ADMIN', '20140717102745');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0068', 'BAS', 'BAS-0068 : In GROUP CATEGORY, "Setup", "Transaction" or "Inquiry" is only allowed.', 'BAS-0068 : Menu Group Category 는 "Setup", "Transaction" 또는 "Inquiry"만 허용됩니다.', 'BAS-0068 : In Group Category ist nur "Setup", "Transaction" oder "Inquiry" erlaubt.', 'ADMIN', '20140529123257', 'ADMIN', '20140717102943');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0554', 'WIP', 'WIP-0554 : Cancelling approval is only allowed on approved Version.', 'WIP-0554 : 승인 취소는 이미 승인된 VERSION 에서만 처리 가능합니다.', 'WIP-0554 : Genehmigung einer Absage ist nur auf die zugelassene Version erlaubt.', 'ADMIN', '20140710161713', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0555', 'WIP', 'WIP-0555 : The version is already released. ''Cancel Approval'' can''t be processed.', 'WIP-0555 : 이 버전은 이미 배포되었으므로 승인 취소가 불가능 합니다.', 'WIP-0555 : Die Version ist bereits freigegeben. Es kann die Genehmigung nicht stornieren.', 'ADMIN', '20140710162435', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0556', 'WIP', 'WIP-0556 : Invalid generation rule Type. Generation rule type should be "F", "V", "D", "S" or "B".', 'WIP-0556 : 유효하지 않은 발번 규칙 타입입니다. 발번 규칙 타입은 "F", "V", "D", "S", "B" 중 하나이어야 합니다.', 'WIP-0556 : Ungultige Generation Rule Typ. Generation Rule typ sollte "F", "V", "D", "S" oder "B" sein.', 'ADMIN', '20140714110846', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0069', 'BAS', 'BAS-0069 : "L(Lot)" or "R(Resource)" is only allowed for the flag "Lot or Resource".', 'BAS-0069 : Lot or Resource의 Flag값은 "L(Lot)" 또는 "R(Resource)"만 허용됩니다.', 'BAS-0069 : Wert von "Lot oder Ressource"  ist nur fur "L (Lot)" oder "R (Resource)" erlaubt.', 'ADMIN', '20140529123257', 'ADMIN', '20140529123705');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('GCM-0031', 'GCM', 'GCM-0031 : This Table use SQL Query to get data. Data for this table cannot be updated.', 'GCM-0031 : 이 테이블은 SQL 을 사용하므로 Data를 정의할 수 없습니다.', 'GCM-0031 : Diese Tabelle verwendet die SQL-Abfrage, um Daten zu erhalten. Daten fur diese Tabelle konnen nicht aktualisiert werden.', 'ADMIN', '20140801133510', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BOM-0041', 'BOM', 'BOM-0041 : "M(Material)" or "O(Order)" is only allowed for the "MAT_OR_ORD_FLAG" member.', 'BOM-0041 : MAT_OR_ORD_FLAG값은 "M(Material)" 또는 "O(Order)"만 허용됩니다.', 'BOM-0041 : "M (Material)" oder "O (Order)" ist nur fur "MAT_OR_ORD_FLAG" Mitglieder erlaubt.', 'ADMIN', '20140804130351', 'ADMIN', '20140905100017');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0070', 'BAS', 'BAS-0070 : "B(Before)" or "A(After)" is only allowed for the flag "BA Point".', 'BAS-0070 : BA Point의 Flag값은 "B(Before)" 또는 "A(After)"만 허용됩니다.', 'BAS-0070 : "B (Vorher)" oder "A (Nachher)" ist nur fur die Flagge "BA Point" erlaubt.', 'ADMIN', '20140805093443', 'ADMIN', '20140905100128');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('CMN-0017', 'CMN', 'CMN-0017 : Option level is invalid.', 'CMN-0017 : 유효하지 않은 "Option Level"입니다', 'CMN-0017 : Option Level ist ungultig.', 'ADMIN', '20140807153300', 'ADMIN', '20140905100229');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0090', 'EDC', 'EDC-0090 : "L(Lot)", "R(Resource)" or "B(Both" is only allowed for the flag "LOT_OR_RES_FLAG".', 'EDC-0090 : "LOT_OR_RES_FLAG"의 값은 "L(Lot)", "R(Resource)" 혹은 "B(Both)"만 허용됩니다.', 'EDC-0090 : "L (Lot)", "R (Resource)" oder "B (Beide)" ist nur fur die Flagge "LOT_OR_RES_FLAG" erlaubt.', 'ADMIN', '20140806130326', 'ADMIN', '20140905100342');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0091', 'EDC', 'EDC-0091 : This collection set version has been already approved.', 'EDC-0091 : 이 콜렉션 셋에 대한 버전은 이미 승인되었습니다.', 'EDC-0091 : Diese "COLLECTION SET" Version wurde bereits genehmigt.', 'ADMIN', '20140807162045', 'ADMIN', '20140905101445');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0092', 'EDC', 'EDC-0092 : This collection set version has been already released.', 'EDC-0092 : 이 콜렉션 셋에 대한 버전은 이미 배포되었습니다.', 'EDC-0092 : Diese "COLLECTION SET" Version wurde bereits freigegeben.', 'ADMIN', '20140807162338', 'ADMIN', '20140905101436');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0093', 'EDC', 'EDC-0093 : The approval process for this collection set version has not been processed, so that approval cancelation cannot be done.', 'EDC-0093 : 이 콜렉션 셋에 대한 버전은 승인 처리가 되지 않아, 승인 취소를 진행할 수 없습니다.', 'EDC-0093 : Das Genehmigungsverfahren fur diese "COLLECTION SET" Version wurde noch nicht bearbeitet, so dass die Zulassungsstornierung nicht durchgefuhrt werden kann.', 'ADMIN', '20140807162624', 'ADMIN', '20140905101426');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0094', 'EDC', 'EDC-0094 : This collection set version has been already released. The approval cancelation cannot be processed.', 'EDC-0094 : 이 콜렉션 셋에 대한 버전은 이미 배포되어, 승인 취소를 진행할 수 없습니다.', 'EDC-0094 : Diese "COLLECTION SET" Version wurde bereits freigegeben. Die Zulassungsstornierung kann nicht bearbeitet werden.', 'ADMIN', '20140807162735', 'ADMIN', '20140905101253');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0095', 'EDC', 'EDC-0095 : The Flag value for this approval process is invalid. Please input ''Y'' value at "APPROVAL_FLAG" member to approval this collection set.', 'EDC-0095 : 승인을 처리하기 위한 Flag의 값이 올바르지 않습니다. 승인을 처리하려면 "APPROVAL_FLAG" 에 "Y"를 입력해 주십시요.', 'EDC-0095 : Der Flag-Wert fur dieses Genehmigungsverfahren ist ungultig. Bitte geben Sie den ''Y'' Wert bei "APPROVAL_FLAG" ein, um das "COLLECTION SET" zu genehmigen.', 'ADMIN', '20140807164222', 'ADMIN', '20140905100935');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0096', 'EDC', 'EDC-0096 : Invalid value of "RELEASE_FLAG" member. Please input ''Y'' value at "RELEASE_FLAG" member to release this collection set.', 'EDC-0096 : 배포를 처리하기 위한 Flag의 값이 올바르지 않습니다. 배포를 처리하려면 "RELEASE_FLAG" 에 "Y"를 입력해 주십시요.', 'EDC-0096 : Ungultiger Wert von "RELEASE_FLAG". Bitte geben Sie den ''Y'' Wert bei "RELEASE_FLAG" ein, um das "COLLECTION SET" freizugeben.', 'ADMIN', '20140807164403', 'ADMIN', '20140905100831');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('EDC-0097', 'EDC', 'EDC-0097 : "A(Automatic Mode)" or "M(Manual Mode)" is only allowed for the flag "COLLECTION_MODE".', 'EDC-0097 : "COLLECTION_MODE"의 값은 "A(Automatic Mode"와 "M(Manual Mode)"만 허용합니다.', 'EDC-0097 : "A (Automatikmodus)" oder "M (Manuell-Modus)" ist nur fur die Flagge "COLLECTION_MODE" erlaubt.', 'ADMIN', '20140808111444', 'ADMIN', '20140905100512');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('ALM-0036', 'ALM', 'ALM-0036 : Invalid alarm transaction point value. Alarm Transaction Point must be "S", "P", "E", "R", "1", "2", "3" or "4".', 'ALM-0036 : 유효하지 않는 Transaction Point 입니다. Transaction Point는  "S", "P", "E", "R", "1", "2", "3", "4" 중 하나이어야 합니다.', 'ALM-0036 : Ungueltiger Wert fuer Alarm-Transaction-Point-Value. Gueltige Werte sind "S", "P", "E", "R", "1", "2", "3" oder "4".', 'ADMIN', '20071213054449', 'ADMIN', '20150120103954');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0071', 'BAS', 'BAS-0071 : The material that having duplicate flow exists. In order to change the value of this option, Material must not duplicated flow.', 'BAS-0071 : 중복된 Flow 를 가진 Material 이 존재합니다. 이 옵션값을 변경하기 위해서는 Material 에 중복된 Flow 가 없어야 합니다.', 'BAS-0071: Material mit einem doppelten Flow liegt vor. Um den Wert dieser Option zu andern, darf kein doppelter Flow im Material vorliegen.', 'ADMIN', '20140611111236', 'ADMIN', '20161122094836');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('BAS-0072', 'BAS', 'BAS-0072 : This factory that having the lot exists. In order to change the value of this option, Factoryl must not had lot.', 'BAS-0072 : 이 공장에 LOT 이 존재합니다. 이 옵션값을 변경하기 위해서는 공장내에 LOT 가 없어야 합니다.', 'BAS-0072: Das Los ist im Prozess vorhanden. Um den Wert dieser Option zu andern, darf kein Los innerhalb des Prozesses vorhanden sein.', 'ADMIN', '20151203105219', 'ADMIN', '20161122094938');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0557', 'WIP', 'WIP-0557 : Lot Status is invalid to ABORT_START.'  , 'WIP-0557 : 이 Lot은 ABORT_START를 실행할 수 없는 상태입니다.', 'WIP-0557 : Der Los Zustand verhindert eine Ausfuehrung von ABORT_START.', 'ADMIN', '201508010800', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0558', 'WIP', 'WIP-0558 : Can not copy material-flow relation. Flow does not exist in target factory.', 'WIP-0558 : 제품-플로우 관계정보를 복사할 수 없습니다. 보낼 공장엔 플로우가 없습니다.', 'WIP-0558 : Die Product-Flow Beziehungsinformationen koennen nicht kopiert werden. Flow existiert nicht.', 'ADMIN', '20150924124535', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('WIP-0559', 'WIP', 'WIP-0559 : Can not copy flow-operation relation. Operation does not exist in target factory.', 'WIP-0559 : 플로우-공정 관계정보를 복사할 수 없습니다. 보낼 공장엔 공정이 없습니다.', 'WIP-0559 : Die Flow-Operation Beziehungsinformationen koennen nicht kopiert werden. Operation existiert nicht.', 'ADMIN', '20150924124544', ' ', ' ');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('GCM-0032', 'GCM', 'GCM-0032 : The valid count is between 1 and 20.', 'GCM-0032 : SIZE는 1보다 크고 20 보다 작거나 같아야 합니다.', 'GCM-0032 : Der gueltige Zahlwert liegt zwischen 1 und 20.', 'ADMIN', '20081201010101', 'ADMIN', '20120203164813');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0317', 'RAS', 'RAS-0317 : Invalid Process Mode. "MANUAL, SEMI AUTO, FULL AUTO" mode only allowed.', 'RAS-0317 : 잘못된 프로세스 모드입니다. "MANUAL, SEMI AUTO, FULL AUTO" 모드만 가능합니다.', 'RAS-0317: Ungultiger Prozessmodus. Nur "Manuell, AUTO, FULL AUTO" - Modus erlaubt.', 'ADMIN', '20161111141430', 'ADMIN', '20161122095048');
INSERT INTO MMSGMSGDEF(MSG_ID, MSG_GRP, MSG_1, MSG_2, MSG_3, CREATE_USER_ID, CREATE_TIME, UPDATE_USER_ID, UPDATE_TIME) VALUES('RAS-0318', 'RAS', 'RAS-0318 : Invalid Control Mode. "OL, OR, OF" mode only allowed.', 'RAS-0318 : 잘못된 콘트롤 모드입니다. "OL, OR, OF" 모드만 가능합니다.', 'RAS-0318 : Ungultiger Kontrol Modus. Nur "OL, OR, OF" Modus erlaubt.', 'ADMIN', '20161111142015', 'ADMIN', '20161122095146');
